# 「今日実際に強化中」= 既存 DIFF_REAL_STRENGTH=1 の集合をそのまま使用する。
# この履歴は表示/研究専用。候補選定・priority・TODAY_BUY・LIVE50・売買判定へ逆流させない。
# ==============================================================================

_MARKET_BREADTH_FIELDS = [
    "trade_date", "captured_at",
    "active_count", "prev_active_count", "peak_count", "count_retention_pct",
    "peak_survivor_count", "peak_survival_pct", "rotation_prev_pct",
    "entrants_prev", "dropouts_prev", "entrants_since_peak", "dropouts_since_peak",
    "peak_captured_at", "regime_code", "regime_label", "warning", "source",
]


def _market_breadth_codes_from_json(value) -> set[str]:
    try:
        raw = json.loads(str(value or "[]"))
    except Exception:
        return set()
    if not isinstance(raw, list):
        return set()
    out = set()
    for x in raw:
        c = str(canonical_code_for_db(x) or "").strip().upper()
        if c and _is_jp_stock_snapshot_code(c):
            out.add(c)
    return out


def _market_breadth_active_codes(rows: list[dict]) -> set[str]:
    """既存の『今日実際に強化中』集合だけを抽出。判定条件はここで再定義しない。"""
    out = set()
    for r in rows or []:
        try:
            flag = int(_live_num(_live_get(r, "DIFF_REAL_STRENGTH", "diff_real_strength")) or 0)
        except Exception:
            flag = 0
        if flag != 1:
            continue
        c = str(canonical_code_for_db(_live_get(r, "コード", "code")) or "").strip().upper()
        if c and _is_jp_stock_snapshot_code(c):
            out.add(c)
    return out


def _market_breadth_regime(prev_exists: bool, active_count: int, peak_count: int,
                           count_retention_pct, peak_survival_pct, rotation_prev_pct):
    # UIの30/50/70%補助線と整合する表示専用の状態ラベル。
    if not prev_exists or peak_count <= 0:
        return "DATA", "履歴形成中", ""
    vals = [x for x in (_live_num(count_retention_pct), _live_num(peak_survival_pct)) if x is not None]
    core = min(vals) if vals else None
    if core is None:
        code, label = "DATA", "履歴形成中"
    elif core >= 70.0:
        code, label = "GREEN", "持続優勢"
    elif core >= 50.0:
        code, label = "YELLOW", "選別継続"
    elif core >= 30.0:
        code, label = "ORANGE", "失速警戒"
    else:
        code, label = "RED", "持続崩れ"

    warning = ""
    rot = _live_num(rotation_prev_pct)
    if active_count <= 0 and peak_count > 0:
        warning = "強化中0件"
    elif rot is not None and rot >= 60.0:
        warning = "直前runから入替大"
    return code, label, warning


def _market_breadth_prune(c: sqlite3.Connection, keep_trade_days: int = MARKET_BREADTH_HISTORY_KEEP_TRADE_DAYS) -> int:
    dates = [str(r[0]) for r in c.execute(
        "SELECT DISTINCT trade_date FROM market_breadth_history_v11 ORDER BY trade_date DESC"
    ).fetchall() if r and r[0]]
    if len(dates) <= int(keep_trade_days):
        return 0
    keep = set(dates[:int(keep_trade_days)])
    ph = ",".join("?" for _ in keep)
    before = c.total_changes
    c.execute(f"DELETE FROM market_breadth_history_v11 WHERE trade_date NOT IN ({ph})", tuple(sorted(keep)))
    return c.total_changes - before


def _market_breadth_capture_on_conn(c: sqlite3.Connection, rows: list[dict],
                                    captured_at: str, trade_date: str) -> dict:
    """有効MIDDAY snapshotで呼ばれる1点保存。DIFF_REAL_STRENGTHの集合以外は見ない。"""
    active = _market_breadth_active_codes(rows)
    active_count = len(active)

    prev = c.execute(
        """SELECT captured_at,active_count,peak_count,peak_captured_at,
                  active_codes_json,peak_codes_json
           FROM market_breadth_history_v11
           WHERE trade_date=? AND captured_at<?
           ORDER BY captured_at DESC LIMIT 1""",
        (trade_date, captured_at),
    ).fetchone()

    prev_exists = prev is not None
    prev_active = _market_breadth_codes_from_json(prev[4]) if prev else set()
    prev_active_count = int(prev[1] or 0) if prev else None
    prior_peak_count = int(prev[2] or 0) if prev else 0
    prior_peak_at = str(prev[3] or "") if prev else ""
    prior_peak_codes = _market_breadth_codes_from_json(prev[5]) if prev else set()

    # 当日ピークは「強化中件数」の最大値。新高値ならそのrunの集合を新しいpeak集合にする。
    if (not prev_exists) or active_count > prior_peak_count:
        peak_count = active_count
        peak_at = captured_at
        peak_codes = set(active)
    else:
        peak_count = prior_peak_count
        peak_at = prior_peak_at or captured_at
        peak_codes = set(prior_peak_codes)
        # legacy/異常行でpeak集合だけ欠けていた場合は、現在集合で捏造せず前run集合を補助に使う。
        if peak_count > 0 and not peak_codes and prev_active:
            peak_codes = set(prev_active)

    count_retention = round(active_count * 100.0 / peak_count, 1) if peak_count > 0 else None
    peak_survivors = len(active & peak_codes) if peak_count > 0 else 0
    peak_survival = round(peak_survivors * 100.0 / peak_count, 1) if peak_count > 0 else None

    if prev_exists:
        entrants_prev = len(active - prev_active)
        dropouts_prev = len(prev_active - active)
        union_n = len(active | prev_active)
        rotation_prev = round(len(active ^ prev_active) * 100.0 / union_n, 1) if union_n > 0 else 0.0
    else:
        entrants_prev = None
        dropouts_prev = None
        rotation_prev = None

    entrants_peak = len(active - peak_codes) if peak_count > 0 else 0
    dropouts_peak = len(peak_codes - active) if peak_count > 0 else 0
    regime_code, regime_label, warning = _market_breadth_regime(
        prev_exists, active_count, peak_count, count_retention, peak_survival, rotation_prev
    )

    vals = (
        captured_at, trade_date, active_count, prev_active_count, peak_count, count_retention,
        peak_survivors, peak_survival, rotation_prev, entrants_prev, dropouts_prev,
        entrants_peak, dropouts_peak, peak_at,
        json.dumps(sorted(active), ensure_ascii=False, separators=(",", ":")),
        json.dumps(sorted(peak_codes), ensure_ascii=False, separators=(",", ":")),
        regime_code, regime_label, warning, "DIFF_REAL_STRENGTH",
    )

    # 同一captured_at再実行だけ置換。旧legacy tableには書き込まない。
    c.execute(
        """INSERT OR REPLACE INTO market_breadth_history_v11(
             captured_at,trade_date,active_count,prev_active_count,peak_count,count_retention_pct,
             peak_survivor_count,peak_survival_pct,rotation_prev_pct,entrants_prev,dropouts_prev,
             entrants_since_peak,dropouts_since_peak,peak_captured_at,active_codes_json,peak_codes_json,
             regime_code,regime_label,warning,source
           ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        vals,
    )
    pruned = _market_breadth_prune(c)
    return {
        "status": "ok",
        "captured_at": captured_at,
        "trade_date": trade_date,
        "active_count": active_count,
        "peak_count": peak_count,
        "count_retention_pct": count_retention,
        "peak_survival_pct": peak_survival,
        "rotation_prev_pct": rotation_prev,
        "pruned": pruned,
        "source": "DIFF_REAL_STRENGTH",
    }


def _market_breadth_legacy_rows(c: sqlite3.Connection, trade_dates: list[str]) -> list[dict]:
    """残存旧tableを読み取り救済。UI必須の核だけあれば不足列はNoneで埋め、旧table自体は変更しない。"""
    if not trade_dates:
        return []
    core_required = {"trade_date", "captured_at", "active_count", "peak_count"}
    out = []
    try:
        names = [str(r[0]) for r in c.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'market_breadth%'"
        ).fetchall()]
    except Exception:
        return []

    for table in names:
        if table == "market_breadth_history_v11":
            continue
        if not re.fullmatch(r"[A-Za-z0-9_]+", table):
            continue
        try:
            cols = {str(r[1]) for r in c.execute(f"PRAGMA table_info({table})").fetchall()}
            if not core_required.issubset(cols):
                continue
            available = [k for k in _MARKET_BREADTH_FIELDS if k in cols]
            ph = ",".join("?" for _ in trade_dates)
            selected = ",".join(available)
            for rr in c.execute(
                f"SELECT {selected} FROM {table} WHERE trade_date IN ({ph}) ORDER BY captured_at",
                tuple(trade_dates),
            ).fetchall():
                d = {k: None for k in _MARKET_BREADTH_FIELDS}
                d.update(dict(zip(available, rr)))
                if not d.get("source"):
                    d["source"] = f"legacy:{table}"
                if not d.get("regime_code"):
                    d["regime_code"] = "DATA"
                if not d.get("regime_label"):
                    d["regime_label"] = "旧履歴"
                out.append(d)
        except Exception as e:
            print(f"[market-breadth][WARN] legacy table skipped {table}: {e}", flush=True)
    return out


def _market_breadth_dashboard_history_payload(trade_days: int = MARKET_BREADTH_DASHBOARD_TRADE_DAYS) -> dict:
    """直近N営業日のcompact履歴を既存UI schemaへ戻す。"""
    c = _live_snapshot_conn()
    try:
        # v11 + 読めるlegacy tableの営業日を合わせて取得。
        dates = [str(r[0]) for r in c.execute(
            "SELECT DISTINCT trade_date FROM market_breadth_history_v11 ORDER BY trade_date DESC"
        ).fetchall() if r and r[0]]

        # legacy側の日付も、schemaが読めるものだけ収集。
        try:
            names = [str(r[0]) for r in c.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'market_breadth%'"
            ).fetchall()]
            for table in names:
                if table == "market_breadth_history_v11" or not re.fullmatch(r"[A-Za-z0-9_]+", table):
                    continue
                cols = {str(r[1]) for r in c.execute(f"PRAGMA table_info({table})").fetchall()}
                if {"trade_date", "captured_at"}.issubset(cols):
                    dates.extend(str(r[0]) for r in c.execute(
                        f"SELECT DISTINCT trade_date FROM {table} ORDER BY trade_date DESC LIMIT ?",
                        (max(1, int(trade_days)),),
                    ).fetchall() if r and r[0])
        except Exception:
            pass

        trade_dates = sorted(set(dates), reverse=True)[:max(1, int(trade_days))]
        trade_dates = sorted(trade_dates)

        rows = []
        if trade_dates:
            ph = ",".join("?" for _ in trade_dates)
            selected = ",".join(_MARKET_BREADTH_FIELDS)
            # legacyを先に、v11を後に積む。同一captured_atならv11を正本として上書きする。
            rows.extend(_market_breadth_legacy_rows(c, trade_dates))
            rows.extend(dict(zip(_MARKET_BREADTH_FIELDS, rr)) for rr in c.execute(
                f"""SELECT {selected}
                    FROM market_breadth_history_v11
                    WHERE trade_date IN ({ph})
                    ORDER BY captured_at""",
                tuple(trade_dates),
            ).fetchall())

        by_ts = {}
        for r in rows:
            ts = str(r.get("captured_at") or "")
            if not ts:
                continue
            by_ts[ts] = r
        merged = sorted(by_ts.values(), key=lambda r: str(r.get("captured_at") or ""))

        compact = [[r.get(k) for k in _MARKET_BREADTH_FIELDS] for r in merged]
        current = merged[-1] if merged else None
        return {
            "schema_version": 1,
            "trade_dates": sorted({str(r.get("trade_date") or "") for r in merged if r.get("trade_date")}),
            "fields": list(_MARKET_BREADTH_FIELDS),
            "rows": compact,
            "current": current,
            "source": "scanner_snapshots.sqlite3/market_breadth_history_v11",
            "notes": {
                "retention": "市場継続率=現在の『今日実際に強化中』件数÷当日ピーク件数。",
                "peak_survival": "ピーク生存率=ピーク時の強化中銘柄のうち現在も残っている割合。",
                "rotation": "直前run入替率=直前runと現在runの銘柄集合の対称差÷和集合。100%ほど総入替。",
                "timing": "MIDDAYかつ市場時間内で、全銘柄snapshot品質gateを通過した実runだけ保存。",
                "gate": "集合の正本は既存DIFF_REAL_STRENGTH=1。表示/研究専用で売買判定へ逆流させない。",
            },
        }
    finally:
        c.close()

def _live_prune_snapshot_trade_days(c: sqlite3.Connection) -> int:
    dates=[r[0] for r in c.execute("SELECT DISTINCT trade_date FROM intraday_scanner_snapshot ORDER BY trade_date DESC").fetchall()]
    if len(dates) <= LIVE_SNAPSHOT_KEEP_TRADE_DAYS:
        return 0
    keep=set(dates[:LIVE_SNAPSHOT_KEEP_TRADE_DAYS])
    placeholders=','.join('?' for _ in keep)
    before=c.total_changes
    c.execute(f"DELETE FROM intraday_scanner_snapshot WHERE trade_date NOT IN ({placeholders})", tuple(sorted(keep)))
    return c.total_changes-before


def _live_is_market_snapshot_time(now=None) -> bool:
    """JPXの立会時間だけintraday snapshotとして採用する。

    PREOPEN・昼休み・大引け後の静止価格を10/20/30/60分特徴量へ混ぜない。
    11:30/15:30ちょうどは前場/大引けsnapshotとして許可する。
    休場日判定は本体の既存run gateへ委ね、ここでは時刻境界だけを担当する。
    """
    dt = now or _now_jst()
    try:
        minute = int(dt.hour) * 60 + int(dt.minute)
    except Exception:
        return False
    return (9 * 60 <= minute <= 11 * 60 + 30) or (12 * 60 + 30 <= minute <= 15 * 60 + 30)


def _is_jp_stock_snapshot_code(code) -> bool:
    c = str(canonical_code_for_db(code) or "").strip().upper()
    return bool(re.fullmatch(r"(?:\d{4}|\d{3}[A-Z])", c))


def _snapshot_stock_quality(rows: list[dict]) -> dict:
    """現在rowsの日本株coverageを判定。指数だけ/数銘柄だけのpartial runを正式snapshotにしない。"""
    expected = set()
    valid = set()
    for r in rows or []:
        code = _live_stock_code(
            _live_get(r, "コード", "code"),
            _live_get(r, "市場", "market"),
            _live_get(r, "銘柄名", "name"),
        )
        if not code:
            continue
        expected.add(str(code))
        px = _live_num(_live_get(r, "現在値_raw", "現在値", "current_price"))
        if px is not None and px > 0:
            valid.add(str(code))
    expected_n = len(expected)
    valid_n = len(valid)
    coverage = (valid_n / expected_n) if expected_n else 0.0
    min_rows = 1 if TEST_MODE else int(INTRADAY_SNAPSHOT_MIN_STOCK_ROWS)
    ok = bool(expected_n >= min_rows and valid_n >= min_rows and coverage >= INTRADAY_SNAPSHOT_MIN_COVERAGE)
    return {
        "ok": ok,
        "expected_stock_rows": expected_n,
        "valid_stock_rows": valid_n,
        "coverage": coverage,
        "min_rows": min_rows,
        "min_coverage": INTRADAY_SNAPSHOT_MIN_COVERAGE,
    }


def _intraday_diff_good_capture_times(c: sqlite3.Connection, trade_date: str, limit: int = 12) -> list[str]:
    """DIFF履歴から日本株coverageが十分なcaptureだけを新しい順で返す。"""
    rows = c.execute(
        """
        SELECT captured_at,
               SUM(CASE
                     WHEN code GLOB '[0-9][0-9][0-9][0-9]'
                       OR code GLOB '[0-9][0-9][0-9][A-Za-z]'
                     THEN 1 ELSE 0 END) AS stock_rows
        FROM intraday_diff_snapshot
        WHERE trade_date=?
        GROUP BY captured_at
        ORDER BY captured_at DESC
        """,
        (trade_date,),
    ).fetchall()
    if not rows:
        return []
    counts = [(str(ts), int(n or 0)) for ts, n in rows]
    max_count = max((n for _, n in counts), default=0)
    abs_min = 1 if TEST_MODE else int(INTRADAY_SNAPSHOT_MIN_STOCK_ROWS)
    required = max(abs_min, int(max_count * INTRADAY_SNAPSHOT_MIN_COVERAGE + 0.999999))
    good = [ts for ts, n in counts if n >= required]
    return good[:max(1, int(limit))]


def _intraday_diff_filter_good_history(df: pd.DataFrame) -> tuple[pd.DataFrame, dict]:
    """既存DB内に残った指数だけ/partial captureをDIFF baselineから除外する。"""
    if df is None or df.empty:
        return df, {"captures_total": 0, "captures_good": 0, "required_stock_rows": None}
    z = df.copy()
    stock_mask = z["code"].map(_is_jp_stock_snapshot_code)
    counts = z.loc[stock_mask].groupby("captured_at")["code"].nunique()
    if counts.empty:
        return z.iloc[0:0].copy(), {"captures_total": int(z["captured_at"].nunique()), "captures_good": 0, "required_stock_rows": None}
    max_count = int(counts.max())
    abs_min = 1 if TEST_MODE else int(INTRADAY_SNAPSHOT_MIN_STOCK_ROWS)
    required = max(abs_min, int(max_count * INTRADAY_SNAPSHOT_MIN_COVERAGE + 0.999999))
    good = set(counts[counts >= required].index.astype(str))
    out = z[z["captured_at"].astype(str).isin(good)].copy()
    return out, {
        "captures_total": int(z["captured_at"].nunique()),
        "captures_good": len(good),
        "max_stock_rows": max_count,
        "required_stock_rows": required,
    }


def _live_capture_snapshots(rows: list[dict], daily_map: dict[str, dict]) -> tuple[str, str, int]:
    now = _now_jst()
    captured = now.isoformat(timespec="microseconds")
    trade_date = now.date().isoformat()
    run_mode = str(_auto_run_mode() or RUN_SESSION or "UNKNOWN").upper()

    # INTRADAY-STABILITY-V1: run開始時モードを優先。
    # 8:59 PREOPEN開始runが処理中に9:00を跨いでも、前営業日ベースの値を場中snapshotへ保存しない。
    if run_mode != "MIDDAY":
        print(f"[live-feed] intraday snapshot write skipped run_mode={run_mode}: {captured}")
        globals()["_LIVE_SNAPSHOT_CURRENT_QUALITY"] = {"ok": False, "reason": f"run_mode={run_mode}", "captured": captured}
        return captured, trade_date, 0

    # P4-LIVE SAFE: 場中継続性を測るDBへ時間外の静止価格を入れない。
    if not _live_is_market_snapshot_time(now):
        print(f"[live-feed] intraday snapshot write skipped outside market hours: {captured}")
        globals()["_LIVE_SNAPSHOT_CURRENT_QUALITY"] = {"ok": False, "reason": "outside_market_hours", "captured": captured}
        return captured, trade_date, 0

    _quality = _snapshot_stock_quality(rows)
    _quality.update({"captured": captured, "trade_date": trade_date, "run_mode": run_mode})
    globals()["_LIVE_SNAPSHOT_CURRENT_QUALITY"] = _quality
    if not _quality.get("ok"):
        print(
            "[live-feed][PARTIAL] snapshot write skipped "
            f"stocks={_quality.get('valid_stock_rows')}/{_quality.get('expected_stock_rows')} "
            f"coverage={float(_quality.get('coverage') or 0.0)*100:.1f}% "
            f"required_rows>={_quality.get('min_rows')} required_cov>={float(_quality.get('min_coverage') or 0.0)*100:.0f}%",
            flush=True,
        )
        return captured, trade_date, 0

    vals=[]
    for r in rows:
        code=_live_stock_code(_live_get(r,"コード","code"), _live_get(r,"市場","market"), _live_get(r,"銘柄名","name"))
        if not code: continue
        current_price = _live_num(_live_get(r,"現在値_raw","現在値","current_price"))
        # snapshotは「各runで価格取得できた全市場銘柄」が対象。候補判定前に保存し、価格欠損行は保存しない。
        if current_price is None or current_price <= 0:
            continue
        d=daily_map.get(code,{})
        vals.append((
            captured, trade_date, code,
            current_price,
            _live_num(_live_get(r,"前日終値","previous_close")),
            _live_num(_live_get(r,"始値","day_open")),
            _live_num(_live_get(r,"高値","day_high")),
            _live_num(_live_get(r,"安値","day_low")),
            _live_num(_live_get(r,"出来高","volume")),
            _live_num(_live_get(r,"売買代金億","売買代金(億)","turnover_oku")),
            _live_num(_live_get(r,"RVOL代金","rvol_turnover")),
            _live_num(d.get("ma5")), _live_num(d.get("ma25")), _live_num(d.get("ma75")),
            _live_num(_live_get(r,"支持線今日","support_today")),
            _live_num(_live_get(r,"抵抗線今日","resistance_today")),
        ))
    c=_live_snapshot_conn()
    try:
        with c:
            c.executemany("""
                INSERT OR REPLACE INTO intraday_scanner_snapshot(
                    captured_at,trade_date,code,current_price,previous_close,day_open,day_high,day_low,
                    volume,turnover_oku,rvol_turnover,ma5,ma25,ma75,support_today,resistance_today
                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, vals)
            pruned=_live_prune_snapshot_trade_days(c)
        if pruned:
            print(f"[live-feed] snapshot prune rows={pruned} keep_trade_days={LIVE_SNAPSHOT_KEEP_TRADE_DAYS}")
    finally:
        c.close()
    return captured, trade_date, len(vals)




# ==============================================================================
# P4-DASH7: 実際に「今買える？」が成立した時点のフォロースルーを保存する。
# ==============================================================================
ENTRY_SIGNAL_RECENT_TRADE_DAYS = max(3, int(os.environ.get("KABU_ENTRY_SIGNAL_RECENT_DAYS", "5")))
ENTRY_SIGNAL_BASELINE_TRADE_DAYS = max(5, int(os.environ.get("KABU_ENTRY_SIGNAL_BASELINE_DAYS", "10")))
ENTRY_SIGNAL_MIN_OBS = max(10, int(os.environ.get("KABU_ENTRY_SIGNAL_MIN_OBS", "30")))
ENTRY_SIGNAL_KEEP_TRADE_DAYS = max(20, int(os.environ.get("KABU_ENTRY_SIGNAL_KEEP_TRADE_DAYS", "60")))


def _daily_close_is_confirmed(day_value, now_jst=None) -> bool:
    """日足の終値として利用してよい時点かを判定する。

    過去日は確定済み、未来日は未確定。当日は東証大引け後の15:30以降だけ確定扱い。
    MIDDAYでprice_history.終値にlive currentが入っていても、この判定を通さない限り
    outcome/翌日終値へ利用しない。
    """
    try:
        d = pd.Timestamp(day_value).date()
    except Exception:
        return False
    now = now_jst or _now_jst()
    today = now.date()
    if d < today:
        return True
    if d > today:
        return False
    return (now.hour, now.minute, now.second) >= (15, 30, 0)


def _confirmed_daily_outcome_cutoff(asof_value) -> str:
    """事後成績計算に使える最終の確定日足日を返す。"""
    try:
        asof_d = pd.Timestamp(asof_value).date()
    except Exception:
        return str(asof_value)
    now = _now_jst()
    if _daily_close_is_confirmed(asof_d, now):
        return asof_d.isoformat()
    extra = _load_extra_closed(EXTRA_CLOSED_PATH)
    return prev_business_day_jp(asof_d, extra).isoformat()


_ENTRY_OUTCOME_V40_FAST = str(os.environ.get("KABU_SCREEN_V40_FAST", "1") or "1").strip().lower() not in {"0","false","off","no"}

def _v40_entry_fast_enabled() -> bool:
    return bool(_ENTRY_OUTCOME_V40_FAST)

def _entry_signal_ensure_schema(c: sqlite3.Connection) -> None:
    c.execute("""
        CREATE TABLE IF NOT EXISTS intraday_buy_signal_event (
            signal_at TEXT NOT NULL,
            trade_date TEXT NOT NULL,
            code TEXT NOT NULL,
            entry_price REAL NOT NULL,
            entry_rank INTEGER NOT NULL,
            entry_label TEXT,
            setup_bucket TEXT,
            steady_score REAL,
            p10m REAL,
            p30m REAL,
            p60m REAL,
            close_price REAL,
            next1d_close REAL,
            next3d_close REAL,
            mfe60 REAL,
            mae60 REAL,
            updated_at TEXT,
            PRIMARY KEY (trade_date, code)
        )
    """)
    c.execute("CREATE INDEX IF NOT EXISTS idx_buy_signal_event_at ON intraday_buy_signal_event(signal_at, code)")
    c.execute("CREATE INDEX IF NOT EXISTS idx_buy_signal_event_date ON intraday_buy_signal_event(trade_date, code)")


def _entry_signal_prune(c: sqlite3.Connection) -> int:
    dates=[str(r[0]) for r in c.execute("SELECT DISTINCT trade_date FROM intraday_buy_signal_event ORDER BY trade_date DESC").fetchall()]
    if len(dates) <= ENTRY_SIGNAL_KEEP_TRADE_DAYS:
        return 0
    keep=set(dates[:ENTRY_SIGNAL_KEEP_TRADE_DAYS])
    q=",".join("?" for _ in keep)
    before=c.total_changes
    c.execute(f"DELETE FROM intraday_buy_signal_event WHERE trade_date NOT IN ({q})",tuple(sorted(keep)))
    return int(c.total_changes-before)


def _entry_signal_capture_events(rows: list[dict], live_context: dict | None) -> int:
    """rank=3の最初の場中シグナルだけを1銘柄1日1イベントとして保存する。

    過去snapshotを後から推測して陽性化しない。導入日以降に実際のrunで成立したsignalだけが正本。
    """
    ctx = live_context or {}
    captured = str(ctx.get("captured") or "")
    trade_date = str(ctx.get("trade_date") or "")
    snapshot_rows = int(ctx.get("snapshot_rows") or 0)
    if not captured or not trade_date or snapshot_rows <= 0:
        print(
            f"[entry-signal] capture skipped: captured={bool(captured)} "
            f"trade_date={trade_date or '-'} snapshot_rows={snapshot_rows}"
        )
        return 0
    vals = []
    for r in rows:
        rank = int(_live_num(r.get("今買えるランク")) or 0)
        if rank < 3:
            continue
        code = _live_stock_code(_live_get(r,"コード"), _live_get(r,"市場"), _live_get(r,"銘柄名"))
        px = _live_num(_live_get(r,"現在値_raw","現在値"))
        if not code or px is None or px <= 0:
            continue
        vals.append((
            captured, trade_date, code, float(px), rank, str(r.get("今買える") or ""),
            _entry_env_current_setup_bucket(r), _live_num(r.get("持続上昇スコア")),
            _now_jst().isoformat(timespec="seconds"),
        ))
    if not vals:
        _rank3 = sum(1 for _r in rows if int(_live_num(_r.get("今買えるランク")) or 0) >= 3)
        print(
            f"[entry-signal] no new event candidates: rows={len(rows)} "
            f"rank3_or_more={_rank3} captured={captured} trade_date={trade_date}"
        )
        return 0
    c = _live_snapshot_conn()
    try:
        _entry_signal_ensure_schema(c)
        before = c.total_changes
        with c:
            c.executemany("""
                INSERT OR IGNORE INTO intraday_buy_signal_event(
                    signal_at,trade_date,code,entry_price,entry_rank,entry_label,setup_bucket,steady_score,updated_at
                ) VALUES (?,?,?,?,?,?,?,?,?)
            """, vals)
            inserted = int(c.total_changes - before)
            _entry_signal_prune(c)
        return inserted
    finally:
        c.close()


def _entry_signal_refresh_intraday_outcomes(trade_date: str | None = None) -> int:
    """signal後の10/30/60分と60分MFE/MAEを既存snapshotから埋める。"""
    c = _live_snapshot_conn()
    try:
        _entry_signal_ensure_schema(c)
        params = []
        where = ""
        if trade_date:
            where = " WHERE trade_date=?"
            params = [str(trade_date)]
        ev = pd.read_sql_query(
            "SELECT * FROM intraday_buy_signal_event" + where + " ORDER BY signal_at, code",
            c, params=params,
        )
        if ev.empty:
            return 0
        dates = sorted(set(ev["trade_date"].astype(str)))
        snaps = None
        if _v40_entry_fast_enabled():
            _v40_t0 = time.perf_counter()
            try:
                event_codes = sorted(set(ev["code"].astype(str)))
                if dates and event_codes:
                    date_q = ",".join("?" for _ in dates)
                    parts = []
                    # SQLite parameter上限とquery plannerの安定性を優先してcodeを分割。
                    for _i in range(0, len(event_codes), 400):
                        _codes = event_codes[_i:_i+400]
                        code_q = ",".join("?" for _ in _codes)
                        parts.append(pd.read_sql_query(
                            f"SELECT captured_at,trade_date,code,current_price FROM intraday_scanner_snapshot "
                            f"WHERE trade_date IN ({date_q}) AND code IN ({code_q}) ORDER BY captured_at,code",
                            c, params=[*dates, *_codes],
                        ))
                    snaps = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
                    if not snaps.empty:
                        snaps = snaps.sort_values(["captured_at","code"], kind="stable").reset_index(drop=True)
                    _perf_record_phase(
                        "backend-detail:entry_intraday_snapshot_filter",
                        time.perf_counter()-_v40_t0, "OK"
                    )
                    print(
                        f"[V40][entry-intraday] snapshot-filter codes={len(event_codes)} dates={len(dates)} rows={len(snaps)}",
                        flush=True,
                    )
            except Exception as _v40_e:
                snaps = None
                print(f"[V40][entry-intraday][WARN] filtered load failed -> legacy: {_v40_e}", flush=True)
        if snaps is None:
            ph = ",".join("?" for _ in dates)
            snaps = pd.read_sql_query(
                f"SELECT captured_at,trade_date,code,current_price FROM intraday_scanner_snapshot WHERE trade_date IN ({ph}) ORDER BY captured_at,code",
                c, params=dates,
            )
        if snaps.empty:
            return 0
        snaps["_dt"] = pd.to_datetime(snaps["captured_at"], errors="coerce", utc=True).dt.tz_convert("Asia/Tokyo")
        snaps["current_price"] = pd.to_numeric(snaps["current_price"], errors="coerce")
        snaps = snaps.dropna(subset=["_dt","current_price"])
        grouped = {(str(code),str(day)): g.sort_values("_dt", kind="stable") for (code,day),g in snaps.groupby(["code","trade_date"], sort=False)}
        updates=[]
        for _, row in ev.iterrows():
            code=str(row["code"]); day=str(row["trade_date"])
            g=grouped.get((code,day))
            if g is None or g.empty:
                continue
            sig=pd.to_datetime(row["signal_at"], errors="coerce", utc=True)
            if pd.isna(sig):
                continue
            sig=sig.tz_convert("Asia/Tokyo")
            ep=_live_num(row["entry_price"])
            if ep is None or ep <= 0:
                continue
            vals={}
            for mins,col,tol in ((10,"p10m",15),(30,"p30m",20),(60,"p60m",25)):
                if _live_num(row.get(col)) is not None:
                    vals[col]=_live_num(row.get(col)); continue
                target=sig+pd.Timedelta(minutes=mins)
                cand=g[(g["_dt"]>=target)&(g["_dt"]<=target+pd.Timedelta(minutes=tol))]
                vals[col]=_live_num(cand.iloc[0]["current_price"]) if not cand.empty else None
            w=g[(g["_dt"]>=sig)&(g["_dt"]<=sig+pd.Timedelta(minutes=60))]["current_price"].dropna()
            mfe=(float(w.max())/ep-1.0) if len(w) else _live_num(row.get("mfe60"))
            mae=(float(w.min())/ep-1.0) if len(w) else _live_num(row.get("mae60"))
            updates.append((vals.get("p10m"),vals.get("p30m"),vals.get("p60m"),mfe,mae,_now_jst().isoformat(timespec="seconds"),day,code))
        if not updates:
            return 0
        with c:
            c.executemany("""
                UPDATE intraday_buy_signal_event
                   SET p10m=COALESCE(p10m,?), p30m=COALESCE(p30m,?), p60m=COALESCE(p60m,?),
                       mfe60=COALESCE(?,mfe60), mae60=COALESCE(?,mae60), updated_at=?
                 WHERE trade_date=? AND code=?
            """, updates)
        return len(updates)
    finally:
        c.close()


def _entry_signal_refresh_daily_outcomes(conn: sqlite3.Connection) -> int:
    """signal日の引け、翌営業日、3営業日後の確定終値をprice_historyから埋める。

    当日の場中price_history.終値はlive currentなので終値扱いしない。
    既に旧runで場中値がnext1d/next3dへ入っていても、対象日が確定後なら真の終値で上書きする。
    対象日が今日かつ15:30前なら旧汚染値をNULLへ戻す。
    """
    c = _live_snapshot_conn()
    try:
        _entry_signal_ensure_schema(c)
        _v45_t = time.perf_counter()
        ev = pd.read_sql_query("SELECT * FROM intraday_buy_signal_event ORDER BY trade_date,code", c)
        _perf_record_phase("backend-detail:entry_daily_event_load", time.perf_counter()-_v45_t, "OK")
        if ev.empty:
            return 0
        codes=sorted(set(ev["code"].astype(str)))
        min_day=str(ev["trade_date"].astype(str).min())
        event_codes=set(codes)

        # PERF-OPT-V40: event codeのraw aliasだけを既存code/date expression indexで取得。
        # 取得後のcanonical filter/dedupe/休日除外/営業日位置計算は従来処理をそのまま通す。
        ph = None
        if _v40_entry_fast_enabled():
            _v40_t0 = time.perf_counter()
            try:
                variants = expand_code_query_variants(codes)
                if variants:
                    parts = []
                    for _i in range(0, len(variants), 400):
                        _part = variants[_i:_i+400]
                        _qm = ",".join("?" for _ in _part)
                        parts.append(pd.read_sql_query(
                            "SELECT rowid AS _rowid,コード,日付,終値 FROM price_history "
                            "INDEXED BY idx_price_history_perf_code_text_date "
                            f"WHERE CAST(コード AS TEXT) IN ({_qm}) AND date(日付)>=date(?) "
                            "ORDER BY 日付,_rowid",
                            conn, params=[*_part, min_day],
                        ))
                    ph = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
                    if not ph.empty:
                        ph = ph.sort_values(["日付","_rowid"], kind="stable").reset_index(drop=True)
                    _perf_record_phase(
                        "backend-detail:entry_daily_history_filter",
                        time.perf_counter()-_v40_t0, "OK"
                    )
                    print(
                        f"[V40][entry-daily] history-filter event_codes={len(codes)} variants={len(variants)} rows={len(ph)}",
                        flush=True,
                    )
            except Exception as _v40_e:
                ph = None
                print(f"[V40][entry-daily][WARN] filtered load failed -> legacy: {_v40_e}", flush=True)
        if ph is None:
            # Legacy exact fallback.
            ph=pd.read_sql_query(
                "SELECT rowid AS _rowid,コード,日付,終値 FROM price_history "
                "WHERE date(日付)>=date(?) ORDER BY 日付,_rowid",
                conn, params=[min_day],
            )
        if ph.empty:
            return 0
        _v45_t = time.perf_counter()
        ph["_entry_code_key"] = ph["コード"].map(canonical_code_for_db)
        ph = ph[ph["_entry_code_key"].isin(event_codes)].drop(
            columns=["_entry_code_key"], errors="ignore"
        ).copy()
        _perf_record_phase("backend-detail:entry_daily_canonical_filter", time.perf_counter()-_v45_t, "OK")
        if ph.empty:
            return 0
        # alias重複とlegacy休場日足を除き、「3行後」=3営業日後を守る。
        _v45_t = time.perf_counter()
        ph = _dedupe_price_history_df(ph)
        _perf_record_phase("backend-detail:entry_daily_dedupe", time.perf_counter()-_v45_t, "OK")
        _v45_t = time.perf_counter()
        ph["日付"]=pd.to_datetime(ph["日付"],errors="coerce").dt.strftime("%Y-%m-%d")
        ph["終値"]=pd.to_numeric(ph["終値"],errors="coerce")
        ph=ph.dropna(subset=["コード","日付","終値"])
        _perf_record_phase("backend-detail:entry_daily_normalize", time.perf_counter()-_v45_t, "OK")
        updates=[]
        now=_now_jst()
        today=now.date().isoformat()

        # PERF-OPT-V46: V45で約2秒を占めていたeventごとのiterrows + 3回iloc +
        # pd.Timestamp確認を、code内営業日positionへのvectorized joinへ置換する。
        # phは直前の_dedupe_price_history_dfでcanonical code / JPX営業日 / 日付順が確定済み。
        # close / +1営業日 / +3営業日の意味論と、当日15:30前の旧汚染値NULL化は不変。
        _v46_fast = str(os.environ.get("KABU_SCREEN_V46_FAST", "1") or "1").strip().lower() not in {"0","false","off","no"}
        _v46_done = False
        if _v46_fast:
            _v46_t0 = time.perf_counter()
            try:
                _v46_ph = ph[["コード","日付","終値"]].copy()
                _v46_ph["コード"] = _v46_ph["コード"].astype(str)
                _v46_ph["_entry_pos"] = _v46_ph.groupby("コード", sort=False).cumcount().astype("int64")

                _v46_base = ev[["trade_date","code"]].copy()
                _v46_base["trade_date"] = _v46_base["trade_date"].astype(str)
                _v46_base["code"] = _v46_base["code"].astype(str)
                _v46_base["_event_ord"] = np.arange(len(_v46_base), dtype=np.int64)

                _v46_pos = _v46_ph[["コード","日付","_entry_pos"]].rename(
                    columns={"コード":"code","日付":"trade_date"}
                )
                _v46_base = _v46_base.merge(
                    _v46_pos, on=["code","trade_date"], how="left", sort=False, validate="many_to_one"
                )
                _v46_base = _v46_base[_v46_base["_entry_pos"].notna()].copy()
                if not _v46_base.empty:
                    _v46_base["_entry_pos"] = _v46_base["_entry_pos"].astype("int64")
                    _v46_target = _v46_ph.rename(columns={"コード":"code"})[["code","_entry_pos","日付","終値"]]
                    _v46_today_confirmed = (now.hour, now.minute, now.second) >= (15, 30, 0)

                    for _v46_off, _v46_prefix in ((0,"close"),(1,"n1"),(3,"n3")):
                        _v46_key = f"_target_pos_{_v46_prefix}"
                        _v46_base[_v46_key] = _v46_base["_entry_pos"] + int(_v46_off)
                        _v46_r = _v46_target.rename(columns={
                            "_entry_pos": _v46_key,
                            "日付": f"_{_v46_prefix}_day",
                            "終値": f"_{_v46_prefix}_value",
                        })
                        _v46_base = _v46_base.merge(
                            _v46_r, on=["code", _v46_key], how="left", sort=False, validate="many_to_one"
                        )
                        _v46_day = _v46_base[f"_{_v46_prefix}_day"]
                        _v46_exists = _v46_day.notna()
                        _v46_past = _v46_exists & (_v46_day < today)
                        _v46_is_today = _v46_exists & (_v46_day == today)
                        _v46_ok = _v46_past | (_v46_is_today & bool(_v46_today_confirmed))
                        _v46_clear = _v46_is_today & (not bool(_v46_today_confirmed))
                        _v46_base[f"_{_v46_prefix}_ok"] = _v46_ok.astype("int8")
                        _v46_base[f"_{_v46_prefix}_clear"] = _v46_clear.astype("int8")
                        _v46_base[f"_{_v46_prefix}_out"] = _v46_base[f"_{_v46_prefix}_value"].where(_v46_ok)

                    _v46_base = _v46_base.sort_values("_event_ord", kind="stable")
                    _v46_updated_at = now.isoformat(timespec="seconds")
                    _v46_cols = [
                        "_close_ok","_close_out","_close_clear",
                        "_n1_ok","_n1_out","_n1_clear",
                        "_n3_ok","_n3_out","_n3_clear",
                        "trade_date","code",
                    ]
                    for _v46_vals in _v46_base[_v46_cols].to_numpy(dtype=object):
                        _cok,_cv,_cclr,_n1ok,_n1v,_n1clr,_n3ok,_n3v,_n3clr,_day,_code = _v46_vals
                        updates.append((
                            int(_cok), None if pd.isna(_cv) else float(_cv), int(_cclr),
                            int(_n1ok), None if pd.isna(_n1v) else float(_n1v), int(_n1clr),
                            int(_n3ok), None if pd.isna(_n3v) else float(_n3v), int(_n3clr),
                            _v46_updated_at, str(_day), str(_code),
                        ))
                _v46_done = True
                _v46_dt = time.perf_counter()-_v46_t0
                _perf_record_phase("backend-detail:entry_daily_group_build", _v46_dt, "FAST-V46")
                _perf_record_phase("backend-detail:entry_daily_outcome_loop", _v46_dt, "FAST-V46")
                _perf_record_phase("backend-detail:entry_daily_vector_outcome", _v46_dt, "OK")
                print(f"[V46][entry-daily] vector-outcome events={len(ev)} updates={len(updates)} dt={_v46_dt:.3f}s", flush=True)
            except Exception as _v46_e:
                updates=[]
                print(f"[V46][entry-daily][WARN] vector outcome failed -> V45 legacy: {_v46_e}", flush=True)

        if not _v46_done:
            _v45_t = time.perf_counter()
            by_code={}
            pos_by_code={}
            for code,g in ph.groupby("コード",sort=False):
                gg=g.sort_values("日付",kind="stable").reset_index(drop=True)
                ck=str(code)
                by_code[ck]=gg
                pos_by_code[ck]={str(_d): int(_i) for _i,_d in enumerate(gg["日付"].astype(str).tolist())}
            _perf_record_phase("backend-detail:entry_daily_group_build", time.perf_counter()-_v45_t, "OK")

            def _slot(g, pos):
                if pos >= len(g):
                    return None, None, False, False
                target_day=str(g.iloc[pos]["日付"])
                confirmed=_daily_close_is_confirmed(target_day, now)
                value=_live_num(g.iloc[pos]["終値"]) if confirmed else None
                # 今日の未確定足だけは、旧版が保存した場中値を明示的に消す。
                clear_unconfirmed=(target_day == today and not confirmed)
                return target_day, value, confirmed, clear_unconfirmed

            _v45_t = time.perf_counter()
            for _,row in ev.iterrows():
                code=str(row["code"]); day=str(row["trade_date"]); g=by_code.get(code)
                if g is None or g.empty:
                    continue
                idx=pos_by_code.get(code,{}).get(day)
                if idx is None:
                    continue
                _, close, close_ok, close_clear = _slot(g, idx)
                _, n1, n1_ok, n1_clear = _slot(g, idx+1)
                _, n3, n3_ok, n3_clear = _slot(g, idx+3)
                updates.append((
                    int(close_ok), close, int(close_clear),
                    int(n1_ok), n1, int(n1_clear),
                    int(n3_ok), n3, int(n3_clear),
                    now.isoformat(timespec="seconds"), day, code,
                ))
            _perf_record_phase("backend-detail:entry_daily_outcome_loop", time.perf_counter()-_v45_t, "OK")
        if not updates:
            return 0
        _v45_t = time.perf_counter()
        with c:
            c.executemany("""
                UPDATE intraday_buy_signal_event
                   SET close_price = CASE WHEN ?=1 THEN ? WHEN ?=1 THEN NULL ELSE close_price END,
                       next1d_close = CASE WHEN ?=1 THEN ? WHEN ?=1 THEN NULL ELSE next1d_close END,
                       next3d_close = CASE WHEN ?=1 THEN ? WHEN ?=1 THEN NULL ELSE next3d_close END,
                       updated_at=?
                 WHERE trade_date=? AND code=?
            """, updates)
        _perf_record_phase("backend-detail:entry_daily_db_update", time.perf_counter()-_v45_t, "OK")
        return len(updates)
    finally:
        c.close()


_ENTRY_SIGNAL_EVENT_DF_RUN_CACHE = None
_ENTRY_SIGNAL_SUMMARY_RUN_CACHE = {}

def _entry_signal_event_df_for_summary() -> pd.DataFrame:
    """V22: intraday_buy_signal_eventを同一runで1回だけ読込・派生列化する。"""
    global _ENTRY_SIGNAL_EVENT_DF_RUN_CACHE
    if isinstance(_ENTRY_SIGNAL_EVENT_DF_RUN_CACHE, pd.DataFrame):
        return _ENTRY_SIGNAL_EVENT_DF_RUN_CACHE
    c = _live_snapshot_conn()
    try:
        _entry_signal_ensure_schema(c)
        df = pd.read_sql_query(
            "SELECT * FROM intraday_buy_signal_event ORDER BY trade_date,signal_at",
            c,
        )
    finally:
        c.close()
    if not df.empty:
        for col in ("entry_price","p10m","p30m","p60m","close_price","next1d_close","next3d_close","mfe60","mae60"):
            df[col] = pd.to_numeric(df[col], errors="coerce")
        ep = df["entry_price"].replace(0, np.nan)
        df["ret_10m"] = df["p10m"] / ep - 1.0
        df["ret_30m"] = df["p30m"] / ep - 1.0
        df["ret_60m"] = df["p60m"] / ep - 1.0
        df["ret_close"] = df["close_price"] / ep - 1.0
        df["ret_1d"] = df["next1d_close"] / ep - 1.0
        df["ret_3d"] = df["next3d_close"] / ep - 1.0
        df["hit1_60m"] = np.where(df["mfe60"].notna(), (df["mfe60"] >= 0.01).astype(float), np.nan)
        df["_trade_date_str_v22"] = df["trade_date"].astype(str)
        if "setup_bucket" in df.columns:
            df["_setup_bucket_str_v22"] = df["setup_bucket"].fillna("").astype(str)
        else:
            df["_setup_bucket_str_v22"] = ""
    _ENTRY_SIGNAL_EVENT_DF_RUN_CACHE = df
    print(f"[ENTRY-V22] signal-event shared rows={len(df)}", flush=True)
    return df


def _entry_signal_metric_summary(setup_bucket: str | None = None) -> dict:
    """実際の『今買える？=○』初回signalの事後成績を集計する。V22は読込/派生列をrun共有。"""
    _key = "__ALL__" if not setup_bucket else str(setup_bucket)
    _hit = _ENTRY_SIGNAL_SUMMARY_RUN_CACHE.get(_key)
    if isinstance(_hit, dict):
        return _hit

    all_df = _entry_signal_event_df_for_summary()
    empty = {"score":None,"qualified":False,"event_count":0,"metrics":{},"recent_days":0,"baseline_days":0}
    if all_df.empty:
        _ENTRY_SIGNAL_SUMMARY_RUN_CACHE[_key] = empty
        return empty
    if setup_bucket:
        df = all_df.loc[all_df["_setup_bucket_str_v22"].eq(str(setup_bucket))]
    else:
        df = all_df
    if df.empty:
        _ENTRY_SIGNAL_SUMMARY_RUN_CACHE[_key] = empty
        return empty

    dates = sorted(df["_trade_date_str_v22"].unique().tolist())
    recent_dates = dates[-ENTRY_SIGNAL_RECENT_TRADE_DAYS:]
    base_dates = dates[-(ENTRY_SIGNAL_RECENT_TRADE_DAYS+ENTRY_SIGNAL_BASELINE_TRADE_DAYS):-ENTRY_SIGNAL_RECENT_TRADE_DAYS] if len(dates)>ENTRY_SIGNAL_RECENT_TRADE_DAYS else []
    _recent_mask = df["_trade_date_str_v22"].isin(recent_dates)
    _base_mask = df["_trade_date_str_v22"].isin(base_dates)
    specs={
        "plus_10m":("ret_10m","positive"),"plus_30m":("ret_30m","positive"),"plus_60m":("ret_60m","positive"),
        "plus_close":("ret_close","positive"),"plus_1d":("ret_1d","positive"),"plus_3d":("ret_3d","positive"),
        "hit_plus1_60m":("hit1_60m","bool"),"mfe_60m":("mfe60","median"),"mae_60m":("mae60","median"),
    }
    def agg(x,kind):
        z=pd.to_numeric(x,errors="coerce").dropna()
        if z.empty:return None
        if kind=="positive":return float((z>0).mean()*100.0)
        if kind=="bool":return float(z.mean()*100.0)
        return float(z.median()*100.0)
    metrics={}
    for key,(col,kind) in specs.items():
        rv=df.loc[_recent_mask,col]
        bv=df.loc[_base_mask,col]
        _nr=int(pd.to_numeric(rv,errors="coerce").notna().sum())
        _nb=int(pd.to_numeric(bv,errors="coerce").notna().sum())
        _ra = agg(rv,kind); _ba = agg(bv,kind)
        metrics[key]={
            "recent":None if _ra is None else round(_ra,2),
            "baseline":None if _ba is None else round(_ba,2),
            "n_recent":_nr,
            "n_baseline":_nb,
            "score_eligible_recent":bool(_nr >= ENTRY_SIGNAL_MIN_OBS),
            "score_eligible_delta":bool(_nr >= ENTRY_SIGNAL_MIN_OBS and _nb >= ENTRY_SIGNAL_MIN_OBS),
        }
    core_n=min(metrics.get("plus_60m",{}).get("n_recent",0),metrics.get("plus_close",{}).get("n_recent",0))
    qualified=bool(core_n>=ENTRY_SIGNAL_MIN_OBS and len(recent_dates)>=3)

    # 絶対的に『買って伸びるか』を主役にし、過去baselineとの差は補助にする。
    abs_specs={
        "plus_10m":(8,50,1.5),"plus_30m":(12,50,1.5),"plus_60m":(18,50,1.6),"plus_close":(14,50,1.5),
        "plus_1d":(14,50,1.4),"plus_3d":(10,50,1.3),"hit_plus1_60m":(8,35,1.5),
        "mfe_60m":(8,1.0,25.0),"mae_60m":(8,-1.0,25.0),
    }
    aw=[]
    for key,(w,center,scale) in abs_specs.items():
        m=metrics.get(key)or{}
        v=_live_num(m.get("recent"))
        if v is None or int(m.get("n_recent") or 0) < ENTRY_SIGNAL_MIN_OBS:
            continue
        comp=_entry_env_clamp(50.0+(v-center)*scale)
        if comp is not None:aw.append((comp,float(w)))
    abs_score=(sum(v*w for v,w in aw)/sum(w for _,w in aw)) if aw else None
    dw=[]
    delta_scales={"plus_10m":12,"plus_30m":12,"plus_60m":12,"plus_close":12,"plus_1d":12,"plus_3d":12,"hit_plus1_60m":15,"mfe_60m":1.0,"mae_60m":1.0}
    for key,sc in delta_scales.items():
        m=metrics.get(key)or{}; rv=_live_num(m.get("recent")); bv=_live_num(m.get("baseline"))
        if (rv is None or bv is None
                or int(m.get("n_recent") or 0) < ENTRY_SIGNAL_MIN_OBS
                or int(m.get("n_baseline") or 0) < ENTRY_SIGNAL_MIN_OBS):
            continue
        comp=_entry_env_clamp(50.0+50.0*((rv-bv)/float(sc)))
        if comp is not None:dw.append(comp)
    delta_score=(sum(dw)/len(dw)) if dw else None
    if abs_score is None: score=None
    elif delta_score is None: score=abs_score
    else: score=abs_score*0.70+delta_score*0.30
    score=None if score is None else round(float(_entry_env_clamp(score)),1)
    result={"score":score,"absolute_score":None if abs_score is None else round(float(abs_score),1),"delta_score":None if delta_score is None else round(float(delta_score),1),"qualified":qualified,"event_count":int(len(df)),"metrics":metrics,"recent_days":len(recent_dates),"baseline_days":len(base_dates),"min_obs":ENTRY_SIGNAL_MIN_OBS}
    _ENTRY_SIGNAL_SUMMARY_RUN_CACHE[_key] = result
    return result

def _live_intraday_feature_map(trade_date: str, current_codes: set[str]) -> dict[str, dict]:
    """場中snapshotから5/10/20/30/60分特徴を作る。

    PERF-OPT-V5: 各銘柄×各horizonでDataFrame boolean filterを繰り返さず、
    ソート済み時刻配列へnp.searchsortedして同じ「target以前の最後のsnapshot」を参照する。
    """
    if not current_codes:
        return {}
    _v25_mode = str(_auto_run_mode() or RUN_SESSION or "UNKNOWN").upper()
    _v25_intraday_fp = ""
    _v25_codes_fp = ""
    if _v25_fast_enabled() and _v25_mode == "EOD":
        try:
            _v25_intraday_fp = _v25_intraday_source_fingerprint(trade_date)
            _v25_codes_fp = _stage2_codes_hash(current_codes)
            _obj = _stage2_json_read(_V25_INTRADAY_CACHE_PATH)
            if (
                _v25_intraday_fp and isinstance(_obj, dict)
                and int(_obj.get("schema") or 0) == _V25_CACHE_SCHEMA
                and str(_obj.get("trade_date") or "") == str(trade_date)
                and str(_obj.get("source_fp") or "") == _v25_intraday_fp
                and str(_obj.get("codes_fp") or "") == _v25_codes_fp
            ):
                _hit = _v25_records_json_map(_obj.get("records"))
                print(f"[V25-INTRADAY-CACHE] HIT trade_date={trade_date} codes={len(_hit)}", flush=True)
                return _hit
            print(f"[V25-INTRADAY-CACHE] MISS trade_date={trade_date}", flush=True)
        except Exception as _e:
            print(f"[V25-INTRADAY-CACHE][WARN] lookup failed: {_e}", flush=True)
    c=_live_snapshot_conn()
    try:
        # V60: 最大horizonは60分。直近window + window以前の各code最新1行(anchor)だけで
        # searchsortedの「target以前の最後のsnapshot」を完全に再現できる。
        if V60_INTRADAY_WINDOW_FAST and str(_auto_run_mode() or RUN_SESSION or "").upper()=="MIDDAY":
            _max_cap = c.execute("SELECT MAX(captured_at) FROM intraday_scanner_snapshot WHERE trade_date=?", (trade_date,)).fetchone()
            _max_cap = _max_cap[0] if _max_cap else None
            _max_dt = pd.to_datetime(_max_cap, errors="coerce", utc=True) if _max_cap else pd.NaT
            if pd.notna(_max_dt):
                _cut_dt = _max_dt - pd.Timedelta(minutes=int(V60_INTRADAY_RECENT_MINUTES))
                _cut_iso = _cut_dt.isoformat()
                df=pd.read_sql_query(
                    """WITH anchor AS (
                           SELECT captured_at,trade_date,code,current_price,day_low
                           FROM (
                             SELECT captured_at,trade_date,code,current_price,day_low,
                                    ROW_NUMBER() OVER (PARTITION BY code ORDER BY captured_at DESC) AS rn
                             FROM intraday_scanner_snapshot
                             WHERE trade_date=? AND captured_at<?
                           ) WHERE rn=1
                         )
                         SELECT captured_at,trade_date,code,current_price,day_low
                         FROM intraday_scanner_snapshot
                         WHERE trade_date=? AND captured_at>=?
                         UNION ALL
                         SELECT captured_at,trade_date,code,current_price,day_low FROM anchor
                         ORDER BY captured_at, code""",
                    c, params=[trade_date,_cut_iso,trade_date,_cut_iso],
                )
                print(f"[V60-INTRADAY] window={V60_INTRADAY_RECENT_MINUTES}m rows={len(df)} max={_max_cap}",flush=True)
            else:
                df=pd.read_sql_query("SELECT captured_at,trade_date,code,current_price,day_low FROM intraday_scanner_snapshot WHERE trade_date=? ORDER BY captured_at, code",c,params=[trade_date])
        else:
            df=pd.read_sql_query(
                "SELECT captured_at,trade_date,code,current_price,day_low FROM intraday_scanner_snapshot WHERE trade_date=? ORDER BY captured_at, code",
                c, params=[trade_date],
            )
    finally:
        c.close()
    if df.empty: return {}
    df=df[df["code"].astype(str).isin(current_codes)].copy()

    # P4-LIVE SAFE: 過去runですでに保存された時間外snapshotも計算時に除外する。
    df["_dt"]=pd.to_datetime(df["captured_at"], errors="coerce", utc=True).dt.tz_convert("Asia/Tokyo")
    _minute = df["_dt"].dt.hour * 60 + df["_dt"].dt.minute
    _market_mask = (
        ((_minute >= 9 * 60) & (_minute <= 11 * 60 + 30))
        | ((_minute >= 12 * 60 + 30) & (_minute <= 15 * 60 + 30))
    )
    _before_market_filter = len(df)
    df = df[_market_mask].copy()
    _ignored_afterhours = _before_market_filter - len(df)
    if _ignored_afterhours:
        print(f"[live-feed] ignored outside-market snapshots={_ignored_afterhours} trade_date={trade_date}")
    if df.empty:
        return {}

    for col in ("current_price","day_low"):
        df[col]=pd.to_numeric(df[col], errors="coerce")
    out={}
    horizons=(5,10,20,30,60)
    _minute_ns = int(pd.Timedelta(minutes=1).value)

    for code,g in df.groupby("code", sort=False):
        # SQL ORDER BY captured_at,codeにより各code内も時刻昇順。group内再sortを省略。
        g=g.dropna(subset=["_dt","current_price"])
        if g.empty: continue

        _dt_arr = g["_dt"].astype("int64").to_numpy(copy=False)
        _price_arr = pd.to_numeric(g["current_price"], errors="coerce").to_numpy(dtype=float, copy=False)
        _low_arr = pd.to_numeric(g["day_low"], errors="coerce").to_numpy(dtype=float, copy=False)
        cur=g.iloc[-1]
        curp=_live_num(cur["current_price"]); nowdt=cur["_dt"]
        _now_ns = int(_dt_arr[-1])
        feat={}

        for mins in horizons:
            _target_ns = _now_ns - int(mins) * _minute_ns
            _pos = int(np.searchsorted(_dt_arr, _target_ns, side="right") - 1)
            p0 = _live_num(_price_arr[_pos]) if _pos >= 0 else None
            feat[f"ret_{mins}m"] = round((curp/p0-1.0)*100.0,4) if curp is not None and p0 not in (None,0) else None

        low=_live_num(cur["day_low"])
        feat["low_rebound_pct"] = round((curp/low-1.0)*100.0,4) if curp is not None and low not in (None,0) else None

        _start60_ns = _now_ns - 60 * _minute_ns
        _w0 = int(np.searchsorted(_dt_arr, _start60_ns, side="left"))
        _prices = _price_arr[_w0:]
        _valid_prices = _prices[np.isfinite(_prices)]
        if len(_valid_prices) >= 2:
            _diffs = np.diff(_valid_prices)
            feat["up_snapshot_ratio"] = round(float(np.mean(_diffs > 0)),4)
        else:
            feat["up_snapshot_ratio"] = None
        if len(_valid_prices):
            _cummax = np.maximum.accumulate(_valid_prices)
            _draw = (_valid_prices / _cummax - 1.0) * 100.0
            feat["max_pullback_pct"] = round(float(np.min(_draw)),4)
        else:
            feat["max_pullback_pct"] = None

        # 旧実装と同じく、60分窓内でday_lowがそれまでの最小値を更新した最後の時刻。
        _last_low_change_pos = None
        _last_val = None
        for _rel, _val in enumerate(_low_arr[_w0:]):
            if not np.isfinite(_val):
                continue
            if _last_val is None or float(_val) < float(_last_val) - 1e-12:
                _last_low_change_pos = _w0 + _rel
                _last_val = float(_val)
        if _last_low_change_pos is not None:
            last_low_change_dt = g["_dt"].iloc[_last_low_change_pos]
            _mins_since_low = round(float((nowdt-last_low_change_dt).total_seconds()/60.0),2)
        else:
            last_low_change_dt = None
            _mins_since_low = None
        feat["low_seen_at"] = last_low_change_dt.isoformat() if last_low_change_dt is not None else None
        feat["minutes_since_low"] = _mins_since_low
        feat["no_new_low_minutes"] = _mins_since_low
        feat["minutes_since_low_update"] = _mins_since_low
        feat["low_update_stopped"] = bool(_mins_since_low is not None and _mins_since_low >= 20.0)
        out[str(code)]=feat
    if _v25_fast_enabled() and _v25_mode == "EOD" and _v25_intraday_fp and _v25_codes_fp:
        try:
            if _stage2_json_write(_V25_INTRADAY_CACHE_PATH, {
                "schema": _V25_CACHE_SCHEMA, "trade_date": str(trade_date),
                "source_fp": _v25_intraday_fp, "codes_fp": _v25_codes_fp,
                "records": _v25_json_map_records(out), "saved_at": _now_jst().isoformat(timespec="seconds"),
            }):
                print(f"[V25-INTRADAY-CACHE] STORE codes={len(out)}", flush=True)
        except Exception as _e:
            print(f"[V25-INTRADAY-CACHE][WARN] store failed: {_e}", flush=True)
    return out

def _live_bottom_score(intraday: dict, current_price, support_today=None) -> tuple[float,bool,list[str]]:
    x=intraday or {}; score=0.0; reasons=[]
    rebound=_live_num(x.get("low_rebound_pct")); r10=_live_num(x.get("ret_10m")); r20=_live_num(x.get("ret_20m")); r30=_live_num(x.get("ret_30m"))
    upr=_live_num(x.get("up_snapshot_ratio")); pull=_live_num(x.get("max_pullback_pct")); stopped=bool(x.get("low_update_stopped"))
    if rebound is not None and rebound >= LIVE_BOTTOM_MIN_REBOUND_PCT: score+=25; reasons.append(f"安値+{rebound:.1f}%")
    if stopped: score+=20; reasons.append("安値更新停止")
    if r10 is not None and r10 > 0: score+=10; reasons.append("10分切上げ")
    if r20 is not None and r20 > 0: score+=10; reasons.append("20分切上げ")
    if r30 is not None and r30 > 0: score+=15; reasons.append("30分切上げ")
    if upr is not None and upr >= 0.60: score+=10; reasons.append("snapshot安定上昇")
    if pull is not None and pull >= -1.0: score+=5; reasons.append("押し浅い")
    p=_live_num(current_price); sup=_live_num(support_today)
    if p is not None and sup is not None and p >= sup: score+=5; reasons.append("支持線回復")
    gate=bool(score>=LIVE_BOTTOM_MIN_SCORE and rebound is not None and rebound>=LIVE_BOTTOM_MIN_REBOUND_PCT and stopped and r20 is not None and r20>0 and (upr is None or upr>=0.5))
    return round(min(100.0,score),1), gate, reasons




def _live_build_context(conn: sqlite3.Connection, rows: list[dict]) -> dict:
    """Dashboard/LIVE feedで同一runのSTEADY計算コンテキストを共有する。"""
    _t0 = time.perf_counter()
    snapshot = str(_auto_run_mode() or RUN_SESSION or "UNKNOWN").upper()
    asof = _expected_snapshot_date_for_run(snapshot).isoformat()

    daily = _live_daily_structure_map(conn, asof)
    _t_daily = time.perf_counter()
    try: _perf_record_phase("live_context:daily", _t_daily - _t0)
    except Exception: pass
    captured, trade_date, snapshot_rows = _live_capture_snapshots(rows, daily)
    _t_capture = time.perf_counter()
    try: _perf_record_phase("live_context:capture", _t_capture - _t_daily)
    except Exception: pass
    codes = {
        _live_stock_code(_live_get(r, "コード"), _live_get(r, "市場"), _live_get(r, "銘柄名"))
        for r in rows
    }
    codes.discard("")
    intraday_map = _live_intraday_feature_map(trade_date, codes)
    _t_intraday = time.perf_counter()
    try: _perf_record_phase("live_context:intraday", _t_intraday - _t_capture)
    except Exception: pass
    print(
        f"[live-context-perf] daily={_t_daily-_t0:.2f}s capture={_t_capture-_t_daily:.2f}s "
        f"intraday={_t_intraday-_t_capture:.2f}s total={_t_intraday-_t0:.2f}s "
        f"daily_codes={len(daily)} intraday_codes={len(intraday_map)}",
        flush=True,
    )
    return {
        "snapshot": snapshot,
        "asof": asof,
        "daily": daily,
        "captured": captured,
        "trade_date": trade_date,
        "snapshot_rows": snapshot_rows,
        "snapshot_quality": dict(globals().get("_LIVE_SNAPSHOT_CURRENT_QUALITY") or {}),
        "codes": codes,
        "intraday_map": intraday_map,
    }

def _absorption_episode_stats(w_low: pd.Series, w_close: pd.Series, prior20_low: float) -> tuple[int, int, float | None]:
    """支持帯での連続タッチ日を1つの吸収episodeとして数える。

    旧実装は近接帯にいた"日数"を吸収回数として数えたため、7日連続で底練りしただけでも
    7回吸収と誤認した。ここでは連続するhitを1episodeへ圧縮し、直近episodeとその1つ前の
    episodeの安値同士でundercutを測る。
    """
    try:
        p20 = float(prior20_low)
    except Exception:
        return 0, 0, None
    if not np.isfinite(p20) or p20 <= 0:
        return 0, 0, None

    lows = pd.to_numeric(w_low, errors="coerce").reset_index(drop=True)
    closes = pd.to_numeric(w_close, errors="coerce").reset_index(drop=True)
    hit_mask = (lows <= p20 * 1.015) & (lows >= p20 * 0.96) & (closes >= p20 * 0.995)
    hit_pos = np.flatnonzero(hit_mask.fillna(False).to_numpy(dtype=bool))
    hit_days = int(len(hit_pos))
    if hit_days == 0:
        return 0, 0, None

    episodes: list[tuple[int, int]] = []
    start = prev = int(hit_pos[0])
    for raw_pos in hit_pos[1:]:
        pos = int(raw_pos)
        if pos == prev + 1:
            prev = pos
            continue
        episodes.append((start, prev))
        start = prev = pos
    episodes.append((start, prev))

    # 現在日がhitでなければ、過去のepisode数だけで現在A2を強くしない。
    current_pos = len(lows) - 1
    current_is_hit = bool(hit_pos[-1] == current_pos)
    episode_count = int(len(episodes)) if current_is_hit else 0
    if episode_count < 2:
        return episode_count, hit_days, None

    ps, pe = episodes[-2]
    cs, ce = episodes[-1]
    prev_abs_low = _live_num(lows.iloc[ps:pe + 1].min())
    cur_abs_low = _live_num(lows.iloc[cs:ce + 1].min())
    if prev_abs_low in (None, 0) or cur_abs_low is None:
        return episode_count, hit_days, None
    undercut_pct = (float(cur_abs_low) / float(prev_abs_low) - 1.0) * 100.0
    return episode_count, hit_days, undercut_pct


def _dashboard_research_signal_map_legacy_v50(conn: sqlite3.Connection, rows: list[dict], asof_date: str) -> dict[str, dict]:
    """A/B/C研究シグナルをdashboard表示用に再現する。

    これは表示・研究補助用で、LIVE Candidate Contractのgate/priorityへは混ぜない。
    A/Cはこれまでの研究定義を優先。Bはイベント近接の監視仮説であり、好材料予測ではない。
    """
    row_by_code = {}
    for r in rows:
        code = _live_stock_code(_live_get(r, "コード"), _live_get(r, "市場"), _live_get(r, "銘柄名"))
        if code:
            row_by_code[code] = r
    if not row_by_code:
        return {}

    asof_ts = pd.Timestamp(asof_date).normalize()
    start = (asof_ts - pd.Timedelta(days=130)).strftime("%Y-%m-%d")
    _research_mode = str(_auto_run_mode() or RUN_SESSION or "UNKNOWN").upper()
    _v25_research_hist_fp = ""
    _v25_research_rows_fp = ""
    if _v25_fast_enabled() and _research_mode in ("EOD", "PREOPEN"):
        try:
            _v25_research_hist_fp = _stage2_price_history_fingerprint(conn, str(asof_date), 240)
            _v25_research_rows_fp = _v25_rows_hash(rows, ("現在値", "現在値_raw", "始値", "高値", "安値", "出来高", "決算発表予定日"))
            _obj = _stage2_json_read(_V25_RESEARCH_CACHE_PATH)
            if (
                _v25_research_hist_fp and isinstance(_obj, dict)
                and int(_obj.get("schema") or 0) == _V25_CACHE_SCHEMA
                and str(_obj.get("asof") or "") == str(asof_date)
                and str(_obj.get("history_fp") or "") == _v25_research_hist_fp
                and str(_obj.get("rows_fp") or "") == _v25_research_rows_fp
            ):
                _hit = _v25_records_json_map(_obj.get("records"))
                print(f"[V25-RESEARCH-CACHE] HIT asof={asof_date} codes={len(_hit)}", flush=True)
                return _hit
            print(f"[V25-RESEARCH-CACHE] MISS asof={asof_date}", flush=True)
        except Exception as _e:
            print(f"[V25-RESEARCH-CACHE][WARN] lookup failed: {_e}", flush=True)

    if _v25_fast_enabled():
        ph = _v25_legacy_history_frame(conn, start, asof_date, tag="dashboard_research")
        if ph.empty:
            return {}
    else:
        ph = _perf_price_history_raw_range(conn, start, asof_date, tag="dashboard_research")
        if ph.empty:
            return {}
        ph["コード"] = ph["コード"].map(canonical_code_for_db)
        ph["日付"] = pd.to_datetime(ph["日付"], errors="coerce").dt.normalize()
        for c in ("始値", "高値", "安値", "終値", "出来高"):
            ph[c] = pd.to_numeric(ph[c], errors="coerce")
    # V25 fastでもV24 researchと同じ順序: code filter -> close欠損除外 -> sort/dedupe。
    ph = ph[ph["コード"].isin(row_by_code)].copy()
    ph = ph.dropna(subset=["コード", "日付", "終値"]).sort_values(["コード", "日付", "_rowid"], kind="stable")
    ph = ph.drop_duplicates(["コード", "日付"], keep="last")

    ph_groups = {
        str(_code): _g.sort_values("日付", kind="stable").reset_index(drop=True)
        for _code, _g in ph.groupby("コード", sort=False)
    }

    out = {}
    for code, r in row_by_code.items():
        _g0 = ph_groups.get(str(code))
        g = _g0.copy() if _g0 is not None else pd.DataFrame(columns=ph.columns)
        cur = _live_num(_live_get(r, "現在値_raw", "現在値"))
        if cur is None or cur <= 0:
            continue
        opn = _live_num(_live_get(r, "始値", "day_open")) or cur
        hi = _live_num(_live_get(r, "高値", "day_high")) or cur
        lo = _live_num(_live_get(r, "安値", "day_low")) or cur
        vol = _live_num(_live_get(r, "出来高", "volume"))

        # P4-DASH8-AUDIT2:
        # A/B/C研究シグナルは過去replayと本番で同じ足を使う。
        # MIDDAYだけ当日足が未確定なのでrows側のlive OHLCVをoverlayする。
        # EOD/PREOPEN/休場日実行ではprice_historyの確定asof足を正本にする。
        _use_live_bar = (_research_mode == "MIDDAY")

        if not g.empty and pd.Timestamp(g.iloc[-1]["日付"]).normalize() == asof_ts:
            if _use_live_bar:
                idx = g.index[-1]
                g.loc[idx, ["始値", "高値", "安値", "終値"]] = [opn, max(hi, cur), min(lo, cur), cur]
                if vol is not None and vol > 0:
                    g.loc[idx, "出来高"] = vol
        elif g.empty or pd.Timestamp(g.iloc[-1]["日付"]).normalize() < asof_ts:
            if _use_live_bar:
                g = pd.concat([g, pd.DataFrame([{
                    "_rowid": 10**18, "コード": code, "日付": asof_ts,
                    "始値": opn, "高値": max(hi, cur), "安値": min(lo, cur), "終値": cur,
                    "出来高": vol,
                }])], ignore_index=True)
            else:
                # 確定asof足が無いEOD/PREOPENでは疑似足を作らない。
                continue
        g = g.sort_values("日付", kind="stable").reset_index(drop=True)
        if len(g) < 22:
            continue

        close = pd.to_numeric(g["終値"], errors="coerce")
        high = pd.to_numeric(g["高値"], errors="coerce")
        low = pd.to_numeric(g["安値"], errors="coerce")
        volume = pd.to_numeric(g["出来高"], errors="coerce")
        current_i = len(g) - 1
        prev20 = g.iloc[max(0, current_i-20):current_i]
        if len(prev20) < 15:
            continue
        prior20_low = _live_num(pd.to_numeric(prev20["安値"], errors="coerce").min())
        prior20_high = _live_num(pd.to_numeric(prev20["高値"], errors="coerce").max())
        vol20 = _live_num(pd.to_numeric(prev20["出来高"], errors="coerce").median())
        prev5 = g.iloc[max(0, current_i-5):current_i]
        vol5 = _live_num(pd.to_numeric(prev5["出来高"], errors="coerce").median()) if len(prev5) >= 4 else None
        prev_turn = pd.to_numeric(prev20["終値"], errors="coerce") * pd.to_numeric(prev20["出来高"], errors="coerce")
        turn20 = _live_num(prev_turn.median())
        cur_low = _live_num(low.iloc[-1]); cur_high = _live_num(high.iloc[-1]); cur_close = _live_num(close.iloc[-1]); cur_vol = _live_num(volume.iloc[-1])
        prev_close = _live_num(close.iloc[-2]); prev_vol = _live_num(volume.iloc[-2])
        ret1 = (cur_close / prev_close - 1.0) if cur_close is not None and prev_close not in (None, 0) else None
        vol_ratio_prev = (cur_vol / prev_vol) if cur_vol is not None and prev_vol not in (None, 0) else None
        dry_ratio = (vol5 / vol20) if vol5 is not None and vol20 not in (None, 0) else None
        cur_turn = (cur_close * cur_vol) if cur_close is not None and cur_vol is not None else None
        turn_ratio = (cur_turn / turn20) if cur_turn is not None and turn20 not in (None, 0) else None
        clv = ((cur_close-cur_low)/(cur_high-cur_low)) if None not in (cur_close,cur_low,cur_high) and cur_high > cur_low else None

        # ---- A: A2 + repeated absorption ----
        a2 = bool(
            None not in (prior20_low, prior20_high, cur_low, cur_close, dry_ratio)
            and cur_low <= prior20_low
            and (cur_low / prior20_high - 1.0) <= -0.08
            and dry_ratio <= 0.80
            and cur_close > prior20_low
        )
        absorb_count = 0
        absorb_hit_days = 0
        undercut_pct = None
        if a2 and prior20_low not in (None, 0):
            w = g.tail(10).copy()
            absorb_count, absorb_hit_days, undercut_pct = _absorption_episode_stats(
                w["安値"], w["終値"], float(prior20_low)
            )
        if a2 and absorb_count >= 2 and undercut_pct is not None and -3.0 <= undercut_pct <= -0.5:
            a_score, a_label = 3, f"◎ {absorb_count}回吸収episode+下抜け奪回"
        elif a2 and absorb_count >= 2:
            a_score, a_label = 2, f"○ {absorb_count}回吸収episode"
        elif a2:
            a_score, a_label = 1, "△ A2奪回"
        else:
            a_score, a_label = 0, "-"

        # ---- C: user's historical benchmark ----
        c_on = bool(ret1 is not None and vol_ratio_prev is not None and ret1 >= 0.029 and vol_ratio_prev >= 2.80)
        c_score = 1 if c_on else 0
        c_label = f"🔥 {vol_ratio_prev:.2f}x/{ret1*100:+.1f}%" if c_on else "-"

        # ---- B: research watch only (not positive-material prediction) ----
        low20_inc = _live_num(pd.to_numeric(g.tail(20)["安値"], errors="coerce").min())
        dist_low20 = (cur_close / low20_inc - 1.0) if cur_close is not None and low20_inc not in (None,0) else None
        earnings_near = False
        try:
            ed = pd.Timestamp(_live_get(r, "決算発表予定日")).normalize()
            if not pd.isna(ed):
                earnings_near = asof_ts <= ed <= asof_ts + pd.Timedelta(days=15)
        except Exception:
            earnings_near = False
        b_on = bool(
            not earnings_near
            and dist_low20 is not None and dist_low20 <= 0.10
            and ret1 is not None and 0 < ret1 <= 0.10
            and dry_ratio is not None and dry_ratio <= 0.80
            and turn_ratio is not None and turn_ratio >= 1.50
            and clv is not None and clv >= 0.75
        )
        b_score = 1 if b_on else 0
        b_label = "👀 監視" if b_on else "-"

        out[code] = {
            "a_score": a_score, "a_label": a_label, "a_absorb_count": absorb_count,
            "a_absorb_hit_days": absorb_hit_days, "a_undercut_pct": undercut_pct,
            "c_score": c_score, "c_label": c_label, "c_vol_ratio_prev": vol_ratio_prev,
            "c_ret1_pct": (ret1*100.0 if ret1 is not None else None),
            "b_score": b_score, "b_label": b_label,
            "b_turn_ratio": turn_ratio, "b_clv": clv, "b_dry_ratio": dry_ratio,
        }
    if _v25_fast_enabled() and _research_mode in ("EOD", "PREOPEN") and _v25_research_hist_fp and _v25_research_rows_fp:
        try:
            if _stage2_json_write(_V25_RESEARCH_CACHE_PATH, {
                "schema": _V25_CACHE_SCHEMA, "asof": str(asof_date),
                "history_fp": _v25_research_hist_fp, "rows_fp": _v25_research_rows_fp,
                "records": _v25_json_map_records(out), "saved_at": _now_jst().isoformat(timespec="seconds"),
            }):
                print(f"[V25-RESEARCH-CACHE] STORE codes={len(out)}", flush=True)
        except Exception as _e:
            print(f"[V25-RESEARCH-CACHE][WARN] store failed: {_e}", flush=True)
    return out



# === PERF-OPT-V50 / MIDDAY-ABC-BASELINE-CACHE 2026-09-03 ===
# MIDDAY dashboard A/B/C research keeps the exact research definitions but avoids rebuilding
# ~130 days of per-symbol pandas frames every run. Previous-day scalar baselines are persisted;
# only today's live OHLCV is applied each run. First cache creation is audited against the
# legacy implementation; a mismatch fails closed to legacy. Disable with KABU_SCREEN_V50_FAST=0.
_V50_ABC_CACHE_SCHEMA = 1
_V50_ABC_CACHE_PATH = Path(SCREEN_RUNTIME_DIR) / "dashboard_research_midday_baseline_v50.pkl"

def _v50_abc_enabled() -> bool:
    return str(os.environ.get("KABU_SCREEN_V50_FAST", "1") or "1").strip().lower() not in {"0","false","no","off"}

def _v50_num_or_none(v):
    try:
        if v is None: return None
        x=float(v)
        return x if np.isfinite(x) else None
    except Exception:
        return None

def _v50_nan_stat(a, kind: str):
    x=np.asarray(a,dtype=float)
    x=x[np.isfinite(x)]
    if x.size==0: return None
    if kind=="min": return float(np.min(x))
    if kind=="max": return float(np.max(x))
    if kind=="median": return float(np.median(x))
    raise ValueError(kind)

def _v50_abc_history_fp(conn: sqlite3.Connection, asof_date: str) -> tuple[str,str]:
    # Only history strictly before the live as-of day belongs to the persisted baseline.
    row=conn.execute("SELECT MAX(date(日付)) FROM price_history WHERE date(日付) < date(?)", (str(asof_date),)).fetchone()
    prev=str((row or [""])[0] or "")
    if not prev:
        return "", ""
    try:
        fp=_stage2_price_history_fingerprint(conn, prev, 180)
    except Exception:
        fp=""
    return prev, str(fp or "")

def _v50_abc_build_baseline(conn: sqlite3.Connection, rows: list[dict], asof_date: str) -> dict:
    row_codes={
        _live_stock_code(_live_get(r,"コード"),_live_get(r,"市場"),_live_get(r,"銘柄名"))
        for r in (rows or [])
    }
    row_codes.discard("")
    if not row_codes:
        return {}
    asof_ts=pd.Timestamp(asof_date).normalize()
    start=(asof_ts-pd.Timedelta(days=130)).strftime("%Y-%m-%d")
    # Reuse the same V25 raw-normalize semantics used by the legacy A/B/C path.
    if _v25_fast_enabled():
        ph=_v25_legacy_history_frame(conn,start,asof_date,tag="dashboard_research_v50_baseline")
    else:
        ph=_perf_price_history_raw_range(conn,start,asof_date,tag="dashboard_research_v50_baseline")
        if not ph.empty:
            ph["コード"]=ph["コード"].map(canonical_code_for_db)
            ph["日付"]=pd.to_datetime(ph["日付"],errors="coerce").dt.normalize()
            for c in ("始値","高値","安値","終値","出来高"):
                ph[c]=pd.to_numeric(ph[c],errors="coerce")
    if ph.empty:
        return {}
    ph=ph[ph["コード"].isin(row_codes)].copy()
    ph=ph.dropna(subset=["コード","日付","終値"]).sort_values(["コード","日付","_rowid"],kind="stable")
    ph=ph.drop_duplicates(["コード","日付"],keep="last")
    out={}
    for code,g in ph.groupby("コード",sort=False):
        # The legacy MIDDAY path replaces today's stored bar with live OHLCV. For a stable
        # baseline, remove today's row entirely and keep only observations before asof.
        h=g[pd.to_datetime(g["日付"],errors="coerce").dt.normalize() < asof_ts]
        if len(h)<21:
            continue
        close=pd.to_numeric(h["終値"],errors="coerce").to_numpy(dtype=float)
        high=pd.to_numeric(h["高値"],errors="coerce").to_numpy(dtype=float)
        low=pd.to_numeric(h["安値"],errors="coerce").to_numpy(dtype=float)
        vol=pd.to_numeric(h["出来高"],errors="coerce").to_numpy(dtype=float)
        p20=slice(max(0,len(h)-20),len(h)); p5=slice(max(0,len(h)-5),len(h))
        turn=close[p20]*vol[p20]
        out[str(code)]={
            "history_n":int(len(h)),
            "prior20_low":_v50_nan_stat(low[p20],"min"),
            "prior20_high":_v50_nan_stat(high[p20],"max"),
            "vol20":_v50_nan_stat(vol[p20],"median"),
            "vol5":_v50_nan_stat(vol[p5],"median") if len(h)>=4 else None,
            "turn20":_v50_nan_stat(turn,"median"),
            "prev_close":_v50_num_or_none(close[-1]),
            "prev_vol":_v50_num_or_none(vol[-1]),
            "prev19_lows":[_v50_num_or_none(x) for x in low[-19:]],
            "prev9_lows":[_v50_num_or_none(x) for x in low[-9:]],
            "prev9_closes":[_v50_num_or_none(x) for x in close[-9:]],
        }
    return out

def _v50_abc_fast_from_baseline(rows: list[dict], asof_date: str, base: dict) -> dict[str,dict]:
    asof_ts=pd.Timestamp(asof_date).normalize(); out={}
    for r in (rows or []):
        code=_live_stock_code(_live_get(r,"コード"),_live_get(r,"市場"),_live_get(r,"銘柄名"))
        b=base.get(code)
        if not code or not isinstance(b,dict) or int(b.get("history_n") or 0)<21:
            continue
        cur=_live_num(_live_get(r,"現在値_raw","現在値"))
        if cur is None or cur<=0: continue
        opn=_live_num(_live_get(r,"始値","day_open")) or cur
        hi=_live_num(_live_get(r,"高値","day_high")) or cur
        lo=_live_num(_live_get(r,"安値","day_low")) or cur
        vol=_live_num(_live_get(r,"出来高","volume"))
        cur_low=float(min(lo,cur)); cur_high=float(max(hi,cur)); cur_close=float(cur); cur_vol=_v50_num_or_none(vol)
        prior20_low=_v50_num_or_none(b.get("prior20_low")); prior20_high=_v50_num_or_none(b.get("prior20_high"))
        vol20=_v50_num_or_none(b.get("vol20")); vol5=_v50_num_or_none(b.get("vol5")); turn20=_v50_num_or_none(b.get("turn20"))
        prev_close=_v50_num_or_none(b.get("prev_close")); prev_vol=_v50_num_or_none(b.get("prev_vol"))
        ret1=(cur_close/prev_close-1.0) if prev_close not in (None,0) else None
        vol_ratio_prev=(cur_vol/prev_vol) if cur_vol is not None and prev_vol not in (None,0) else None
        dry_ratio=(vol5/vol20) if vol5 is not None and vol20 not in (None,0) else None
        cur_turn=(cur_close*cur_vol) if cur_vol is not None else None
        turn_ratio=(cur_turn/turn20) if cur_turn is not None and turn20 not in (None,0) else None
        clv=((cur_close-cur_low)/(cur_high-cur_low)) if cur_high>cur_low else None
        a2=bool(None not in (prior20_low,prior20_high,cur_low,cur_close,dry_ratio) and cur_low<=prior20_low and (cur_low/prior20_high-1.0)<=-0.08 and dry_ratio<=0.80 and cur_close>prior20_low)
        absorb_count=0; absorb_hit_days=0; undercut_pct=None
        if a2 and prior20_low not in (None,0):
            lows=list(b.get("prev9_lows") or [])+[cur_low]
            closes=list(b.get("prev9_closes") or [])+[cur_close]
            absorb_count,absorb_hit_days,undercut_pct=_absorption_episode_stats(pd.Series(lows,dtype=float),pd.Series(closes,dtype=float),float(prior20_low))
        if a2 and absorb_count>=2 and undercut_pct is not None and -3.0<=undercut_pct<=-0.5:
            a_score,a_label=3,f"◎ {absorb_count}回吸収episode+下抜け奪回"
        elif a2 and absorb_count>=2:
            a_score,a_label=2,f"○ {absorb_count}回吸収episode"
        elif a2:
            a_score,a_label=1,"△ A2奪回"
        else:
            a_score,a_label=0,"-"
        c_on=bool(ret1 is not None and vol_ratio_prev is not None and ret1>=0.029 and vol_ratio_prev>=2.80)
        c_score=1 if c_on else 0; c_label=f"🔥 {vol_ratio_prev:.2f}x/{ret1*100:+.1f}%" if c_on else "-"
        lows20=[x for x in (list(b.get("prev19_lows") or [])+[cur_low]) if x is not None]
        low20_inc=min(lows20) if lows20 else None
        dist_low20=(cur_close/low20_inc-1.0) if low20_inc not in (None,0) else None
        earnings_near=False
        try:
            ed=pd.Timestamp(_live_get(r,"決算発表予定日")).normalize()
            if not pd.isna(ed): earnings_near=asof_ts<=ed<=asof_ts+pd.Timedelta(days=15)
        except Exception:
            earnings_near=False
        b_on=bool(not earnings_near and dist_low20 is not None and dist_low20<=0.10 and ret1 is not None and 0<ret1<=0.10 and dry_ratio is not None and dry_ratio<=0.80 and turn_ratio is not None and turn_ratio>=1.50 and clv is not None and clv>=0.75)
        out[code]={
            "a_score":a_score,"a_label":a_label,"a_absorb_count":absorb_count,"a_absorb_hit_days":absorb_hit_days,"a_undercut_pct":undercut_pct,
            "c_score":c_score,"c_label":c_label,"c_vol_ratio_prev":vol_ratio_prev,"c_ret1_pct":ret1*100.0 if ret1 is not None else None,
            "b_score":1 if b_on else 0,"b_label":"👀 監視" if b_on else "-","b_turn_ratio":turn_ratio,"b_clv":clv,"b_dry_ratio":dry_ratio,
        }
    return out

def _v50_abc_maps_equal(a: dict,b: dict) -> tuple[bool,list]:
    diffs=[]; keys=set(a)|set(b)
    fields=("a_score","a_label","a_absorb_count","a_absorb_hit_days","a_undercut_pct","c_score","c_label","c_vol_ratio_prev","c_ret1_pct","b_score","b_label","b_turn_ratio","b_clv","b_dry_ratio")
    for k in sorted(keys):
        x=a.get(k); y=b.get(k)
        if x is None or y is None:
            if x!=y: diffs.append((k,"presence",x,y))
            if len(diffs)>=10: break
            continue
        for f in fields:
            xv=x.get(f); yv=y.get(f)
            if isinstance(xv,(int,float,np.integer,np.floating)) or isinstance(yv,(int,float,np.integer,np.floating)):
                xn=_v50_num_or_none(xv); yn=_v50_num_or_none(yv)
                ok=(xn is None and yn is None) or (xn is not None and yn is not None and abs(xn-yn)<=1e-9*max(1.0,abs(xn),abs(yn)))
            else:
                ok=(xv==yv)
            if not ok:
                diffs.append((k,f,xv,yv)); break
        if len(diffs)>=10: break
    return (len(diffs)==0),diffs

def _dashboard_research_signal_map(conn: sqlite3.Connection, rows: list[dict], asof_date: str) -> dict[str, dict]:
    mode=str(_auto_run_mode() or RUN_SESSION or "UNKNOWN").upper()
    if mode!="MIDDAY" or not _v50_abc_enabled():
        return _dashboard_research_signal_map_legacy_v50(conn,rows,asof_date)
    t0=time.perf_counter()
    try:
        prev,fp=_v50_abc_history_fp(conn,asof_date)
        if not prev or not fp:
            raise RuntimeError("previous-history fingerprint unavailable")
        cache=None
        try:
            with _V50_ABC_CACHE_PATH.open("rb") as f: cache=pickle.load(f)
        except Exception:
            cache=None
        hit=bool(isinstance(cache,dict) and int(cache.get("schema") or 0)==_V50_ABC_CACHE_SCHEMA and str(cache.get("asof") or "")==str(asof_date) and str(cache.get("prev") or "")==prev and str(cache.get("history_fp") or "")==fp and bool(cache.get("audit_ok")) and isinstance(cache.get("base"),dict))
        if hit:
            base=cache["base"]
            out=_v50_abc_fast_from_baseline(rows,asof_date,base)
            dt=time.perf_counter()-t0; _perf_record_phase("export-detail:abc_v50_cache_hit",dt,"HIT")
            print(f"[V50-ABC] HIT asof={asof_date} base={len(base)} out={len(out)} dt={dt:.2f}s",flush=True)
            return out
        # First valid run for this day/history revision: build baseline and audit against exact legacy output.
        b0=time.perf_counter(); base=_v50_abc_build_baseline(conn,rows,asof_date); bdt=time.perf_counter()-b0
        fast=_v50_abc_fast_from_baseline(rows,asof_date,base)
        l0=time.perf_counter(); legacy=_dashboard_research_signal_map_legacy_v50(conn,rows,asof_date); ldt=time.perf_counter()-l0
        ok,diffs=_v50_abc_maps_equal(fast,legacy)
        _perf_record_phase("export-detail:abc_v50_baseline_build",bdt,"OK")
        _perf_record_phase("export-detail:abc_v50_legacy_audit",ldt,"OK" if ok else "ERROR",None if ok else str(diffs[:3]))
        if not ok:
            print(f"[V50-ABC][AUDIT-FAIL] diffs={diffs[:5]} -> legacy",flush=True)
            return legacy
        obj={"schema":_V50_ABC_CACHE_SCHEMA,"asof":str(asof_date),"prev":prev,"history_fp":fp,"audit_ok":True,"base":base,"saved_at":_now_jst().isoformat(timespec="seconds")}
        try:
            _V50_ABC_CACHE_PATH.parent.mkdir(parents=True,exist_ok=True)
            tmp=_V50_ABC_CACHE_PATH.with_suffix(_V50_ABC_CACHE_PATH.suffix+f".{os.getpid()}.tmp")
            with tmp.open("wb") as f: pickle.dump(obj,f,protocol=pickle.HIGHEST_PROTOCOL)
            os.replace(tmp,_V50_ABC_CACHE_PATH)
        except Exception as e:
            print(f"[V50-ABC][WARN] cache store failed: {e}",flush=True)
        dt=time.perf_counter()-t0; _perf_record_phase("export-detail:abc_v50_first_audited",dt,"OK")
        print(f"[V50-ABC] AUDIT-PASS base={len(base)} out={len(fast)} build={bdt:.2f}s legacy={ldt:.2f}s total={dt:.2f}s",flush=True)
        return fast
    except Exception as e:
        print(f"[V50-ABC][WARN] fastpath failed -> legacy: {e}",flush=True)
        return _dashboard_research_signal_map_legacy_v50(conn,rows,asof_date)
# === /PERF-OPT-V50 / MIDDAY-ABC-BASELINE-CACHE ===

def _dashboard_apply_strategy_columns(conn: sqlite3.Connection, rows: list[dict], live_context: dict | None) -> None:
    """売買目的別の6列をrowsへ付加する。既存候補選定には影響しない。"""
    if not rows:
        return
    ctx = live_context or {}
    snapshot = str(ctx.get("snapshot") or _auto_run_mode() or RUN_SESSION or "UNKNOWN").upper()
    asof = str(ctx.get("asof") or _expected_snapshot_date_for_run(snapshot).isoformat())
    daily = ctx.get("daily") or _live_daily_structure_map(conn, asof)
    intraday_map = ctx.get("intraday_map") or {}
    try:
        research = _dashboard_research_signal_map(conn, rows, asof)
        _a_n = sum(1 for _v in research.values() if int(_live_num(_v.get("a_score")) or 0) > 0)
        _a2_n = sum(1 for _v in research.values() if int(_live_num(_v.get("a_score")) or 0) >= 2)
        _a3_n = sum(1 for _v in research.values() if int(_live_num(_v.get("a_score")) or 0) >= 3)
        _b_n = sum(1 for _v in research.values() if int(_live_num(_v.get("b_score")) or 0) > 0)
        _c_n = sum(1 for _v in research.values() if int(_live_num(_v.get("c_score")) or 0) > 0)
        _a_sample = [str(_k) for _k,_v in research.items() if int(_live_num(_v.get("a_score")) or 0) > 0][:10]
        _b_sample = [str(_k) for _k,_v in research.items() if int(_live_num(_v.get("b_score")) or 0) > 0][:10]
        print(
            f"[dashboard-research] mode={snapshot} asof={asof} mapped={len(research)} "
            f"A>0={_a_n} A>=2={_a2_n} A>=3={_a3_n} B>0={_b_n} C>0={_c_n} "
            f"A_sample={','.join(_a_sample) or '-'} B_sample={','.join(_b_sample) or '-'}"
        )
    except Exception as e:
        print(f"[dashboard-strategy][WARN] A/B/C research columns unavailable: {e}")
        research = {}

    for r in rows:
        code = _live_stock_code(_live_get(r,"コード"), _live_get(r,"市場"), _live_get(r,"銘柄名"))
        d = daily.get(code,{})
        x = intraday_map.get(code,{})
        current = _live_num(_live_get(r,"現在値_raw","現在値"))
        turn = _live_num(_live_get(r,"売買代金億","売買代金(億)"))
        dr = _live_num(_live_get(r,"前日終値比率_raw","前日終値比率"))
        steady_score, steady_on, steady_reason = _live_steady_score(d,x,current,turn,dr)
        rr = research.get(code,{})
        a_score = int(rr.get("a_score") or 0)
        c_on = bool(rr.get("c_score"))
        b_on = bool(rr.get("b_score"))

        r["持続上昇スコア"] = steady_score
        r["持続上昇フラグ"] = "候補" if steady_on else ""
        r["持続上昇"] = (
            "DATA不足" if steady_score is None
            else (f"◎ {steady_score:.0f}" if steady_on else f"{steady_score:.0f}")
        )
        r["持続上昇理由"] = " / ".join(steady_reason[:6])

        r["底反転スコア"] = a_score
        r["底反転"] = rr.get("a_label") or "-"
        r["底反転吸収回数"] = rr.get("a_absorb_count")
        r["底反転吸収日数"] = rr.get("a_absorb_hit_days")
        r["底反転下抜け_pct"] = rr.get("a_undercut_pct")

        r["急伸スコア"] = int(rr.get("c_score") or 0)
        r["急伸"] = rr.get("c_label") or "-"
        r["急伸出来高倍率"] = rr.get("c_vol_ratio_prev")
        r["急伸当日騰落_pct"] = rr.get("c_ret1_pct")

        r["材料先行スコア"] = int(rr.get("b_score") or 0)
        r["材料先行"] = rr.get("b_label") or "-"

        # 持越し適性: 研究/既存戦略の優先度を5段階にまとめる。確率ではない。
        if steady_on and steady_score >= 85:
            hold_rank = 5
        elif steady_on and steady_score >= 75:
            hold_rank = 4
        elif a_score >= 3:
            hold_rank = 4
        elif steady_on or a_score >= 2:
            hold_rank = 3
        elif c_on:
            hold_rank = 2
        else:
            hold_rank = 1
        if current is not None and current <= LIVE_LOW_PRICE_MAX and hold_rank > 1:
            hold_rank -= 1
        if dr is not None and dr > LIVE_STEADY_MAX_DAY_RETURN_PCT and hold_rank > 2:
            hold_rank -= 1
        pull = _live_num(x.get("max_pullback_pct"))
        if pull is not None and pull < -1.5 and hold_rank > 2:
            hold_rank -= 1
        hold_rank = int(max(1,min(5,hold_rank)))
        r["持越し適性ランク"] = hold_rank
        r["持越し適性"] = "★" * hold_rank + "☆" * (5-hold_rank)

        # 今買える?: 板/歩み値の無い一次判定。◎は出さず最終LIVE確認を残す。
        r20 = _live_num(x.get("ret_20m"))
        intraday_has = sum(_live_num(x.get(k)) is not None for k in ("ret_10m","ret_20m","ret_30m","ret_60m")) >= 2
        if dr is not None and dr > 10.0:
            entry_rank, entry_label = 1, "△ 過熱待ち"
        elif pull is not None and pull < -2.0:
            entry_rank, entry_label = 1, "△ 崩れ確認"
        elif steady_on and ((not intraday_has) or (r20 is not None and r20 > 0)):
            entry_rank, entry_label = 3, "○ 持続候補"
        elif a_score >= 3 and ((not intraday_has) or (r20 is not None and r20 > 0)):
            entry_rank, entry_label = 3, "○ 反転候補"
        elif c_on:
            entry_rank, entry_label = 2, "△ 急伸注意"
        elif (steady_score is not None and steady_score >= LIVE_STEADY_MIN_SCORE) or a_score >= 1 or b_on:
            entry_rank, entry_label = 2, "△ 追加確認"
        else:
            entry_rank, entry_label = 0, "-"
        r["今買えるランク"] = entry_rank
        r["今買える"] = entry_label



# ==============================================================================
# P4-DASH6: 全銘柄フォロースルー環境 × 個別相場耐性
# ==============================================================================
ENTRY_ENV_RECENT_TRADE_DAYS = max(3, int(os.environ.get("KABU_ENTRY_ENV_RECENT_DAYS", "10")))
ENTRY_ENV_BASELINE_TRADE_DAYS = max(5, int(os.environ.get("KABU_ENTRY_ENV_BASELINE_DAYS", "20")))
ENTRY_ENV_HISTORY_CALENDAR_DAYS = max(120, int(os.environ.get("KABU_ENTRY_ENV_HISTORY_CALENDAR_DAYS", "170")))
ENTRY_ENV_MIN_OBS = max(30, int(os.environ.get("KABU_ENTRY_ENV_MIN_OBS", "80")))


def _entry_env_clamp(v, lo=0.0, hi=100.0):
    try:
        return max(lo, min(hi, float(v)))
    except Exception:
        return None


def _entry_env_regime(score):
    s = _live_num(score)
    if s is None:
        return "N", "DATA不足"
    if s >= 68:
        return "A", "追随型"
    if s >= 52:
        return "B", "選別型"
    if s >= 38:
        return "C", "逆回転型"
    return "D", "リスクオフ"


def _entry_env_current_setup_bucket(r: dict) -> str:
    """現在行を価格構造ベースの大分類へ寄せる。候補集合は作らず、行ごとの比較群を選ぶだけ。"""
    if _live_flag(r, "INITIAL_MOMENTUM") or int(_live_num(r.get("急伸スコア")) or 0) > 0:
        return "MOMENTUM"
    if int(_live_num(r.get("底反転スコア")) or 0) > 0:
        return "REVERSAL"
    early = str(r.get("右肩早期種別") or "")
    if "20MAリバ" in early or "ポケット" in early:
        return "PULLBACK"
    steady = _live_num(r.get("持続上昇スコア"))
    if steady is not None and steady >= LIVE_STEADY_MIN_SCORE:
        return "STEADY"
    return "OTHER"


def _entry_env_resilience_score(r: dict) -> tuple[float | None, str, list[str]]:
    """今の悪地合いでも個別株が崩れにくい構造かを0-100で評価する。

    市場統計とは分離し、RS・持続構造・支持位置・場中引け位置・流動性/RVOL・Safetyを
    取得できた項目だけで再正規化する。欠損を0点扱いしない。
    """
    comps = []
    reasons = []

    def add(score, weight, reason=None):
        sc = _entry_env_clamp(score)
        if sc is None:
            return
        comps.append((sc, float(weight)))
        if reason:
            reasons.append(str(reason))

    rs5 = _live_num(r.get("RS_5"))
    if rs5 is not None:
        add(50.0 + rs5 * 400.0, 18, f"RS5={rs5*100:+.1f}%")
    rs20 = _live_num(r.get("RS_20"))
    if rs20 is not None:
        add(50.0 + rs20 * 250.0, 12, f"RS20={rs20*100:+.1f}%")

    steady = _live_num(r.get("持続上昇スコア"))
    if steady is not None:
        add(steady, 20, f"持続={steady:.0f}")

    p = _live_num(_live_get(r, "現在値_raw", "現在値"))
    sup = _live_num(_live_get(r, "最寄り支持", "支持線今日", "support_today"))
    if p is not None and p > 0 and sup is not None and sup > 0:
        d = (p / sup - 1.0) * 100.0
        if d < -0.5:
            sc = 18
        elif d <= 2.0:
            sc = 92
        elif d <= 5.0:
            sc = 82
        elif d <= 10.0:
            sc = 66
        elif d <= 18.0:
            sc = 52
        else:
            sc = 42
        add(sc, 14, f"支持距離={d:+.1f}%")

    hi = _live_num(_live_get(r, "高値", "day_high"))
    lo = _live_num(_live_get(r, "安値", "day_low"))
    if p is not None and hi is not None and lo is not None and hi > lo:
        clv = (p - lo) / (hi - lo) * 100.0
        add(clv, 12, f"場中位置={clv:.0f}%")

    turn = _live_num(_live_get(r, "売買代金(億)", "売買代金億", "turnover_oku"))
    if turn is not None:
        if turn < 0.3: sc = 25
        elif turn < 1.0: sc = 40
        elif turn < 3.0: sc = 55
        elif turn < 10.0: sc = 70
        elif turn < 30.0: sc = 82
        else: sc = 92
        add(sc, 8, f"代金={turn:.1f}億")

    rv = _live_num(r.get("RVOL代金"))
    if rv is not None:
        if rv < 0.5: sc = 35
        elif rv < 0.8: sc = 45
        elif rv < 1.2: sc = 55
        elif rv < 1.5: sc = 64
        elif rv < 2.0: sc = 74
        elif rv < 3.0: sc = 84
        else: sc = 92
        add(sc, 7, f"RVOL代金={rv:.2f}")

    safety = _live_num(r.get("tri_safety"))
    if safety is not None:
        add(safety, 6, f"Safety={safety:.0f}")

    jq = str(r.get("短期需給判定") or "")
    if jq:
        if "高RVOL上昇" in jq: sc = 82
        elif "強い売り" in jq: sc = 22
        elif "低RVOL下落" in jq: sc = 35
        elif "低RVOL上昇" in jq: sc = 45
        else: sc = 50
        add(sc, 3, jq)

    if not comps:
        return None, "⚪ DATA不足", []
    total_w = sum(w for _, w in comps)
    score = sum(sc * w for sc, w in comps) / total_w if total_w > 0 else None
    score = round(float(score), 1) if score is not None else None
    if score is None:
        label = "⚪ DATA不足"
    elif score >= 80:
        label = "🛡 強"
    elif score >= 65:
        label = "○ やや強"
    elif score >= 50:
        label = "△ 中立"
    elif score >= 35:
        label = "⚠ 弱"
    else:
        label = "× 脆弱"
    return score, label, reasons


def _entry_env_metric_summary(df: pd.DataFrame) -> dict:
    """全銘柄日次outcomeを絶対水準70% + 過去baseline差30%で評価する。

    P4-DASH8: 「以前より改善した」だけで買いやすい相場としない。中心値・scaleは暫定設計値で、
    学習済み係数ではない。実BUY signal統計が十分になればそちらが主役になる。
    """
    if df is None or df.empty:
        return {"score": None, "absolute_score": None, "delta_score": None, "metrics": {}, "reason": "outcome data empty"}
    recent_n=ENTRY_ENV_RECENT_TRADE_DAYS; base_n=ENTRY_ENV_BASELINE_TRADE_DAYS
    specs={
      "plus_1d":("ret_1d","positive_rate"),"plus_3d":("ret_3d","positive_rate"),
      "plus_5d":("ret_5d","positive_rate"),"plus_10d":("ret_10d","positive_rate"),
      "hit_plus2_5d":("hit2_5d","bool_rate"),"mfe_5d":("mfe_5d","median_pct"),
      "mae_5d":("mae_5d","median_pct"),"mfe_10d":("mfe_10d","median_pct"),
      "mae_10d":("mae_10d","median_pct"),"break_fail_3d":("break_fail_3d","bool_rate"),
    }
    def agg(v,kind):
        x=pd.to_numeric(v,errors="coerce").dropna()
        if x.empty:return None
        if kind=="positive_rate":return float((x>0).mean()*100.0)
        if kind=="bool_rate":return float(x.mean()*100.0)
        return float(x.median()*100.0)
    out={}
    for key,(col,kind) in specs.items():
        if col not in df.columns:
            out[key]={"recent":None,"baseline":None,"n_recent":0,"n_baseline":0,"asof":None};continue
        work=df[["entry_date",col]].copy();work[col]=pd.to_numeric(work[col],errors="coerce");work=work.dropna(subset=[col])
        if work.empty:
            out[key]={"recent":None,"baseline":None,"n_recent":0,"n_baseline":0,"asof":None};continue
        dates=sorted(work["entry_date"].astype(str).unique().tolist())
        rd=dates[-recent_n:]; bd=dates[-(recent_n+base_n):-recent_n] if len(dates)>recent_n else []
        rv=work[work["entry_date"].astype(str).isin(rd)][col]; bv=work[work["entry_date"].astype(str).isin(bd)][col]
        r=agg(rv,kind); b=agg(bv,kind); nr=int(rv.notna().sum()); nb=int(bv.notna().sum())
        out[key]={"recent":None if r is None else round(r,2),"baseline":None if b is None else round(b,2),
                  "recent_for_score":None if nr<ENTRY_ENV_MIN_OBS or r is None else round(r,2),
                  "baseline_for_score":None if nb<ENTRY_ENV_MIN_OBS or b is None else round(b,2),
                  "n_recent":nr,"n_baseline":nb,"recent_days":len(rd),"baseline_days":len(bd),"asof":rd[-1] if rd else None}
    abs_specs={
      "plus_1d":(14,50,1.4,True),"plus_3d":(14,50,1.4,True),"plus_5d":(14,50,1.4,True),
      "plus_10d":(10,50,1.3,True),"hit_plus2_5d":(16,40,1.25,True),
      "mfe_5d":(10,2.0,15.0,True),"mae_5d":(10,-2.0,15.0,True),"break_fail_3d":(12,40,1.25,False),
    }
    ap=[]
    for key,(w,center,scale,higher) in abs_specs.items():
        v=_live_num((out.get(key)or{}).get("recent_for_score"))
        if v is None:continue
        comp=_entry_env_clamp(50.0+((v-center) if higher else (center-v))*scale)
        if comp is not None:ap.append((comp,float(w)))
    abs_score=sum(v*w for v,w in ap)/sum(w for _,w in ap) if ap else None
    delta_specs={"plus_1d":(12.5,True),"plus_3d":(12.5,True),"plus_5d":(12.5,True),"plus_10d":(12.5,True),
                 "hit_plus2_5d":(12.5,True),"mfe_5d":(1.5,True),"mae_5d":(1.5,True),"break_fail_3d":(15.0,False)}
    dp=[]
    for key,(scale,higher) in delta_specs.items():
        m=out.get(key)or{};r=_live_num(m.get("recent_for_score"));b=_live_num(m.get("baseline_for_score"))
        if r is None or b is None:continue
        delta=(r-b) if higher else (b-r); comp=_entry_env_clamp(50.0+50.0*(delta/float(scale)))
        if comp is not None:dp.append(comp)
    delta_score=sum(dp)/len(dp) if dp else None
    score=None if abs_score is None else (abs_score if delta_score is None else abs_score*0.70+delta_score*0.30)
    score=None if score is None else round(float(_entry_env_clamp(score)),1)
    return {"score":score,"absolute_score":None if abs_score is None else round(float(abs_score),1),
            "delta_score":None if delta_score is None else round(float(delta_score),1),"metrics":out,
            "score_note":"absolute70_delta30; heuristic centers, not trained coefficients"}


def _entry_env_build_outcomes(conn: sqlite3.Connection, rows: list[dict], asof: str) -> tuple[pd.DataFrame, set[str]]:
    """price_historyから全個別株の日次買いoutcomeを作る。

    これは候補抽出ではない。現在screening universeの個別株を全て母集団にし、
    各営業日の終値で買った仮定の1/3/5/10日後・MFE/MAE等を横断集計する。
    銘柄ごとの計算はNumPy配列でまとめて行い、3590銘柄×日数をPythonの行ループにしない。
    """
    stock_codes = set()
    for r in rows:
        c = _live_stock_code(_live_get(r, "コード"), _live_get(r, "市場"), _live_get(r, "銘柄名"))
        if c:
            stock_codes.add(c)
    if not stock_codes:
        return pd.DataFrame(), set()

    # FINAL-CONSISTENCY: outcomeは確定引けだけを使う。
    # MIDDAYのprice_history.終値はlive currentであり、前日entryの「翌日終値」にしてはいけない。
    outcome_asof = _confirmed_daily_outcome_cutoff(asof)
    if str(outcome_asof) != str(asof):
        print(f"[entry-env] confirmed outcome cutoff: requested={asof} -> {outcome_asof}")
    start = (pd.Timestamp(outcome_asof) - pd.Timedelta(days=ENTRY_ENV_HISTORY_CALENDAR_DAYS)).strftime("%Y-%m-%d")
    ph = _perf_price_history_raw_range(conn, start, outcome_asof, tag="entry_env")
    if ph.empty:
        return pd.DataFrame(), stock_codes
    # P4-DASH8: 全銘柄地合いoutcomeも共通の論理価格履歴を使い、休日legacy足を除外。
    ph = _dedupe_price_history_df(ph)
    ph["日付"] = pd.to_datetime(ph["日付"], errors="coerce")
    ph = ph.dropna(subset=["コード", "日付"])
    ph = ph[ph["コード"].astype(str).isin(stock_codes)].copy()
    if ph.empty:
        return pd.DataFrame(), stock_codes
    for c in ("始値", "高値", "安値", "終値", "出来高"):
        ph[c] = pd.to_numeric(ph[c], errors="coerce")
    ph = ph.dropna(subset=["終値"])
    ph = ph[np.isfinite(ph["終値"]) & (ph["終値"] > 0)].copy()

    parts = []

    def _future_extreme(arr: np.ndarray, h: int, mode: str) -> np.ndarray:
        n = len(arr)
        out = np.full(n, np.nan, dtype=float)
        if n <= h:
            return out
        # window[j] = arr[j:j+h]。entry i のfutureは j=i+1。
        win = np.lib.stride_tricks.sliding_window_view(arr, h)
        fw = win[1:n-h+1]
        if len(fw) != n-h:
            return out
        valid = np.all(np.isfinite(fw), axis=1)
        vals = np.full(len(fw), np.nan, dtype=float)
        if valid.any():
            vals[valid] = np.max(fw[valid], axis=1) if mode == "max" else np.min(fw[valid], axis=1)
        out[:n-h] = vals
        return out

    for code, g in ph.groupby("コード", sort=False):
        g = g.sort_values("日付", kind="stable")
        n = len(g)
        if n < 35:
            continue
        dates = g["日付"].dt.strftime("%Y-%m-%d").to_numpy(dtype=object)
        close = g["終値"].to_numpy(dtype=float)
        high = g["高値"].to_numpy(dtype=float)
        low = g["安値"].to_numpy(dtype=float)
        vol = g["出来高"].to_numpy(dtype=float)

        sc = pd.Series(close)
        sh = pd.Series(high)
        sl = pd.Series(low)
        sv = pd.Series(vol)
        ma5 = sc.rolling(5, min_periods=5).mean().to_numpy()
        ma25 = sc.rolling(25, min_periods=25).mean().to_numpy()
        ma75 = sc.rolling(75, min_periods=75).mean().to_numpy()
        prev_high20 = sh.rolling(20, min_periods=10).max().shift(1).to_numpy()
        prev_low20 = sl.rolling(20, min_periods=10).min().shift(1).to_numpy()
        prev_vol20 = sv.rolling(20, min_periods=10).mean().shift(1).to_numpy()

        prev = np.full(n, np.nan, dtype=float)
        prev[1:] = close[:-1]
        day_ret = np.full(n, np.nan, dtype=float)
        ok_prev = np.isfinite(prev) & (prev > 0) & np.isfinite(close) & (close > 0)
        day_ret[ok_prev] = close[ok_prev] / prev[ok_prev] - 1.0
        vr = np.full(n, np.nan, dtype=float)
        ok_vr = np.isfinite(vol) & np.isfinite(prev_vol20) & (prev_vol20 > 0)
        vr[ok_vr] = vol[ok_vr] / prev_vol20[ok_vr]

        setup = np.full(n, "OTHER", dtype=object)
        steady_mask = (
            np.isfinite(ma5) & np.isfinite(ma25) & np.isfinite(ma75)
            & (ma5 > ma25) & (ma25 > ma75) & (close >= ma5 * 0.995)
        )
        pull_mask = (
            np.isfinite(ma25) & np.isfinite(ma75) & (ma25 > ma75)
            & (close >= ma25)
            & (~np.isfinite(ma5) | (close <= ma5 * 1.02))
            & (~np.isfinite(day_ret) | (day_ret > -0.03))
        )
        reversal_mask = (
            np.isfinite(prev_low20) & (prev_low20 > 0) & np.isfinite(prev)
            & (prev <= prev_low20 * 1.03) & np.isfinite(day_ret) & (day_ret >= 0.01)
        )
        momentum_mask = np.isfinite(day_ret) & (day_ret >= 0.02) & np.isfinite(vr) & (vr >= 2.0)
        setup[steady_mask] = "STEADY"
        setup[pull_mask] = "PULLBACK"
        setup[reversal_mask] = "REVERSAL"
        setup[momentum_mask] = "MOMENTUM"  # 優先順位はMOMENTUM > REVERSAL > PULLBACK > STEADY

        data = {
            "entry_date": dates,
            "code": np.full(n, str(code), dtype=object),
            "setup": setup,
        }
        for h in (1, 3, 5, 10):
            ret = np.full(n, np.nan, dtype=float)
            if n > h:
                base = close[:-h]
                fut = close[h:]
                ok = np.isfinite(base) & (base > 0) & np.isfinite(fut) & (fut > 0)
                temp = np.full(n-h, np.nan, dtype=float)
                temp[ok] = fut[ok] / base[ok] - 1.0
                ret[:n-h] = temp
            data[f"ret_{h}d"] = ret

        fh5 = _future_extreme(high, 5, "max")
        fl5 = _future_extreme(low, 5, "min")
        fh10 = _future_extreme(high, 10, "max")
        fl10 = _future_extreme(low, 10, "min")
        mfe5 = np.where(np.isfinite(fh5), fh5 / close - 1.0, np.nan)
        mae5 = np.where(np.isfinite(fl5), fl5 / close - 1.0, np.nan)
        mfe10 = np.where(np.isfinite(fh10), fh10 / close - 1.0, np.nan)
        mae10 = np.where(np.isfinite(fl10), fl10 / close - 1.0, np.nan)
        data["mfe_5d"] = mfe5
        data["mae_5d"] = mae5
        data["hit2_5d"] = np.where(np.isfinite(mfe5), (mfe5 >= 0.02).astype(float), np.nan)
        data["mfe_10d"] = mfe10
        data["mae_10d"] = mae10

        breakout = (
            np.isfinite(prev_high20) & (prev_high20 > 0) & (close > prev_high20 * 1.002)
            & np.isfinite(vr) & (vr >= 1.5)
        )
        data["breakout"] = breakout.astype(float)
        fh3 = _future_extreme(high, 3, "max")
        c3 = np.full(n, np.nan, dtype=float)
        if n > 3:
            c3[:n-3] = close[3:]
        bf = np.full(n, np.nan, dtype=float)
        valid_bf = breakout & np.isfinite(fh3) & np.isfinite(c3)
        bf[valid_bf] = ((fh3[valid_bf] < close[valid_bf] * 1.02) & (c3[valid_bf] < close[valid_bf])).astype(float)
        data["break_fail_3d"] = bf
        parts.append(pd.DataFrame(data))

    if not parts:
        return pd.DataFrame(), stock_codes
    return pd.concat(parts, ignore_index=True), stock_codes


def _stage2_entry_history_pack(conn: sqlite3.Connection, rows: list[dict], asof: str):
    """Return historical global/setup packs. V22: PREOPEN/MIDDAY/EOD may reuse a fingerprint-matched persistent summary."""
    t0 = time.perf_counter()
    stock_codes = set()
    for r in rows or []:
        c = _live_stock_code(_live_get(r, "コード"), _live_get(r, "市場"), _live_get(r, "銘柄名"))
        if c:
            stock_codes.add(c)
    mode = str(_auto_run_mode() or "").upper()
    outcome_asof = _confirmed_daily_outcome_cutoff(asof)
    cache_key = None
    if mode in ("PREOPEN", "MIDDAY", "EOD") and stock_codes:
        hist_fp = _stage2_price_history_fingerprint(conn, outcome_asof, 240)
        codes_fp = _stage2_codes_hash(stock_codes)
        cache_key = {
            "schema": _STAGE2_CACHE_SCHEMA,
            "logic_token": _V67_ENTRY_CACHE_LOGIC_TOKEN,
            "outcome_asof": str(outcome_asof),
            "history_fp": hist_fp,
            "codes_fp": codes_fp,
            "recent_days": int(ENTRY_ENV_RECENT_TRADE_DAYS),
            "baseline_days": int(ENTRY_ENV_BASELINE_TRADE_DAYS),
            "history_days": int(ENTRY_ENV_HISTORY_CALENDAR_DAYS),
            "min_obs": int(ENTRY_ENV_MIN_OBS),
        }
        old = _stage2_json_read(_STAGE2_ENTRY_CACHE_PATH)
        _v67_entry_logic_ok, _v67_entry_needs_migration = _v67_cache_logic_compatible(
            old, _V67_ENTRY_CACHE_LOGIC_TOKEN
        )
        _v67_entry_base_match = bool(
            hist_fp and isinstance(old, dict) and _v67_entry_logic_ok
            and all(old.get(k) == v for k, v in cache_key.items() if k != "logic_token")
        )
        if _v67_entry_base_match:
            gp = old.get("global_pack")
            ss = old.get("setup_scores")
            if isinstance(gp, dict) and isinstance(ss, dict) and all(k in ss for k in ("MOMENTUM", "STEADY", "PULLBACK", "REVERSAL")):
                if _v67_entry_needs_migration:
                    _v67_migrate_cache_token(
                        _STAGE2_ENTRY_CACHE_PATH, old, _V67_ENTRY_CACHE_LOGIC_TOKEN, "ENTRY"
                    )
                dt = time.perf_counter() - t0
                print(f"[ENTRY-V22-CACHE] HIT asof={outcome_asof} universe={len(stock_codes)} dt={dt:.2f}s", flush=True)
                return gp, ss, stock_codes, {"status": "hit", "outcomes_seconds": dt, "hist_seconds": 0.0}

    calc0 = time.perf_counter()
    outcomes, stock_codes = _entry_env_build_outcomes(conn, rows, asof)
    calc1 = time.perf_counter()
    global_pack = _entry_env_metric_summary(outcomes)
    setup_scores = {}
    for bucket in ("MOMENTUM", "STEADY", "PULLBACK", "REVERSAL"):
        sub = outcomes[outcomes["setup"].eq(bucket)] if not outcomes.empty else pd.DataFrame()
        pack = _entry_env_metric_summary(sub)
        setup_scores[bucket] = {
            "score": pack.get("score"),
            "metrics": pack.get("metrics") or {},
            "n": int(len(sub)),
        }
    calc2 = time.perf_counter()
    if mode in ("PREOPEN", "MIDDAY", "EOD") and cache_key and stock_codes:
        obj = {
            **cache_key,
            "build_token": str(_daily_build_token()),
            "global_pack": global_pack,
            "setup_scores": setup_scores,
            "universe_count": int(len(stock_codes)),
            "saved_at": _now_jst().isoformat(timespec="seconds"),
        }
        if _stage2_json_write(_STAGE2_ENTRY_CACHE_PATH, obj):
            print(f"[ENTRY-V22-CACHE] STORE asof={outcome_asof} universe={len(stock_codes)}", flush=True)
    return global_pack, setup_scores, stock_codes, {
        "status": "miss",
        "outcomes_seconds": calc1 - calc0,
        "hist_seconds": calc2 - calc1,
    }


def _dashboard_apply_entry_environment(conn: sqlite3.Connection, rows: list[dict], asof: str) -> dict:
    """全個別株の実績環境を背景に、各銘柄へ相場耐性/地合い込み一次判定を付ける。"""
    meta = {
        "version": 2,
        "universe": "ALL_STOCKS",
        "asof": str(asof),
        "score": None,
        "historical_score": None,
        "regime_code": "N",
        "regime": "DATA不足",
        "universe_count": 0,
        "metrics": {},
        "setup_scores": {},
        "signal_environment": {},
        "signal_setup_scores": {},
        "breadth": {},
        "recent_trade_days": ENTRY_ENV_RECENT_TRADE_DAYS,
        "baseline_trade_days": ENTRY_ENV_BASELINE_TRADE_DAYS,
        "note": "全個別株の日次統計をfallbackにし、導入後に実際の『今買える？=○』初回signal実績が十分たまればそちらを主役にする。",
    }
    try:
        _env_t0 = time.perf_counter()
        global_pack, setup_scores, stock_codes, _entry_hist_perf = _stage2_entry_history_pack(conn, rows, asof)
        _env_t_hist = time.perf_counter()
        meta["universe_count"] = int(len(stock_codes))
        hist_score = _live_num(global_pack.get("score"))
        meta["historical_score"] = hist_score
        meta["metrics"] = global_pack.get("metrics") or {}
        meta["setup_scores"] = setup_scores
        _entry_hist_outcomes_sec = float((_entry_hist_perf or {}).get("outcomes_seconds") or 0.0)
        _entry_hist_summary_sec = float((_entry_hist_perf or {}).get("hist_seconds") or 0.0)

        # P4-DASH7: 過去runで実際に『今買える？=○』になった最初の時点を追跡。
        signal_env = _entry_signal_metric_summary()
        signal_setup_scores = {}
        for bucket in ("MOMENTUM", "STEADY", "PULLBACK", "REVERSAL", "OTHER"):
            signal_setup_scores[bucket] = _entry_signal_metric_summary(bucket)
        meta["signal_environment"] = signal_env
        meta["signal_setup_scores"] = signal_setup_scores
        _env_t_signal = time.perf_counter()

        # 今日の全個別株breadthは補助。実signalが十分ならsignal実績を主役にする。
        stock_rows = []
        for r in rows:
            c = _live_stock_code(_live_get(r, "コード"), _live_get(r, "市場"), _live_get(r, "銘柄名"))
            if c:
                stock_rows.append(r)
        day_ret = [_live_num(r.get("前日終値比率")) for r in stock_rows]
        day_ret = [v for v in day_ret if v is not None]
        rs5 = [_live_num(r.get("RS_5")) for r in stock_rows]
        rs5 = [v for v in rs5 if v is not None]
        above25 = []
        strong_down = []
        for r in stock_rows:
            p = _live_num(r.get("現在値")); ma25 = _live_num(_live_get(r, "MA25", "25日", "２５日"))
            if p is not None and ma25 is not None and ma25 > 0:
                above25.append(int(p > ma25))
            st = _live_num(r.get("持続上昇スコア")); dr = _live_num(r.get("前日終値比率"))
            if st is not None and st >= LIVE_STEADY_MIN_SCORE and dr is not None:
                strong_down.append(int(dr < 0))
        adv = (sum(v > 0 for v in day_ret) / len(day_ret) * 100.0) if day_ret else None
        rs5p = (sum(v > 0 for v in rs5) / len(rs5) * 100.0) if rs5 else None
        ma25p = (sum(above25) / len(above25) * 100.0) if above25 else None
        strong_down_rate = (sum(strong_down) / len(strong_down) * 100.0) if strong_down else None
        meta["breadth"] = {
            "advancing_rate": None if adv is None else round(adv, 2),
            "rs5_positive_rate": None if rs5p is None else round(rs5p, 2),
            "above_ma25_rate": None if ma25p is None else round(ma25p, 2),
            "steady_down_rate": None if strong_down_rate is None else round(strong_down_rate, 2),
            "n": len(stock_rows),
        }
        breadth_parts = []
        for val in (adv, rs5p, ma25p):
            if val is not None:
                breadth_parts.append(_entry_env_clamp(50.0 + (val - 50.0) * 1.5))
        breadth_score = (sum(breadth_parts) / len(breadth_parts)) if breadth_parts else None
        signal_score = _live_num(signal_env.get("score"))
        signal_qualified = bool(signal_env.get("qualified"))
        if signal_qualified and signal_score is not None:
            # 実際の買える判定後の成績を70%主役。全銘柄日次20%＋当日breadth10%は補助。
            pieces=[]
            pieces.append((signal_score,0.70))
            if hist_score is not None: pieces.append((hist_score,0.20))
            if breadth_score is not None: pieces.append((breadth_score,0.10))
            global_score=sum(v*w for v,w in pieces)/sum(w for _,w in pieces)
            meta["score_source"]="BUY_SIGNAL_PRIMARY"
        elif hist_score is not None and breadth_score is not None:
            global_score = hist_score * 0.80 + breadth_score * 0.20
            meta["score_source"]="ALL_STOCK_DAILY_FALLBACK"
        elif hist_score is not None:
            global_score = hist_score
            meta["score_source"]="ALL_STOCK_DAILY_FALLBACK"
        else:
            global_score = breadth_score
            meta["score_source"]="BREADTH_ONLY"
        global_score = None if global_score is None else round(float(_entry_env_clamp(global_score)), 1)
        regime_code, regime = _entry_env_regime(global_score)
        meta["score"] = global_score
        meta["breadth_score"] = None if breadth_score is None else round(float(breadth_score), 1)
        meta["regime_code"] = regime_code
        meta["regime"] = regime

        for r in rows:
            resilience, res_label, res_reasons = _entry_env_resilience_score(r)
            setup = _entry_env_current_setup_bucket(r)
            signal_setup = signal_setup_scores.get(setup) or {}
            signal_setup_score = _live_num(signal_setup.get("score")) if bool(signal_setup.get("qualified")) else None
            setup_score = signal_setup_score
            if setup_score is None:
                setup_score = _live_num((setup_scores.get(setup) or {}).get("score"))
            effective_env = global_score
            if global_score is not None and setup_score is not None:
                effective_env = round(global_score * 0.65 + setup_score * 0.35, 1)
            elif setup_score is not None:
                effective_env = setup_score

            r["相場耐性スコア"] = resilience
            r["相場耐性"] = (f"{resilience:.0f} {res_label}" if resilience is not None else res_label)
            r["相場耐性理由"] = " / ".join(res_reasons[:6])
            r["個別買い環境タイプ"] = setup
            r["同型環境スコア"] = setup_score
            r["地合い環境スコア"] = effective_env

            base_rank = int(_live_num(r.get("今買えるランク")) or 0)
            base_score = {0: 20.0, 1: 40.0, 2: 60.0, 3: 80.0}.get(base_rank, 20.0)
            if resilience is None or effective_env is None:
                final_score = None
                final_label = "⚪ 環境統計不足"
            else:
                final_score = 0.50 * base_score + 0.30 * resilience + 0.20 * effective_env
                # 「今買える？」を最初のgateとして尊重。環境だけで非候補を買いへ昇格させない。
                cap = {0: 39.0, 1: 54.0, 2: 69.0, 3: 100.0}.get(base_rank, 39.0)
                final_score = min(final_score, cap)
                # 強い逆風では相場耐性の高い銘柄だけ例外的に残す。
                if effective_env < 35:
                    final_score = min(final_score, 64.0 if resilience >= 80 and base_rank >= 2 else 49.0)
                elif effective_env < 45 and resilience < 60:
                    final_score = min(final_score, 49.0)
                if resilience < 45:
                    final_score = min(final_score, 49.0)
                final_score = round(float(_entry_env_clamp(final_score)), 1)
                if final_score >= 75:
                    final_label = "◎ 買い優位"
                elif final_score >= 62:
                    final_label = "○ 買い検討"
                elif final_score >= 50:
                    final_label = "△ 押し目限定"
                elif final_score >= 40:
                    final_label = "△ 反転確認"
                else:
                    final_label = "× 新規抑制"

            r["地合い込み一次判定スコア"] = final_score
            r["地合い込み一次判定"] = final_label
            m5 = (meta.get("metrics") or {}).get("hit_plus2_5d") or {}
            mfe5 = (meta.get("metrics") or {}).get("mfe_5d") or {}
            mae5 = (meta.get("metrics") or {}).get("mae_5d") or {}
            _fmt = lambda x, suf="": "-" if _live_num(x) is None else f"{float(x):.1f}{suf}"
            r["地合い込み理由"] = (
                f"今買える={r.get('今買える') or '-'} / 相場耐性={_fmt(resilience)} / "
                f"全体={regime_code}{regime} {_fmt(global_score)}[{meta.get('score_source','-')}] / 同型={setup} {_fmt(setup_score)} / "
                f"5日+2%到達={_fmt(m5.get('recent'),'%')} (基準{_fmt(m5.get('baseline'),'%')}) / "
                f"MFE5={_fmt(mfe5.get('recent'),'%')} / MAE5={_fmt(mae5.get('recent'),'%')}"
            )

        _env_t_done = time.perf_counter()
        print(
            f"[entry-env-perf] outcomes={_entry_hist_outcomes_sec:.2f}s "
            f"hist_summary={_entry_hist_summary_sec:.2f}s "
            f"signal_stats={_env_t_signal-_env_t_hist:.2f}s "
            f"attach_breadth={_env_t_done-_env_t_signal:.2f}s total={_env_t_done-_env_t0:.2f}s",
            flush=True,
        )
        return meta
    except Exception as e:
        print(f"[entry-env][WARN] 個別買い環境の計算に失敗: {e}")
        for r in rows:
            resilience, res_label, res_reasons = _entry_env_resilience_score(r)
            r["相場耐性スコア"] = resilience
            r["相場耐性"] = (f"{resilience:.0f} {res_label}" if resilience is not None else res_label)
            r["相場耐性理由"] = " / ".join(res_reasons[:6])
            r["個別買い環境タイプ"] = _entry_env_current_setup_bucket(r)
            r["同型環境スコア"] = None
            r["地合い環境スコア"] = None
            r["地合い込み一次判定スコア"] = None
            r["地合い込み一次判定"] = "⚪ 環境統計不足"
            r["地合い込み理由"] = f"個別買い環境の計算失敗: {e}"
        meta["error"] = str(e)
        try:
            _env_t_done = time.perf_counter()
            print(f"[entry-env-perf][ERROR] elapsed={_env_t_done-_env_t0:.2f}s", flush=True)
        except Exception:
            pass
        return meta


def _dashboard_attach_ui_sort_contract(rows: list[dict]) -> None:
    """P4-DASH3: Python側の意味をdashboardの並べ替えへ明示的に渡す。

    ここで追加する値は UI専用。候補抽出・strategy gate・priority・モデル計算には使わない。
    template側が表示文字列を再解釈して順位を推測しないよう、カテゴリ順位や表示価格の
    数値版をPythonで確定する。古いJSONとの互換はtemplate側のfallbackだけに限定する。
    """
    if not rows:
        return

    _rec_rank = {"エントリー有力": 4, "中強度": 3, "小口提案": 2, "微小口": 1}
    _hist_rank = {"HIGH": 4, "MEDIUM": 3, "LOW": 2, "DATA不足": 1}
    _ma_rank = {"5": 3, "25": 2, "75": 1}  # _pick_ma_label() の優先度 5 > 25 > 75 と一致

    def _alpha_rank(v):
        s = str(v or "").strip().upper().replace("＋", "+").replace("－", "-")
        if not s:
            return None
        m = re.fullmatch(r"([SABCD])(\+\+|--|\+|-)?", s)
        if not m:
            return None
        base = {"S": 500, "A": 400, "B": 300, "C": 200, "D": 100}[m.group(1)]
        adj = {"++": 20, "+": 10, "": 0, None: 0, "-": -10, "--": -20}[m.group(2)]
        return base + adj

    def _shinden_rank(v):
        s = str(v or "").strip()
        if not s:
            return None
        if s.startswith("参考"):
            return 0
        for label, rank in (("S", 5), ("A", 4), ("B", 3), ("C", 2), ("D", 1)):
            if s.startswith(label):
                return rank
        return None

    def _ai_judge_rank(v):
        s = str(v or "").strip()
        if not s or s == "-":
            return None
        if "超強気" in s:
            return 4
        if "到達有望" in s:
            return 3
        if "閾値近辺" in s:
            return 2
        if "閾値未満" in s:
            return 1
        return None

    def _profit_accel_rank(v):
        # _profit_acceleration_quality() の意味順。情報不足は弱い0ではなく未判定(None)。
        s = str(v or "").strip()
        if not s or "情報不足" in s:
            return None
        if "加速" in s and "鈍化" not in s:
            return 3
        if "利益率鈍化" in s:
            return 2  # authoritative flagは立っているが、利益成長が売上成長に劣後
        if s == "-":
            return 1  # authoritative flagが非該当
        return None

    for r in rows:
        g = _live_num(r.get("tri_growth")); s = _live_num(r.get("tri_safety")); v = _live_num(r.get("tri_vol"))
        r["_UI_SORT_TRIANGLE"] = (g * 10000.0 + s * 100.0 + v) if None not in (g, s, v) else None
        r["_UI_SORT_AI_JUDGE"] = _ai_judge_rank(r.get("AI判定"))
        # AI目標値_raw は後方互換名だが、producerの正式意味はAI到達確率(AIスコア)のソート値。
        r["_UI_SORT_AI_TARGET"] = _live_num(r.get("AIスコア"))
        # 信用倍率はdashboard上で「売り残0」と表示する場合があるため、sort用の生数値を分離。
        r["_UI_SORT_CREDIT_RATIO"] = _live_num(r.get("信用倍率"))
        r["仕込み目安価格"] = _live_num(r.get("shikomi_txt"))
        r["利確目安価格"] = _live_num(r.get("rikaku_txt"))
        r["損切目安価格"] = _live_num(r.get("songiri_txt"))
        r["_UI_SORT_RECOMMEND"] = _rec_rank.get(str(r.get("推奨アクション") or "").strip())
        r["_UI_SORT_PROFIT_ACCEL"] = _profit_accel_rank(r.get("利益加速ステータス"))
        r["_UI_SORT_PAST_REACTION"] = _live_num(r.get("決算勝率"))
        r["_UI_SORT_ALPHA"] = _alpha_rank(r.get("overall_alpha"))
        _tob = r.get("tob_titles")
        r["TOB件数"] = len(_tob) if isinstance(_tob, list) else 0
        r["_UI_SORT_SHINDEN_JUDGE"] = _shinden_rank(r.get("シンデン判定"))
        r["_UI_SORT_HISTORY_CONF"] = _hist_rank.get(str(r.get("予想達成履歴信頼度") or "").strip().upper())
        r["_UI_SORT_MA"] = _ma_rank.get(str(r.get("移動平均") or "").strip())


def _dashboard_display_semantics(rows: list[dict]) -> list[dict]:
    """VALUE-SEMANTICS-V1: dashboard表示だけを分かりやすくする。

    raw rows / DB / monitor / LLM / LIVE Candidate Contract は変更しない。
    """
    out = []
    for _src in rows or []:
        r = dict(_src)

        # 信用倍率:
        # 内部999.9は「売り残0・買い残あり」の計算用sentinelとして維持。
        # dashboardだけ「売り残0」と表示し、欠損は「-」にする。
        _mr = _live_num(r.get("信用倍率"))
        _sell = _live_num(r.get("売り残"))
        _buy = _live_num(r.get("買い残"))
        if _sell is not None and abs(_sell) < 1e-12 and _buy is not None and _buy > 0:
            r["信用倍率"] = "売り残0"
        elif _mr is None:
            r["信用倍率"] = "-"

        # 機関空売り:
        # 過去履歴があっても「今回取得未成功 / current不明」なら現在残高を0株に見せない。
        _acq = str(r.get("機関空売り取得状態") or "").strip()
        _cur = str(r.get("機関空売り現在状態") or "不明").strip()
        if _acq != "成功" or _cur not in {"あり", "なし"}:
            r["機関空売り合計株数"] = "-"
            r["本日の増減合計株数"] = "-"

        out.append(r)
    return out


def _live_priority_sort_key(c: dict):
    """Existing scanner priority order. Keep this single definition authoritative."""
    return (
        float(c.get("priority") or 0.0),
        float((c.get("scores") or {}).get("market_score") or 0.0),
        float(c.get("turnover_oku") or 0.0),
        str(c.get("code") or ""),
    )


def _live_select_execution_candidates(all_candidates: list[dict]) -> list[dict]:
    """
    Build LIVE50 from the existing priority ranking while dynamically rescuing
    genuinely strong INITIAL_MOMENTUM candidates.

    INITIAL rescue:
      Tier 1) source_rank <= configured rank cap AND
              priority >= normal LIVE cutoff - 2
      Tier 2) source_rank <= 8 AND market_score >= 95 AND
              priority >= normal LIVE cutoff - 10

    Existing priority TOP50 is the base.
    Base names with market_score >= 95 are protected from displacement.
    STEADY_UP keeps the existing top-N reservation policy for now.
    """
    limit = max(1, int(LIVE_EXECUTION_MAX))
    ranked = sorted(all_candidates, key=_live_priority_sort_key, reverse=True)

    if not ranked:
        return []

    base = ranked[:limit]

    def _priority(c):
        return float(c.get("priority") or 0.0)

    def _market(c):
        return float((c.get("scores") or {}).get("market_score") or 0.0)

    def _source_rank(c, source):
        v = (c.get("source_rank") or {}).get(source)
        try:
            return int(v) if v is not None else None
        except Exception:
            return None

    def _source_sorted(source):
        pool = [
            c for c in all_candidates
            if source in (c.get("sources") or [])
        ]
        pool.sort(key=lambda c: (
            _source_rank(c, source) or 10**9,
            -_priority(c),
            -_market(c),
            -float(c.get("turnover_oku") or 0.0),
            str(c.get("code") or ""),
        ))
        return pool

    cutoff = _priority(base[-1])
    base_codes = {
        str(c.get("code") or "")
        for c in base
        if str(c.get("code") or "")
    }

    selected = {}

    for c in base:
        code = str(c.get("code") or "")
        if code:
            selected[code] = (c, "PRIORITY_FILL")

    # ----- INITIAL dynamic rescue -----
    initial_rank_cap = max(0, int(LIVE_EXECUTION_INITIAL_RESERVED))
    strong_rank_cap = min(10, initial_rank_cap)

    initial_eligible = []

    if initial_rank_cap > 0:
        for c in _source_sorted("INITIAL_MOMENTUM"):
            r = _source_rank(c, "INITIAL_MOMENTUM")

            if r is None or r > initial_rank_cap:
                continue

            # Tier 1: ordinary rescue near the normal LIVE50 cutoff.
            near_cutoff = (
                _priority(c) >= cutoff - 2.0
            )

            # Tier 2: exceptional INITIAL rescue.
            # Allow a larger priority gap only when the INITIAL rank and
            # current market state are both exceptionally strong.
            exceptional_initial = (
                r <= min(8, initial_rank_cap)
                and _market(c) >= 95.0
                and _priority(c) >= cutoff - 10.0
            )

            if near_cutoff or exceptional_initial:
                initial_eligible.append(c)

    initial_codes = set()
    initial_promotions = []

    for c in initial_eligible:
        code = str(c.get("code") or "")

        if not code:
            continue

        initial_codes.add(code)

        if code in selected:
            selected[code] = (selected[code][0], "INITIAL_RESERVED")
        else:
            initial_promotions.append((c, "INITIAL_RESERVED"))

    # ----- STEADY existing reservation -----
    steady_quota = max(0, int(LIVE_EXECUTION_STEADY_RESERVED))
    steady_promotions = []
    steady_added = 0

    for c in _source_sorted("STEADY_UP"):
        if steady_added >= steady_quota:
            break

        code = str(c.get("code") or "")

        if not code or code in initial_codes:
            continue

        steady_added += 1

        if code in selected:
            selected[code] = (selected[code][0], "STEADY_RESERVED")
        else:
            steady_promotions.append((c, "STEADY_RESERVED"))

    # ----- Protect strong base candidates -----
    protected_codes = set()

    for code, (c, bucket) in selected.items():
        if (
            _market(c) >= 95.0
            or bucket in ("INITIAL_RESERVED", "STEADY_RESERVED")
        ):
            protected_codes.add(code)

    evictable = [
        c for c in base
        if str(c.get("code") or "") not in protected_codes
    ]

    # weakest normal candidates first
    evictable.sort(key=lambda c: (
        _priority(c),
        _market(c),
        float(c.get("turnover_oku") or 0.0),
        -int(c.get("priority_rank") or 0),
        str(c.get("code") or ""),
    ))

    promotions = initial_promotions + steady_promotions

    for c, bucket in promotions:
        code = str(c.get("code") or "")

        if not code or code in selected:
            continue

        if len(selected) >= limit:
            if not evictable:
                break

            victim = evictable.pop(0)
            victim_code = str(victim.get("code") or "")
            selected.pop(victim_code, None)

        selected[code] = (c, bucket)

    admitted = sorted(
        selected.values(),
        key=lambda x: _live_priority_sort_key(x[0]),
        reverse=True,
    )[:limit]

    out = []

    for live_rank, (c, bucket) in enumerate(admitted, start=1):
        cc = dict(c)
        cc["live_rank"] = live_rank
        cc["live_selection_bucket"] = bucket

        if bucket == "INITIAL_RESERVED":
            sr = (cc.get("source_rank") or {}).get("INITIAL_MOMENTUM")
            cc["live_selection_reason"] = (
                f"INITIAL_MOMENTUM dynamic reserve / source_rank={sr}"
            )

        elif bucket == "STEADY_RESERVED":
            sr = (cc.get("source_rank") or {}).get("STEADY_UP")
            cc["live_selection_reason"] = (
                f"STEADY_UP reserved / source_rank={sr}"
            )

        else:
            cc["live_selection_reason"] = "existing priority fill"

        out.append(cc)

    return out


def _build_day_elite_focus_lane(rows: list[dict], limit: int | None = None) -> list[dict]:
    """LIVE-FOCUS-NOTIFY-V1: DAY ELITEへ渡す高密度候補レーン。

    OR条件:
      - 現在の主役化状態が 🌈主役化 / 🌈再主役化
      - 現在の主役化状態が 🔥継続期待 / 🔥再点火
      - DIFF_REAL_STRENGTH=1（今日実際に強化中）

    既存 candidate / broker_watch の選定は変更しない。LIVE側が明示的にこの
    laneを採用した時だけDAY ELITEの入口が切り替わる。
    """
    cap = max(1, int(limit or LIVE_EXECUTION_MAX))
    out = []
    seen = set()

    grade_rank = {"S": 4, "A": 3, "B": 2, "C": 1}
    ignition_rank = {"⬆": 2, "→": 1, "⬇": 0}

    for r in rows or []:
        code = _live_stock_code(
            _live_get(r, "コード", "code"),
            _live_get(r, "市場", "market"),
            _live_get(r, "銘柄名", "name"),
        )
        if not code or code in seen:
            continue

        leader_state = str(_live_get(r, "主役化状態") or "").strip()
        is_rainbow = leader_state.startswith("🌈")
        is_fire = leader_state.startswith("🔥")
        is_diff = int(_live_num(_live_get(r, "DIFF_REAL_STRENGTH")) or 0) == 1
        if not (is_rainbow or is_fire or is_diff):
            continue

        focus_sources = []
        if is_fire:
            focus_sources.append("LEADER_CONTINUATION")
        if is_rainbow:
            focus_sources.append("LEADER_MAIN")
        if is_diff:
            focus_sources.append("DIFF_REAL_STRENGTH")
        is_repeat = int(_live_num(_live_get(r, "再主役候補")) or 0) == 1
        if is_repeat:
            focus_sources.append("LEADER_REIGNITION_HISTORY")

        grade = str(_live_get(r, "🔥基礎期待度") or "").strip().upper()
        ignition = str(_live_get(r, "点火進行") or "").strip()
        leader_score = _live_num(_live_get(r, "主役化現在スコア"))
        diff_score = _live_num(_live_get(r, "DIFF_SCORE"))
        diff_rank = _live_num(_live_get(r, "DIFF_RANK"))
        turn = _live_num(_live_get(r, "売買代金(億)", "売買代金億"))
        current = _live_num(_live_get(r, "現在値_raw", "現在値", "current_price"))
        day_ret = _live_num(_live_get(r, "前日終値比率_raw", "前日終値比率", "day_return_pct"))

        item = {
            "code": str(code),
            "name": str(_live_get(r, "銘柄名", "name") or ""),
            "market": str(_live_get(r, "市場", "market") or ""),
            "current_price": current,
            "day_return_pct": day_ret,
            "turnover_oku": turn,
            "rvol_turnover": _live_num(_live_get(r, "RVOL代金")),
            "focus_sources": focus_sources,
            "leader_state": leader_state,
            "fire_expectancy_grade": grade,
            "ignition_progress": ignition,
            "leader_current_score": leader_score,
            "leader_current_mfe_pct": _live_num(_live_get(r, "主役化現在MFE_pct")),
            "leader_current_return_pct": _live_num(_live_get(r, "主役化現在比_pct")),
            "leader_current_vwap_gap_pct": _live_num(_live_get(r, "主役化現在VWAP乖離_pct")),
            "leader_signal_time": str(_live_get(r, "主役化シグナル時刻") or ""),
            "repeat_leader": bool(is_repeat),
            "repeat_leader_score": _live_num(_live_get(r, "再主役研究スコア")),
            "repeat_strength_grade": str(_live_get(r, "再主役強度") or ""),
            "repeat_explosive": bool(int(_live_num(_live_get(r, "再主役爆発級")) or 0)),
            "repeat_calibration_version": str(_live_get(r, "再主役校正版") or ""),
            "repeat_day1_date": str(_live_get(r, "再主役DAY1日") or ""),
            "repeat_persist_date": str(_live_get(r, "再主役継続確認日") or ""),
            "repeat_first_date": str(_live_get(r, "再主役初回日") or ""),
            "repeat_elapsed_sessions": int(_live_num(_live_get(r, "再主役経過営業日")) or 0) if is_repeat else None,
            "repeat_reason": str(_live_get(r, "再主役根拠") or "")[:500],
            "diff_real_strength": bool(is_diff),
            "diff_score": diff_score,
            "diff_rank": int(diff_rank) if diff_rank is not None else None,
            "diff_state": str(_live_get(r, "DIFF_STATE") or ""),
            "diff_reason": str(_live_get(r, "DIFF_REASON") or "")[:500],
            "today_buy": bool(int(_live_num(_live_get(r, "TODAY_BUY")) or 0) == 1),
            "today_score": _live_num(_live_get(r, "TODAY_SCORE")),
            "watch_state": str(_live_get(r, "WATCH_STATE") or ""),
            "invalidation_price": _live_num(_live_get(r, "EXIT_INVALIDATION_PRICE")),
            "entry_permission": "LIVE_CONFIRMATION_REQUIRED",
            "direct_order_allowed": False,
            "_sort_key": (
                1 if is_fire else 0,
                1 if is_rainbow else 0,
                grade_rank.get(grade, 0),
                ignition_rank.get(ignition, 0),
                1 if is_diff else 0,
                float(leader_score if leader_score is not None else -999.0),
                float(diff_score if diff_score is not None else -999.0),
                float(turn if turn is not None else 0.0),
            ),
        }
        out.append(item)
        seen.add(code)

    out.sort(key=lambda x: x["_sort_key"], reverse=True)
    out = out[:cap]
    for rank, item in enumerate(out, start=1):
        item.pop("_sort_key", None)
        item["focus_rank"] = rank
        item["focus_reason"] = " OR ".join(item.get("focus_sources") or [])
    return out


def _live_candidate_payload(conn: sqlite3.Connection, rows: list[dict], context: dict | None = None) -> dict:
    """
    Candidate Contract v2 (safe/minimal).

    Existing scanner selection logic is intentionally preserved:
    - INITIAL_MOMENTUM / STEADY_UP / BOTTOM_REVERSAL gates are unchanged.
    - existing priority formula is unchanged.
    - existing final sort/candidate cap are unchanged.

    v2 only makes lineage/ranking explicit so LIVE does not destroy scanner order.
    """
    generated=_now_jst().isoformat(timespec="seconds")
    _ctx = context or _live_build_context(conn, rows)
    snapshot = str(_ctx.get("snapshot") or _auto_run_mode() or RUN_SESSION or "UNKNOWN").upper()
    asof = str(_ctx.get("asof") or _expected_snapshot_date_for_run(snapshot).isoformat())
    daily = _ctx.get("daily") or {}
    captured = str(_ctx.get("captured") or generated)
    trade_date = str(_ctx.get("trade_date") or _now_jst().date().isoformat())
    snapshot_rows = int(_ctx.get("snapshot_rows") or 0)
    codes = set(_ctx.get("codes") or set())
    intraday_map = _ctx.get("intraday_map") or {}
    candidates=[]; counts={k:0 for k in ("INITIAL_MOMENTUM","STEADY_UP","BOTTOM_REVERSAL","FUNDAMENTAL_EARLY","THEME_DISCOVERY","PRE_EARNINGS","POST_EARNINGS")}

    def _market_segment_from_market(market_value) -> str:
        s=str(market_value or "").strip().upper()
        if s in {"東G","G","GROWTH"} or "グロース" in s or "GROWTH" in s:
            return "GROWTH"
        if s in {"東P","P","PRIME"} or "プライム" in s or "PRIME" in s:
            return "PRIME"
        if s in {"東S","S","STANDARD"} or "スタンダード" in s or "STANDARD" in s:
            return "STANDARD"
        return "UNKNOWN"

    for r in rows:
        code=_live_stock_code(_live_get(r,"コード"),_live_get(r,"市場"),_live_get(r,"銘柄名"))
        if not code: continue
        name=str(_live_get(r,"銘柄名") or ""); market=str(_live_get(r,"市場") or "")
        current=_live_num(_live_get(r,"現在値_raw","現在値")); prev=_live_num(_live_get(r,"前日終値"))
        dr=_live_num(_live_get(r,"前日終値比率_raw","前日終値比率"))
        turn=_live_num(_live_get(r,"売買代金億","売買代金(億)")); rvol=_live_num(_live_get(r,"RVOL代金")); vol=_live_num(_live_get(r,"出来高"))
        d=daily.get(code,{})
        intr=intraday_map.get(code,{})
        steady_score, steady_on, steady_reason=_live_steady_score(d,intr,current,turn,dr)
        bottom_score,bottom_on,bottom_reason=_live_bottom_score(intr,current,_live_get(r,"支持線今日"))
        im_on=_live_flag(r,"INITIAL_MOMENTUM")
        im_score=_live_num(_live_get(r,"INITIAL_MOMENTUM_SCORE")) or 0.0
        # 正式QUALITYは未実装。tri_safety等を意味の異なるproxyとしてsource化しない。
        quality_score=None
        market_score=_live_num(_live_get(r,"合成スコア","AIスコア")) or 0.0
        active=[]; scores={
            "market_score":round(market_score,1),
            "initial_momentum":round(im_score,1),
            "steady_up":steady_score,
            "bottom_reversal":bottom_score,
            "quality":quality_score,
            "fundamental_early":0.0,
            "theme_discovery":0.0,
            "pre_earnings":0.0,
            "post_earnings":0.0,
        }
        reasons=[]
        if im_on: active.append("INITIAL_MOMENTUM"); reasons.append(str(_live_get(r,"INITIAL_MOMENTUM_REASON") or "初動モメンタム"))
        if steady_on: active.append("STEADY_UP"); reasons.extend(steady_reason[:4])
        if bottom_on: active.append("BOTTOM_REVERSAL"); reasons.extend(bottom_reason[:4])
        if not active: continue
        for s in active: counts[s]+=1

        # Existing ranking formula: intentionally unchanged in Contract v2-safe.
        strategy_scores=[scores[{"INITIAL_MOMENTUM":"initial_momentum","STEADY_UP":"steady_up","BOTTOM_REVERSAL":"bottom_reversal"}[s]] for s in active]
        base=max(strategy_scores) if strategy_scores else 0.0
        priority=base+min(10.0,max(0,len(active)-1)*3.0)
        if turn is not None and turn < LIVE_LOW_LIQUIDITY_OKU: priority-=LIVE_LOW_LIQUIDITY_PENALTY
        priority=round(max(0.0,min(100.0,priority)),1)

        tags=[]
        if current is not None and current <= LIVE_LOW_PRICE_MAX: tags.append("LOW_PRICE_SPECIAL")
        if rvol is not None and rvol >= 2.0: tags.append("HIGH_RVOL")
        ma25=_live_num(d.get("ma25")); ma75=_live_num(d.get("ma75"))
        if current is not None and ma25 is not None and current>ma25: tags.append("ABOVE_MA25")
        if current is not None and ma75 is not None and current>ma75: tags.append("ABOVE_MA75")
        if d.get("near_90d_high"): tags.append("NEAR_90D_HIGH")

        candidate={
            "code":str(code), "name":name, "market":market,
            "market_segment":_market_segment_from_market(market),
            "sources":active,
            "primary_source":None,
            "source_rank":{},
            "priority":priority,
            "feed_rank":None,
            "current_price":current, "previous_close":prev, "day_return_pct":dr,
            "day_open":_live_num(_live_get(r,"始値")), "day_high":_live_num(_live_get(r,"高値")), "day_low":_live_num(_live_get(r,"安値")),
            "volume":vol, "turnover_oku":turn, "rvol_turnover":rvol,
            "ma5":_live_num(d.get("ma5")), "ma25":ma25, "ma75":ma75,
            "support_today":_live_num(_live_get(r,"支持線今日")), "resistance_today":_live_num(_live_get(r,"抵抗線今日")),
            "scores":scores,
            "intraday":{
                "ret_5m":_live_num(intr.get("ret_5m")), "ret_10m":_live_num(intr.get("ret_10m")),
                "ret_20m":_live_num(intr.get("ret_20m")), "ret_30m":_live_num(intr.get("ret_30m")), "ret_60m":_live_num(intr.get("ret_60m")),
                "low_rebound_pct":_live_num(intr.get("low_rebound_pct")), "up_snapshot_ratio":_live_num(intr.get("up_snapshot_ratio")),
                "max_pullback_pct":_live_num(intr.get("max_pullback_pct")),
                "low_seen_at":intr.get("low_seen_at"),
                "minutes_since_low":_live_num(intr.get("minutes_since_low")),
                "no_new_low_minutes":_live_num(intr.get("no_new_low_minutes")),
            },
            "flags":{
                "above_ma25":bool(current is not None and ma25 is not None and current>ma25),
                "above_ma75":bool(current is not None and ma75 is not None and current>ma75),
                "near_90d_high":bool(d.get("near_90d_high")),
                "low_price_special":bool(current is not None and current<=LIVE_LOW_PRICE_MAX),
            },
            "tags":tags,
            "reason":" / ".join(dict.fromkeys(x for x in reasons if x))[:400],
            # WHY-TODAY-V1 metadata only. legacy candidate gate/priorityには不使用。
            "today_buy":bool(int(_live_num(_live_get(r,"TODAY_BUY")) or 0)==1),
            "today_score":_live_num(_live_get(r,"TODAY_SCORE")),
            "why_today":str(_live_get(r,"WHY_TODAY") or "")[:500],
            "today_waiting_for":str(_live_get(r,"TODAY_WAITING_FOR") or "")[:400],
            "today_blockers":str(_live_get(r,"TODAY_BLOCKERS") or "")[:400],
            "today_confirmation_needed":[x for x in str(_live_get(r,"TODAY_CONFIRMATION_NEEDED") or "").split(",") if x],
            "invalidation_price":_live_num(_live_get(r,"EXIT_INVALIDATION_PRICE")),
            "risk_pct":_live_num(_live_get(r,"EXIT_RISK_PCT")),
            "risk_100_shares_yen":_live_num(_live_get(r,"EXIT_RISK_100_SHARES_YEN")),
        }
        candidates.append(candidate)

    # Strategy-internal ranks are metadata only; they DO NOT alter candidate selection.
    _score_key={
        "INITIAL_MOMENTUM":"initial_momentum",
        "STEADY_UP":"steady_up",
        "BOTTOM_REVERSAL":"bottom_reversal",
    }
    _source_preference={"INITIAL_MOMENTUM":0,"STEADY_UP":1,"BOTTOM_REVERSAL":2}
    for _source,_sk in _score_key.items():
        _pool=[c for c in candidates if _source in c["sources"]]
        _pool.sort(
            key=lambda c:(
                float(c["scores"].get(_sk) or 0.0),
                float(c["scores"].get("market_score") or 0.0),
                float(c.get("turnover_oku") or 0.0),
                c["code"],
            ),
            reverse=True,
        )
        for _rank,c in enumerate(_pool,start=1):
            c["source_rank"][_source]=_rank

    for c in candidates:
        # Primary source is descriptive only; original ranking remains authoritative.
        c["primary_source"]=max(
            c["sources"],
            key=lambda s:(
                float(c["scores"].get(_score_key[s]) or 0.0),
                -_source_preference.get(s,99),
            ),
        )

    # Full pre-cap priority rank is metadata only. It lets LIVE explain cases where
    # a reserved strategy candidate would have fallen outside the legacy top 300.
    candidates.sort(key=_live_priority_sort_key, reverse=True)
    for _priority_rank,c in enumerate(candidates,start=1):
        c["priority_rank"]=_priority_rank

    # NEW: select LIVE50 from the full pre-300 pool. This does NOT alter the legacy 300.
    live_candidates=_live_select_execution_candidates(candidates)

    # Existing final cap: intentionally unchanged.
    candidates=candidates[:LIVE_CANDIDATE_MAX]

    for _feed_rank,c in enumerate(candidates,start=1):
        c["feed_rank"]=_feed_rank
        _sr=c["source_rank"].get(c["primary_source"])
        c["selection_reason"]=(
            f'既存priority順 / primary={c["primary_source"]}'
            + (f' / {c["primary_source"]}#{_sr}' if _sr is not None else '')
        )

    # Back-fill legacy feed_rank onto LIVE copies when the admitted name also belongs
    # to the legacy top 300. Reserved names outside the top 300 keep feed_rank=None.
    _feed_rank_by_code={str(c.get("code") or ""):c.get("feed_rank") for c in candidates}
    for c in live_candidates:
        c["feed_rank"]=_feed_rank_by_code.get(str(c.get("code") or ""))

    _live_source_counts={s:sum(1 for c in live_candidates if s in (c.get("sources") or [])) for s in ("INITIAL_MOMENTUM","STEADY_UP","BOTTOM_REVERSAL")}
    _live_bucket_counts={b:sum(1 for c in live_candidates if c.get("live_selection_bucket")==b) for b in ("INITIAL_RESERVED","STEADY_RESERVED","PRIORITY_FILL")}

    # REPRICING-DISCOVERY-V1: 既存候補/LIVE50を変えない別レーン。
    discovery_candidates, discovery_stats=_build_repricing_discovery_feed(rows, LIVE_CANDIDATE_MAX)
    # LIVE-ENTRY-FUNNEL-V3: 「何を買うか」と「いつ買えるか」を分離。
    # legacy live_candidatesは移行監査用に維持し、Kabuのリアルタイム登録正本は
    # broker_watch_candidates = TODAY_BUY + 安全gate済みTODAY_WATCH(READY/START) とする。
    today_buy_candidates=_build_today_buy_lane(rows, min(100, LIVE_CANDIDATE_MAX))
    today_watch_candidates=_build_today_watch_lane(rows, min(50, LIVE_CANDIDATE_MAX))
    broker_watch_candidates,broker_watch_stats=_build_broker_watch_lane(
        today_buy_candidates,today_watch_candidates,LIVE_EXECUTION_MAX
    )
    timing_near_candidates=_build_timing_near_lane(rows, min(120, LIVE_CANDIDATE_MAX))
    fundamental_watch_candidates=_build_fundamental_watch_lane(rows, min(300, LIVE_CANDIDATE_MAX))
    # LIVE-FOCUS-NOTIFY-V1: DAY専用の高密度候補。現行broker_watchはまだ置換しない。
    day_elite_focus_candidates=_build_day_elite_focus_lane(rows, LIVE_EXECUTION_MAX)

    return {
        "schema_version":LIVE_CANDIDATE_SCHEMA_VERSION,
        "candidate_contract_version":2,
        "producer":"auto_screening",
        "producer_script":Path(__file__).name,
        "generated_at":generated,
        "snapshot":snapshot,
        "source":"auto_screening",
        "valid_for_seconds":LIVE_CANDIDATE_VALID_SECONDS,
        "candidate_count":len(candidates),
        "candidates":candidates,
        "lane_contract_version":3,
        "broker_watch_version":1,
        "broker_watch_count":len(broker_watch_candidates),
        "broker_watch_candidates":broker_watch_candidates,
        "broker_watch_policy":{
            "authoritative_for_realtime_registration":True,
            "max_candidates":LIVE_EXECUTION_MAX,
            "source_lanes":["TODAY_BUY","TODAY_WATCH"],
            "priority_order":["TODAY_BUY","READY","START"],
            "context_only_lane":"TIMING_NEAR",
            "entry_permission":"LIVE_CONFIRMATION_REQUIRED",
            "direct_order_allowed":False,
            "dedupe":"code",
            "fill_policy":"do_not_force_fill",
        },
        "broker_watch_stats":broker_watch_stats,
        "day_elite_focus_version":2,
        "day_elite_focus_count":len(day_elite_focus_candidates),
        "day_elite_focus_candidates":day_elite_focus_candidates,
        "day_elite_focus_policy":{
            "purpose":"DAY_ELITE_INPUT_AFTER_LIVE_SIDE_MIGRATION",
            "match":"OR",
            "sources":["LEADER_MAIN","LEADER_CONTINUATION","DIFF_REAL_STRENGTH"],
            "leader_states":["🌈主役化/再主役化","🔥継続期待/再点火"],
            "diff_condition":"DIFF_REAL_STRENGTH=1",
            "max_candidates":LIVE_EXECUTION_MAX,
            "entry_permission":"LIVE_CONFIRMATION_REQUIRED",
            "direct_order_allowed":False,
            "authoritative_for_realtime_registration":False,
            "note":"LIVE側を改修するまで現行broker_watch_candidatesを正本として維持",
        },
        "today_buy_version":1,
        "today_buy_count":len(today_buy_candidates),
        "today_buy_candidates":today_buy_candidates,
        "today_watch_version":1,
        "today_watch_count":len(today_watch_candidates),
        "today_watch_candidates":today_watch_candidates,
        "timing_near_count":len(timing_near_candidates),
        "timing_near_candidates":timing_near_candidates,
        "fundamental_watch_count":len(fundamental_watch_candidates),
        "fundamental_watch_candidates":fundamental_watch_candidates,
        "discovery_version":1,
        "discovery_candidate_count":len(discovery_candidates),
        "discovery_total_count":int(discovery_stats.get("total_count", len(discovery_candidates))),
        "discovery_candidates":discovery_candidates,
        "discovery_stats":discovery_stats,
        "live_selection_version":1,
        "live_candidate_count":len(live_candidates),
        "live_candidates":live_candidates,
        "live_selection_policy":{
            "max_candidates":LIVE_EXECUTION_MAX,
            "initial_reserved":LIVE_EXECUTION_INITIAL_RESERVED,
            "initial_reserved_mode":"dynamic",
            "initial_near_cutoff_gap":2.0,
            "initial_exceptional_rank_max":min(8,LIVE_EXECUTION_INITIAL_RESERVED),
            "initial_exceptional_market_min":95.0,
            "initial_exceptional_cutoff_gap":10.0,
            "market_score_protect":95.0,
            "steady_reserved":LIVE_EXECUTION_STEADY_RESERVED,
            "bottom_reserved":0,
            "fill":"existing_priority",
            "dedupe":"code",
            "final_order":"existing_priority",
            "source_pool":"pre_300",
        },
        "stats":{
            "universe_count":len(codes), "snapshot_rows_written":snapshot_rows,
            "initial_momentum_count":counts["INITIAL_MOMENTUM"], "steady_up_count":counts["STEADY_UP"],
            "bottom_reversal_count":counts["BOTTOM_REVERSAL"],
            "exported_count":len(candidates), "max_candidates":LIVE_CANDIDATE_MAX,
            "live_exported_count":len(live_candidates),
            "live_initial_count":_live_source_counts["INITIAL_MOMENTUM"],
            "live_steady_count":_live_source_counts["STEADY_UP"],
            "live_bottom_count":_live_source_counts["BOTTOM_REVERSAL"],
            "live_initial_reserved_count":_live_bucket_counts["INITIAL_RESERVED"],
            "live_steady_reserved_count":_live_bucket_counts["STEADY_RESERVED"],
            "live_priority_fill_count":_live_bucket_counts["PRIORITY_FILL"],
            "day_elite_focus_count":len(day_elite_focus_candidates),
            "snapshot_db":str(LIVE_SNAPSHOT_DB), "captured_at":captured,
        },
    }



def export_live_candidate_feed(conn: sqlite3.Connection, rows_or_df, context: dict | None = None) -> bool:
    """LIVE AUTO向け正式Candidate Contractをatomic更新。失敗時は前回正常JSONを残す。"""
    try:
        if isinstance(rows_or_df,pd.DataFrame): rows=rows_or_df.to_dict(orient="records")
        else: rows=list(rows_or_df or [])
        payload=_live_candidate_payload(conn,rows,context=context)
        clean=dumps_json_clean(payload, ensure_ascii=False)
        # allow_nan=False相当のdumps_json_cleanを経たうえで、再parseしてschema/count整合も確認。
        check=json.loads(clean)
        if check.get("schema_version") != LIVE_CANDIDATE_SCHEMA_VERSION or not isinstance(check.get("candidates"),list):
            raise RuntimeError("live candidate payload schema validation failed")
        if int(check.get("candidate_count",-1)) != len(check["candidates"]):
            raise RuntimeError("live candidate candidate_count mismatch")
        if any(not isinstance(x.get("code"),str) for x in check["candidates"]):
            raise RuntimeError("live candidate code must be string")
        if int(check.get("candidate_contract_version", 1)) >= 2:
            _ranks=[x.get("feed_rank") for x in check["candidates"]]
            if _ranks != list(range(1, len(check["candidates"])+1)):
                raise RuntimeError("live candidate feed_rank must be contiguous and ordered")
            if str(check.get("producer") or "") != "auto_screening":
                raise RuntimeError("live candidate producer mismatch")
        if "discovery_candidates" in check:
            if not isinstance(check.get("discovery_candidates"),list):
                raise RuntimeError("discovery_candidates must be list")
            if int(check.get("discovery_candidate_count",-1)) != len(check["discovery_candidates"]):
                raise RuntimeError("discovery_candidate_count mismatch")
            _dr=[x.get("discovery_feed_rank") for x in check["discovery_candidates"]]
            if _dr != list(range(1,len(check["discovery_candidates"])+1)):
                raise RuntimeError("discovery_feed_rank must be contiguous and ordered")
        if "broker_watch_candidates" in check:
            if not isinstance(check.get("broker_watch_candidates"),list):
                raise RuntimeError("broker_watch_candidates must be list")
            if int(check.get("broker_watch_count",-1)) != len(check["broker_watch_candidates"]):
                raise RuntimeError("broker_watch_count mismatch")
            if len(check["broker_watch_candidates"]) > LIVE_EXECUTION_MAX:
                raise RuntimeError("broker_watch_candidates exceeds LIVE_EXECUTION_MAX")
            _br=[x.get("broker_watch_rank") for x in check["broker_watch_candidates"]]
            if _br != list(range(1,len(check["broker_watch_candidates"])+1)):
                raise RuntimeError("broker_watch_rank must be contiguous and ordered")
            _bc=[x.get("code") for x in check["broker_watch_candidates"]]
            if len(_bc) != len(set(_bc)):
                raise RuntimeError("broker_watch_candidates must be deduped by code")
            if any(bool(x.get("direct_order_allowed")) for x in check["broker_watch_candidates"]):
                raise RuntimeError("broker_watch_candidates must not allow direct order")
            if any(str(x.get("entry_permission") or "") != "LIVE_CONFIRMATION_REQUIRED" for x in check["broker_watch_candidates"]):
                raise RuntimeError("broker_watch_candidates entry_permission mismatch")
            if any(
                str(x.get("broker_source_lane") or "") == "TODAY_WATCH"
                and str(x.get("watch_state") or "") not in {"READY","START"}
                for x in check["broker_watch_candidates"]
            ):
                raise RuntimeError("broker TODAY_WATCH must be READY/START only")
        if "day_elite_focus_candidates" in check:
            if not isinstance(check.get("day_elite_focus_candidates"), list):
                raise RuntimeError("day_elite_focus_candidates must be list")
            if int(check.get("day_elite_focus_count", -1)) != len(check["day_elite_focus_candidates"]):
                raise RuntimeError("day_elite_focus_count mismatch")
            if len(check["day_elite_focus_candidates"]) > LIVE_EXECUTION_MAX:
                raise RuntimeError("day_elite_focus_candidates exceeds LIVE_EXECUTION_MAX")
            _fr=[x.get("focus_rank") for x in check["day_elite_focus_candidates"]]
            if _fr != list(range(1,len(check["day_elite_focus_candidates"])+1)):
                raise RuntimeError("day_elite_focus focus_rank must be contiguous and ordered")
            _fc=[x.get("code") for x in check["day_elite_focus_candidates"]]
            if len(_fc) != len(set(_fc)):
                raise RuntimeError("day_elite_focus_candidates must be deduped by code")
            if any(bool(x.get("direct_order_allowed")) for x in check["day_elite_focus_candidates"]):
                raise RuntimeError("day_elite_focus_candidates must not allow direct order")
            if any(str(x.get("entry_permission") or "") != "LIVE_CONFIRMATION_REQUIRED" for x in check["day_elite_focus_candidates"]):
                raise RuntimeError("day_elite_focus entry_permission mismatch")
            if any(not (x.get("focus_sources") or []) for x in check["day_elite_focus_candidates"]):
                raise RuntimeError("day_elite_focus candidate without focus source")
        if "live_candidates" in check:
            if not isinstance(check.get("live_candidates"),list):
                raise RuntimeError("live_candidates must be list")
            if int(check.get("live_candidate_count",-1)) != len(check["live_candidates"]):
                raise RuntimeError("live_candidate_count mismatch")
            _lr=[x.get("live_rank") for x in check["live_candidates"]]
            if _lr != list(range(1,len(check["live_candidates"])+1)):
                raise RuntimeError("live_rank must be contiguous and ordered")
            _codes=[x.get("code") for x in check["live_candidates"]]
            if len(_codes) != len(set(_codes)):
                raise RuntimeError("live_candidates must be deduped by code")
        _atomic_write_text_file(LIVE_CANDIDATE_FEED_PATH, clean)
        st=check.get("stats",{})
        print(
            "[live-feed] generated: "
            f"universe={st.get('universe_count',0)} candidates={check.get('candidate_count',0)} "
            f"INITIAL_MOMENTUM={st.get('initial_momentum_count',0)} "
            f"STEADY_UP={st.get('steady_up_count',0)} BOTTOM_REVERSAL={st.get('bottom_reversal_count',0)} "
            f"LIVE50={st.get('live_exported_count',0)} "
            f"LIVE_INITIAL={st.get('live_initial_count',0)} LIVE_STEADY={st.get('live_steady_count',0)} "
            f"LIVE_BOTTOM={st.get('live_bottom_count',0)} "
            f"BROKER_WATCH={check.get('broker_watch_count',0)} "
            f"(BUY={check.get('broker_watch_stats',{}).get('selected_today_buy',0)} "
            f"READY={check.get('broker_watch_stats',{}).get('selected_ready',0)} "
            f"START={check.get('broker_watch_stats',{}).get('selected_start',0)}) "
            f"DISCOVERY={check.get('discovery_candidate_count',0)}/{check.get('discovery_total_count', check.get('discovery_candidate_count',0))} "
            f"snapshot_rows_written={st.get('snapshot_rows_written',0)} path={LIVE_CANDIDATE_FEED_PATH}"
        )
        return True
    except Exception as e:
        # 旧正常feedを消さない。generated_atでLIVE側がstale判定できる。
        logging.error("[live-feed][ERROR] candidate feed generation failed; previous normal file preserved", exc_info=True)
        print(f"[live-feed][WARN] generation failed; previous file preserved: {e}")
        return False


def _open_db(path: str) -> sqlite3.Connection:
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(
        path,
        timeout=30.0,
        detect_types=sqlite3.PARSE_DECLTYPES | sqlite3.PARSE_COLNAMES,
        check_same_thread=False,   # 必要に応じて True へ
        isolation_level=None       # autocommit（必要なら変更）
    )
    # PRAGMA 初期化
    conn.execute("PRAGMA journal_mode=WAL;")
    conn.execute("PRAGMA synchronous=NORMAL;")
    conn.execute("PRAGMA temp_store=MEMORY;")
    conn.execute("PRAGMA foreign_keys=ON;")
    conn.execute("PRAGMA busy_timeout=60000;")
    conn.row_factory = sqlite3.Row

    return conn

def _get_db_conn() -> sqlite3.Connection:
    """必要になった時だけ開いて使い回す（再帰なし・スレッド安全）"""
    global _DB_SINGLETON
    with _DB_LOCK:
        if _DB_SINGLETON is not None:
            # コネクション健全性チェック
            try:
                _DB_SINGLETON.execute("SELECT 1;")
                return _DB_SINGLETON
            except Exception:
                try:
                    _DB_SINGLETON.close()
                except Exception:
                    pass
                _DB_SINGLETON = None
        # 新規オープン
        _DB_SINGLETON = _open_db(DB_PATH)
        return _DB_SINGLETON

def _close_db_conn_safely():
    """任意：終了処理などで明示クローズしたい場合のみ使用"""
    global _DB_SINGLETON
    with _DB_LOCK:
        if _DB_SINGLETON is not None:
            try:
                _DB_SINGLETON.close()
            finally:
                _DB_SINGLETON = None



# price_history読取は logical-code + distinct-market-date を基本規約とする。
# === Canonicalize code for DB keys (再発防止の要) ===
_TOPIX_ALIASES = {'^TOPIX', 'TOPIX', '998405.T', '^TOPX'}
# Yahoo JapanのTOPIX正規シンボルは 998405.T。DB内の論理コードは
# ^TOPX に統一するが、Yahooへ ^TOPX をそのまま送るとquoteが取れず、
# RS_5/RS_20が全銘柄NULLになる。問合せシンボルだけ明示変換する。
_YAHOO_INDEX_SYMBOLS = {
    '^TOPX': '998405.T',
    '^TOPIX': '998405.T',
    'TOPIX': '998405.T',
    '998405.T': '998405.T',
}

def canonical_code_for_db(code: str) -> str:
    """DB JOIN/UPDATE 用の証券コードを決定的に正規化する。

    P1-163: 7203.0 / 285a / 285A.T のような同一銘柄の別表記を
    7203 / 285A に統一し、TOPIX別名は ^TOPX に統一する。
    """
    if code is None:
        return ""
    s = str(code).strip()

    # DB key safety guard:
    # Reject accidental pandas Series/DataFrame string representations.
    # A valid security code must never contain line breaks or pandas repr markers.
    if (
        "\n" in s
        or "\r" in s
        or "dtype:" in s
        or "Name:" in s
    ):
        raise ValueError(
            "series-like security code rejected: "
            + repr(s[:160])
        )

    if not s:
        return ""
    u = s.upper()
    if u in {a.upper() for a in _TOPIX_ALIASES}:
        return '^TOPX'
    if u in {'NAN', 'NONE'}:
        return ""
    # P1-329: 東証だけでなく名証/札証/福証のYahoo suffixもDBキーから外す。
    for suf in ('.T', '.N', '.S', '.F', '-T', '-N', '-S', '-F', '.JP', '-JP'):
        if u.endswith(suf):
            u = u[:-len(suf)]
            break
    if re.fullmatch(r"[0-9]+\.0+", u):
        u = u.split('.', 1)[0]
    if u.isdigit():
        return u.zfill(4)
    return u

def code_query_variants(code: object) -> list[str]:
    """P1-256: canonical/legacy DB表記を同一銘柄として検索する候補列。"""
    c = canonical_code_for_db(code)
    if not c:
        return []
    vals = [c]
    if re.fullmatch(r"\d{4}", c):
        vals.append(c + ".0")
    elif re.fullmatch(r"\d{3}[A-Z]", c):
        vals.append(c.lower())

    # P1-333: P1-329以前のDBにYahoo市場suffix付きキーが残っていても検索できるようにする。
    # 証券コード自体は同一なので、T/N/S/Fのcross-list表記はlogical aliasとして扱う。
    if re.fullmatch(r"(?:\d{4}|\d{3}[A-Z])", c):
        vals.extend(c + suf for suf in (".T", ".N", ".S", ".F"))

    raw = "" if code is None else str(code).strip()
    if raw and raw not in vals:
        vals.append(raw)
    return list(dict.fromkeys(vals))

def expand_code_query_variants(codes) -> list[str]:
    """P1-276: 複数銘柄のcanonical/legacy検索候補を重複なく展開する。"""
    out = []
    for code in (codes or []):
        out.extend(code_query_variants(code))
    return list(dict.fromkeys(v for v in out if v))


def _latest_finance_notes_by_canonical(df: pd.DataFrame, key_col: str = "_key") -> pd.DataFrame:
    """P1-602: finance_notesのalias重複から実際に最終更新された正本行を選ぶ。

    finance_notesは現行writerではコードPRIMARY KEYのcurrent snapshotだが、legacy DBには
    7203 / 7203.0 等のalias行が共存し得る。ON CONFLICT UPDATEではrowidが変わらないため、
    rowid最大=最新更新とは限らない。updated_atを主、canonical表記・rowidをtie-breakにする。
    """
    if df is None or getattr(df, "empty", True):
        return df.copy() if hasattr(df, "copy") else pd.DataFrame()
    if "コード" not in df.columns:
        return df.copy()
    x = df.copy()
    # P1-607: key_col="コード" の呼出しではcanonical keyを書き戻す前にraw表記を保存する。
    # 先に上書きすると7203.0も7203になり、canonical表記tie-breakが全行1へ潰れる。
    _raw = x["コード"].astype(str).str.strip().str.upper()
    if globals().get("_v44_finance_stale_fast_enabled", lambda: False)():
        x[key_col] = _v24_unique_canonical_series(x["コード"])
    else:
        x[key_col] = x["コード"].map(canonical_code_for_db)
    x = x[x[key_col].astype(str).str.len() > 0].copy()
    _raw = _raw.loc[x.index]
    if x.empty:
        return x
    if "updated_at" in x.columns:
        # P1-650: legacy naive ISO と現行offset付きISOが混在しても比較可能なJST-naiveへ統一。
        if globals().get("_v44_finance_stale_fast_enabled", lambda: False)():
            x["_fn_updated_sort"] = _v44_unique_jst_naive_series(x["updated_at"])
        else:
            x["_fn_updated_sort"] = x["updated_at"].map(_p1_608_jst_naive_ts)
    else:
        x["_fn_updated_sort"] = pd.NaT
    x["_fn_canon_match"] = (_raw == x[key_col].astype(str).str.upper()).astype(int)
    if "_rowid" not in x.columns:
        x["_rowid"] = range(1, len(x) + 1)
    x = (x.sort_values([key_col, "_fn_updated_sort", "_fn_canon_match", "_rowid"],
                       kind="stable", na_position="first")
           .drop_duplicates(key_col, keep="last"))
    return x.drop(columns=["_fn_updated_sort", "_fn_canon_match"], errors="ignore")


def _p1_608_jst_naive_ts(value):
    """P1-608: DB内の発表/更新時刻をJST壁時計のnaive Timestampへ揃える。"""
    try:
        if value is None or (isinstance(value, float) and np.isnan(value)):
            return pd.NaT
        ts = pd.Timestamp(value)
        if pd.isna(ts):
            return pd.NaT
        if ts.tzinfo is not None:
            ts = ts.tz_convert("Asia/Tokyo").tz_localize(None)
        return ts
    except Exception:
        return pd.NaT




# === V44 FINANCE STALE TRANSFORM FAST ===
def _v44_finance_stale_fast_enabled() -> bool:
    return str(os.environ.get("KABU_SCREEN_V44_FAST", "1") or "1").strip().lower() not in {"0", "false", "off", "no"}

def _v44_unique_jst_naive_series(series: pd.Series) -> pd.Series:
    """V44: scalar P1-608 semanticsを保ったまま、同じraw timestampのparseを1回に縮約する。"""
    if series is None:
        return pd.Series(dtype="datetime64[ns]")
    s = pd.Series(series, copy=False)
    if s.empty:
        return pd.Series(pd.NaT, index=s.index, dtype="datetime64[ns]")
    # factorizeはNaN/None/NaTを -1 に集約。非欠損uniqueだけscalar helperを1回ずつ呼ぶ。
    codes, uniques = pd.factorize(s, sort=False)
    parsed = [_p1_608_jst_naive_ts(v) for v in uniques.tolist()]
    vals = np.empty(len(s), dtype="datetime64[ns]")
    vals[:] = np.datetime64("NaT")
    if parsed:
        parr = np.asarray(parsed, dtype="datetime64[ns]")
        mask = codes >= 0
        vals[mask] = parr[codes[mask]]
    return pd.Series(vals, index=s.index)

def _finance_codes_stale_after_latest_earnings_uncached(conn: sqlite3.Connection) -> set[str]:
    """P1-608: finance_notes更新後に新しい決算イベントが来た銘柄を返す。

    fetch_allは各runでearnings_eventsを更新する一方、株探ファンダ全件更新は日次1回。
    朝のfinance_notes更新後に昼/引け後の決算・業績予想イベントが追加された場合、
    旧score/進捗/forecastをcurrent入力として再利用しないための鮮度ゲート。
    """
    try:
        # V43: profile-only instrumentation. Freshness semantics are unchanged.
        _v43_seg_t0 = time.perf_counter()
        _tables = {r[0] for r in conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table'"
        ).fetchall()}
        if "earnings_events" not in _tables or "finance_notes" not in _tables:
            return set()

        _ecols = {r[1] for r in conn.execute("PRAGMA table_info(earnings_events)").fetchall()}
        _fcols = {r[1] for r in conn.execute("PRAGMA table_info(finance_notes)").fetchall()}
        if "コード" not in _ecols or not ({"発表日時", "提出時刻"} & _ecols) or "コード" not in _fcols:
            return set()

        # P1-612: 実績決算は「finance_notesを今更新した」だけでfreshとしない。
        # TDnet直後は株探financeページの反映が遅れ、旧四半期を再取得してupdated_atだけ
        # 新しくなることがある。タイトルも保持し、実績決算かどうかを後段で判定する。
        _title_expr = 'タイトル' if 'タイトル' in _ecols else "'' AS タイトル"
        # P1-621: 同じearnings_eventsの正式読込は COALESCE(発表日時,提出時刻) なのに、
        # freshness gateだけ提出時刻固定だと旧DB/旧producerの発表日時-only行を見逃す。
        # 空文字もNULL相当に扱い、発表日時を優先して無ければ提出時刻へfallbackする。
        if "発表日時" in _ecols and "提出時刻" in _ecols:
            _event_ts_expr = "COALESCE(NULLIF(TRIM(発表日時),''), NULLIF(TRIM(提出時刻),''))"
        elif "発表日時" in _ecols:
            _event_ts_expr = "NULLIF(TRIM(発表日時),'')"
        else:
            _event_ts_expr = "NULLIF(TRIM(提出時刻),'')"
        try:
            _perf_record_phase("backend-detail:finance_stale_schema", time.perf_counter() - _v43_seg_t0, "OK")
        except Exception:
            pass
        _v43_seg_t0 = time.perf_counter()
        _ev = pd.read_sql_query(
            f"SELECT rowid AS _rowid, コード, {_event_ts_expr} AS _event_time, {_title_expr} FROM earnings_events "
            f"WHERE {_event_ts_expr} IS NOT NULL", conn
        )
        try:
            _perf_record_phase("backend-detail:finance_stale_earnings_load", time.perf_counter() - _v43_seg_t0, "OK")
        except Exception:
            pass
        _v43_seg_t0 = time.perf_counter()
        if _ev.empty:
            return set()
        if _v44_finance_stale_fast_enabled():
            _ev["_key"] = _v24_unique_canonical_series(_ev["コード"])
            _ev["_event_ts"] = _v44_unique_jst_naive_series(_ev["_event_time"])
        else:
            _ev["_key"] = _ev["コード"].map(canonical_code_for_db)
            _ev["_event_ts"] = _ev["_event_time"].map(_p1_608_jst_naive_ts)
        _ev = _ev[
            _ev["_key"].astype(str).str.len().gt(0) & _ev["_event_ts"].notna()
        ].copy()
        if _ev.empty:
            return set()
        # P1-614: 「最新イベント」と「最新の実績決算イベント」は別々に保持する。
        # 同日、決算短信の直後に通期業績予想修正などが出ると、最新1件だけを見る方式では
        # 後者が前者を隠し、四半期実績のsemantic freshness gateを回避できる。
        # P1-615: 「決算」という部分一致だけでは「決算期変更」等まで実績決算扱いする。
        # semantic gateはTDnetの実績本体を強く示す「決算短信」に限定する。
        if _v44_finance_stale_fast_enabled():
            _ev["_is_actual_result"] = _ev["タイトル"].fillna("").astype(str).str.contains("決算短信", regex=False)
        else:
            _ev["_is_actual_result"] = _ev["タイトル"].map(
                lambda _x: "決算短信" in str(_x or "")
            )
        _ev_sorted = _ev.sort_values(["_key", "_event_ts", "_rowid"], kind="stable")
        _ev_latest = _ev_sorted.drop_duplicates("_key", keep="last")
        if _v44_finance_stale_fast_enabled():
            _event_map = dict(zip(_ev_latest["_key"].tolist(), _ev_latest["_event_ts"].tolist()))
        else:
            _event_map = {r["_key"]: r["_event_ts"] for _, r in _ev_latest.iterrows()}
        _ev_actual = _ev_sorted[_ev_sorted["_is_actual_result"]].drop_duplicates("_key", keep="last")
        if _v44_finance_stale_fast_enabled():
            _actual_event_map = dict(zip(_ev_actual["_key"].tolist(), _ev_actual["_event_ts"].tolist()))
        else:
            _actual_event_map = {r["_key"]: r["_event_ts"] for _, r in _ev_actual.iterrows()}

        try:
            _perf_record_phase("backend-detail:finance_stale_earnings_transform", time.perf_counter() - _v43_seg_t0, "OK")
        except Exception:
            pass
        _v43_seg_t0 = time.perf_counter()

        # current producer（株探ファンダv14+）が保存する実績四半期履歴。
        # テーブルが存在する環境だけsemantic freshness gateを有効化し、旧DB互換は維持する。
        _qh_available = False
        _actual_announce = {}
        if "quarterly_actual_history" in _tables:
            _qcols = {r[1] for r in conn.execute("PRAGMA table_info(quarterly_actual_history)").fetchall()}
            if {"コード", "announcement_date"}.issubset(_qcols):
                _qh_available = True
                # P1-629: P1-625の季節進捗本体と同じく、値/発表日の有無より先に
                # logical Qのauthoritative rowを確定する。旧aliasの誤った新しい発表日で
                # finance freshnessを「追いついた」と誤認しない。
                _qh_fk_expr = "fiscal_key" if "fiscal_key" in _qcols else "NULL AS fiscal_key"
                _qh_qn_expr = "quarter_no" if "quarter_no" in _qcols else "NULL AS quarter_no"
                _qh_up_expr = "updated_at" if "updated_at" in _qcols else "NULL AS updated_at"
                # V43: split quarterly DB load from pandas semantic transform.
                try:
                    _perf_record_phase("backend-detail:finance_stale_pre_quarterly", time.perf_counter() - _v43_seg_t0, "OK")
                except Exception:
                    pass
                _v43_seg_t0 = time.perf_counter()
                _qh = pd.read_sql_query(
                    f"SELECT rowid AS _rowid, コード, announcement_date, "
                    f"{_qh_fk_expr}, {_qh_qn_expr}, {_qh_up_expr} "
                    "FROM quarterly_actual_history", conn
                )
                try:
                    _perf_record_phase("backend-detail:finance_stale_quarterly_load", time.perf_counter() - _v43_seg_t0, "OK")
                except Exception:
                    pass
                _v43_seg_t0 = time.perf_counter()
                if not _qh.empty:
                    _qh["_raw_code"] = _qh["コード"].astype(str).str.strip()
                    if _v44_finance_stale_fast_enabled():
                        _qh["_key"] = _v24_unique_canonical_series(_qh["コード"])
                        _qh["_announce_ts"] = _v44_unique_jst_naive_series(_qh["announcement_date"])
                        # P1-651 semantics: scalar helperと同じJST-naive変換をunique値単位で実行。
                        _qh["_updated_ts"] = _v44_unique_jst_naive_series(_qh.get("updated_at"))
                    else:
                        _qh["_key"] = _qh["コード"].map(canonical_code_for_db)
                        _qh["_announce_ts"] = _qh["announcement_date"].map(_p1_608_jst_naive_ts)
                        # P1-651: P1-650のauthoritative時刻統一をfinance freshness gateにも適用。
                        # quarterly_actual_history.updated_atのaware/naive混在で正しいsnapshotをFATALにしない。
                        _qh["_updated_ts"] = _qh.get("updated_at").map(_p1_608_jst_naive_ts)
                    _qh["_canon_match"] = (
                        _qh["_raw_code"].str.upper() == _qh["_key"].astype(str).str.upper()
                    ).astype(int)
                    _qh["quarter_no"] = pd.to_numeric(_qh.get("quarter_no"), errors="coerce")
                    _qh["fiscal_key"] = _qh.get("fiscal_key").fillna("").astype(str).str.strip()
                    _qh = _qh[_qh["_key"].astype(str).str.len().gt(0)].copy()
                    if not _qh.empty:
                        _has_logical_q = (
                            _qh["fiscal_key"].ne("") & _qh["quarter_no"].notna()
                        )
                        _qh_q = _qh[_has_logical_q].copy()
                        _qh_other = _qh[~_has_logical_q].copy()
                        if not _qh_q.empty:
                            _qh_q = (
                                _qh_q.sort_values(
                                    ["_key", "fiscal_key", "quarter_no", "_updated_ts",
                                     "_canon_match", "_announce_ts", "_rowid"],
                                    kind="stable", na_position="first"
                                )
                                .drop_duplicates(["_key", "fiscal_key", "quarter_no"], keep="last")
                            )
                        # 旧schema等でQキーが無い行は従来互換として残すが、future発表日は下で除外。
                        _qh = pd.concat([_qh_q, _qh_other], ignore_index=True)
                        _today_fin_fresh = pd.Timestamp(date.fromisoformat(_today_jst()))
                        _qh = _qh[
                            _qh["_announce_ts"].notna()
                            & (_qh["_announce_ts"].dt.normalize() <= _today_fin_fresh)
                        ].copy()
                        if not _qh.empty:
                            _qh = (
                                _qh.sort_values(
                                    ["_key", "_announce_ts", "_updated_ts", "_canon_match", "_rowid"],
                                    kind="stable", na_position="first"
                                )
                                .drop_duplicates("_key", keep="last")
                            )
                            if _v44_finance_stale_fast_enabled():
                                _actual_announce = dict(zip(_qh["_key"].tolist(), _qh["_announce_ts"].tolist()))
                            else:
                                _actual_announce = {
                                    r["_key"]: r["_announce_ts"] for _, r in _qh.iterrows()
                                }

        try:
            _perf_record_phase("backend-detail:finance_stale_quarterly_transform", time.perf_counter() - _v43_seg_t0, "OK")
        except Exception:
            pass
        _v43_seg_t0 = time.perf_counter()
        _updated_expr = "updated_at" if "updated_at" in _fcols else "NULL AS updated_at"
        _fn = pd.read_sql_query(
            f"SELECT rowid AS _rowid, コード, {_updated_expr} FROM finance_notes", conn
        )
        try:
            _perf_record_phase("backend-detail:finance_stale_finance_load", time.perf_counter() - _v43_seg_t0, "OK")
        except Exception:
            pass
        _v43_seg_t0 = time.perf_counter()
        _fin_updated = {}
        if not _fn.empty:
            _fn = _latest_finance_notes_by_canonical(_fn, "_key")
            if _v44_finance_stale_fast_enabled():
                _fin_ts_series = _v44_unique_jst_naive_series(_fn["updated_at"])
                _fin_updated = dict(zip(_fn["_key"].tolist(), _fin_ts_series.tolist()))
            else:
                for _, _r in _fn.iterrows():
                    _fin_updated[_r["_key"]] = _p1_608_jst_naive_ts(_r.get("updated_at"))

        try:
            _perf_record_phase("backend-detail:finance_stale_finance_transform", time.perf_counter() - _v43_seg_t0, "OK")
        except Exception:
            pass
        _v43_seg_t0 = time.perf_counter()
        _stale = set()
        for _key, _event_ts in _event_map.items():
            _fin_ts = _fin_updated.get(_key, pd.NaT)
            if pd.isna(_fin_ts) or _event_ts > _fin_ts:
                _stale.add(_key)
                continue

            # P1-612/P1-614: 最新イベントが予想修正でも、それより前に同日/直近の実績決算が
            # あれば、その最新実績決算に対するquarterly history到達も独立して必須化する。
            if _qh_available and _key in _actual_event_map:
                _actual_event_ts = _actual_event_map[_key]
                _ann_ts = _actual_announce.get(_key, pd.NaT)
                if pd.isna(_ann_ts) or pd.Timestamp(_ann_ts).date() < pd.Timestamp(_actual_event_ts).date():
                    _stale.add(_key)
        try:
            _perf_record_phase("backend-detail:finance_stale_compare", time.perf_counter() - _v43_seg_t0, "OK")
        except Exception:
            pass
        return _stale
    except Exception as _e:
        # P1-613: 鮮度判定不能を「stale 0件」として続行すると、そのrunだけ旧財務を
        # currentとして再公開できる。必要テーブル不存在は上で互換分岐済みなので、
        # ここへ来るDB読込/parse障害はfail-closedで上位へ返す。
        print(f"[finance-fresh][ERROR] latest earnings freshness check failed: {_e}", flush=True)
        raise RuntimeError("finance freshness check failed; refusing to treat cached finance as current") from _e



_PERF_FINANCE_STALE_RUN_CACHE = {}

def _finance_codes_stale_after_latest_earnings(conn: sqlite3.Connection) -> set[str]:
    """PERF-OPT-V17: same-run freshness result cache; semantic calculation remains in uncached function."""
    _key = id(conn)
    if _key in _PERF_FINANCE_STALE_RUN_CACHE:
        return set(_PERF_FINANCE_STALE_RUN_CACHE[_key])
    _t0 = time.perf_counter()
    _res = set(_finance_codes_stale_after_latest_earnings_uncached(conn))
    _PERF_FINANCE_STALE_RUN_CACHE[_key] = set(_res)
    try:
        _perf_record_phase(
            "backend-detail:finance_stale_first_compute",
            time.perf_counter() - _t0, "OK"
        )
    except Exception:
        pass
    print(
        f"[finance-stale-cache] mode=compute codes={len(_res)} dt={time.perf_counter()-_t0:.2f}s",
        flush=True,
    )
    return set(_res)


def _dedupe_price_history_df(df: pd.DataFrame) -> pd.DataFrame:
    """P1-276: price_history の論理同一銘柄・同一日重複を決定的に1行へ畳む。

    過去DBに 7203 / 7203.0、285A / 285a が同日に共存していても、
    MA・RS・ATR・前日終値などで1日を2本として数えない。
    候補が複数なら OHLCV の非NULL数が多い行を優先し、同点ならcanonical表記、
    さらに同点ならrowidの大きい行を採用する。
    P1-454: legacy土日/祝日足も同時に除外する。
    """
    if df is None or getattr(df, 'empty', True):
        return df.copy() if hasattr(df, 'copy') else pd.DataFrame()
    if 'コード' not in df.columns or '日付' not in df.columns:
        return df.copy()
    x = df.copy()
    x['_code_key'] = (_v24_unique_canonical_series(x['コード']) if _v24_fast_enabled() else x['コード'].map(canonical_code_for_db))
    x['_date_key'] = pd.to_datetime(x['日付'], errors='coerce').dt.normalize()
    x = x[x['_code_key'].astype(str).str.len().gt(0) & x['_date_key'].notna()].copy()
    # P1-454: P1-158以前に残った土日/祝日足も論理履歴から除外する。
    # 単なるfuture cutoffだけでは、月曜朝に「金曜実足 + 土曜legacy足」の土曜が最新になり得る。
    if not x.empty:
        _extra_ph_closed = _load_extra_closed(EXTRA_CLOSED_PATH)
        _unique_ph_dates = pd.Series(x['_date_key'].dt.date.unique()).dropna().tolist()
        _valid_ph_dates = {
            _d for _d in _unique_ph_dates
            if not is_jp_market_holiday(_d, _extra_ph_closed)
        }
        x = x[x['_date_key'].dt.date.isin(_valid_ph_dates)].copy()
    if x.empty:
        return x.drop(columns=[c for c in ('_code_key','_date_key') if c in x.columns], errors='ignore')
    rawu = x['コード'].astype(str).str.strip().str.upper()
    x['_canon_match'] = rawu.eq(x['_code_key'].astype(str).str.upper()).astype(int)
    qcols = [c for c in ('始値','高値','安値','終値','出来高') if c in x.columns]
    x['_quality'] = x[qcols].notna().sum(axis=1) if qcols else 0
    if '_rowid' in x.columns:
        x['_rid_sort'] = pd.to_numeric(x['_rowid'], errors='coerce').fillna(-1)
    else:
        x['_rid_sort'] = range(len(x))
    x = x.sort_values(
        ['_code_key','_date_key','_quality','_canon_match','_rid_sort'],
        ascending=[True,True,True,True,True],
        kind='mergesort'
    ).drop_duplicates(subset=['_code_key','_date_key'], keep='last')
    x['コード'] = x['_code_key']
    # 日付は元の表示形式を保ちつつ、並びは論理日付で決定する。
    x = x.sort_values(['_code_key','_date_key'], kind='mergesort')
    return x.drop(columns=['_code_key','_date_key','_canon_match','_quality','_rid_sort'], errors='ignore').reset_index(drop=True)


def _delete_legacy_price_alias_rows(conn: sqlite3.Connection, code, date_value) -> None:
    """P1-290: canonical行を書き込む直前に同日legacy aliasだけ削除する。"""
    c = canonical_code_for_db(code)
    if not c:
        return
    legacy = [v for v in code_query_variants(code) if str(v) != str(c)]
    if not legacy:
        return
    ph = ','.join('?' * len(legacy))
    conn.execute(
        f"DELETE FROM price_history WHERE CAST(コード AS TEXT) IN ({ph}) AND 日付=?",
        tuple(legacy) + (str(date_value)[:10],)
    )


def _filter_price_history_write_rows(rows, *, date_index: int = 1):
    """P1-462: price_history書込み直前にJPX営業日だけを許可する。

    過去バグ由来の休日/未来足は読み取り側でも除外しているが、今後DBへ
    新規混入させないため全writer共通の入口でも検証する。
    """
    rows = list(rows or [])
    if not rows:
        return []
    cutoff = _expected_jpx_asof_date()
    extra = _load_extra_closed(EXTRA_CLOSED_PATH)
    valid_cache = {}
    out = []
    dropped = 0
    for row in rows:
        try:
            ds = str(row[date_index])[:10]
            d = date.fromisoformat(ds)
        except Exception:
            dropped += 1
            continue
        ok = valid_cache.get(d)
        if ok is None:
            ok = (d <= cutoff) and (not is_jp_market_holiday(d, extra))
            valid_cache[d] = ok
        if ok:
            out.append(row)
        else:
            dropped += 1
    if dropped:
        print(f"[price_history][GUARD] rejected non-JPX/future rows={dropped}")
    return out


def _atomic_write_price_history_rows(conn: sqlite3.Connection, rows, *, close_only: bool = False, intraday_merge: bool = False) -> int:
    """P1-352〜355: alias削除と履歴upsertを同一SAVEPOINTで行う。
    P1-528: intraday_merge=Trueでは同日高安/累積出来高を後続の部分応答で巻き戻さない。
    """
    rows = _filter_price_history_write_rows(rows, date_index=1)
    if not rows:
        return 0
    sp = f"ph_rows_{time.time_ns()}"
    cur = conn.cursor()
    try:
        conn.execute(f"SAVEPOINT {sp}")
        if close_only:
            norm_rows = []
            for code, d, close in rows:
                code = canonical_code_for_db(code)
                if not code:
                    continue
                _delete_legacy_price_alias_rows(conn, code, d)
                norm_rows.append((code, str(d)[:10], close))
            cur.executemany(
                """INSERT INTO price_history(コード,日付,終値) VALUES(?,?,?)
                   ON CONFLICT(コード,日付) DO UPDATE SET
                     終値=COALESCE(excluded.終値, 終値)""",
                norm_rows
            )
        else:
            norm_rows = []
            for code, d, o, h, l, c, v in rows:
                code = canonical_code_for_db(code)
                if not code:
                    continue
                _delete_legacy_price_alias_rows(conn, code, d)
                norm_rows.append((code, str(d)[:10], o, h, l, c, v))
            if intraday_merge:
                cur.executemany(
                    """INSERT INTO price_history(コード,日付,始値,高値,安値,終値,出来高)
                       VALUES(?,?,?,?,?,?,?)
                       ON CONFLICT(コード,日付) DO UPDATE SET
                         始値=COALESCE(始値, excluded.始値),
                         高値=CASE
                           WHEN 高値 IS NULL THEN excluded.高値
                           WHEN excluded.高値 IS NULL THEN 高値
                           ELSE MAX(高値, excluded.高値) END,
                         安値=CASE
                           WHEN 安値 IS NULL THEN excluded.安値
                           WHEN excluded.安値 IS NULL THEN 安値
                           ELSE MIN(安値, excluded.安値) END,
                         終値=COALESCE(excluded.終値, 終値),
                         出来高=CASE
                           WHEN 出来高 IS NULL THEN excluded.出来高
                           WHEN excluded.出来高 IS NULL THEN 出来高
                           ELSE MAX(出来高, excluded.出来高) END""",
                    norm_rows
                )
            else:
                cur.executemany(
                    """INSERT INTO price_history(コード,日付,始値,高値,安値,終値,出来高)
                       VALUES(?,?,?,?,?,?,?)
                       ON CONFLICT(コード,日付) DO UPDATE SET
                         始値=COALESCE(excluded.始値, 始値),
                         高値=COALESCE(excluded.高値, 高値),
                         安値=COALESCE(excluded.安値, 安値),
                         終値=COALESCE(excluded.終値, 終値),
                         出来高=COALESCE(excluded.出来高, 出来高)""",
                    norm_rows
                )
        conn.execute(f"RELEASE SAVEPOINT {sp}")
        return len(norm_rows)
    except Exception:
        try:
            conn.execute(f"ROLLBACK TO SAVEPOINT {sp}")
            conn.execute(f"RELEASE SAVEPOINT {sp}")
        except Exception:
            pass
        raise
    finally:
        cur.close()


def _market_for_code_variants(conn: sqlite3.Connection, code) -> str | None:
    """P1-486: legacy aliasを含むscreenerから市場を決定的に選ぶ。"""
    if conn is None:
        return None
    variants = code_query_variants(code)
    if not variants:
        return None
    ph = ",".join("?" * len(variants))
    rows = conn.execute(
        f"SELECT CAST(コード AS TEXT), 市場 FROM screener WHERE CAST(コード AS TEXT) IN ({ph})",
        tuple(variants),
    ).fetchall()
    if not rows:
        return None
    by_code = {}
    for raw_code, market in rows:
        key = str(raw_code)
        # 同じraw keyが複数残っても、空市場より非空市場を優先。
        if key not in by_code or (not by_code[key] and market):
            by_code[key] = market
    for v in variants:
        market = by_code.get(str(v))
        if market is not None and str(market).strip():
            return market
    return None


def _yfinance_download_repaired(*args, **kwargs):
    """P2-14/P2-55: repair=Trueを既定化。未導入/旧版を明示的に扱う。"""
    if yfinance is None:
        raise RuntimeError("yfinance is required for Yahoo price-history fallback; install yfinance before this phase")
    if "repair" not in kwargs:
        kwargs["repair"] = True
    try:
        return yfinance.download(*args, **kwargs)
    except TypeError as e:
        # 古いyfinanceだけrepair引数が未対応。別のTypeErrorまで握り潰さない。
        if "repair" not in str(e).lower():
            raise
        legacy_kwargs = dict(kwargs)
        legacy_kwargs.pop("repair", None)
        return yfinance.download(*args, **legacy_kwargs)


def resolve_yahoo_symbol(code: str,
                         conn: Optional[sqlite3.Connection] = None,
                         try_online: bool = False) -> str:
    """
    screenerの 'コード' を Yahoo Finance 問い合わせ用シンボルに解決する。

    優先順位:
      1) DB上書きテーブル yahoo_symbol_override に一致があればそれを最優先で採用
      2) 規則で解決
         - '^'で始まる指数 or 既に'.T'付き   → そのまま
         - 4桁の純数字（例: 7203）          → 'XXXX.T'
         - 3桁数字+英字/4桁英数字ミックス   → 候補 ['CODE.T','CODE'] を順に採用
           （try_online=Trueならyfinanceで実在チェック、Falseなら'.T'優先）
         - それ以外                           → そのまま

    注意:
      - price_history へ保存する「コード」は問い合わせシンボルではなく
        *元の code（screenerのコード文字列）* を使ってください（JOINのキー保持）。
    """
    raw = "" if code is None else str(code).strip()
    if not raw:
        return raw
    RAWU = raw.upper()

    # 指数・Yahoo明示サフィックスは問い合わせシンボルなので破壊しない。
    if RAWU in _YAHOO_INDEX_SYMBOLS:
        return _YAHOO_INDEX_SYMBOLS[RAWU]
    if RAWU.startswith('^') or re.search(r"\.(?:T|N|S|F)$", RAWU):
        return RAWU

    # P1-164: bare code はDB共通規則へ。7203.0→7203、285a→285A。
    s = canonical_code_for_db(raw)
    if not s:
        return s
    S = s.upper()

    # 1) 明示オーバーライド（最優先）
    if conn is not None:
        _ov = _read_yahoo_override(conn, s)
        # P1-506: NONE/HISTORY_NONEは状態フラグでありYahoo symbolではない。
        # full symbol overrideだけをそのまま採用し、sentinelは通常の市場解決へフォールスルーする。
        if _ov and str(_ov).strip().upper() not in {"NONE", "HISTORY_NONE"}:
            return str(_ov).strip().upper()
            
    # 2) 規則解決
    # 2-2) 4桁の純数字
    # 2-2) 4桁の純数字
    if len(S) == 4 and S.isdigit():
        # screener から市場情報を拾う（あれば）
        market = None
        if conn is not None:
            try:
                # P1-486: alias複数行が残っていても無順序LIMIT 1で市場を選ばない。
                market = _market_for_code_variants(conn, s)
            except Exception:
                market = None

        # 市場＋override を使ってサフィックス決定
        # （他の処理と同じく _resolve_yahoo_suffix / _market_to_yahoo_suffix を使う）
        suffix = ".T"
        try:
            # _resolve_yahoo_suffix は内部で override テーブルも見てくれる
            suffix = _resolve_yahoo_suffix(s, market)
        except Exception:
            try:
                suffix = _market_to_yahoo_suffix(market)
            except Exception:
                suffix = ".T"

        symbol_default = s + suffix   # 例: 1449 + ".S" → "1449.S"

        if try_online:
            try:
                # 優先: 市場ベースの symbol_default → フォールバック: ".T" / 生
                for cand in (symbol_default, s + ".T", s):
                    _df = _yfinance_download_repaired(
                        cand,
                        period="5d",
                        interval="1d",
                        progress=False,
                        threads=False,
                    )
                    if _df is not None and not _df.empty:
                        return cand
            except Exception:
                pass

        # オフライン or 取れなかった場合は市場ベースのシンボルを返す
        return symbol_default


    # 2-3) 3桁数字+英字 or 4桁英数字ミックス
    pat_3d1a    = re.compile(r"^\d{3}[A-Z]$")   # 例: 130A
    pat_4_alnum = re.compile(r"^[A-Z0-9]{4}$")  # 例: 1A3B, A130, 13AB など

    if pat_3d1a.match(S) or (len(S) == 4 and pat_4_alnum.match(S) and not S.isdigit()):
        # P1-331: 英数字コードも4桁数字と同じく市場列からYahoo suffixを解決する。
        # 旧版は285A等だけ常に.T固定で、名証/札証/福証の英数字銘柄を誤照会していた。
        market = None
        if conn is not None:
            try:
                market = _market_for_code_variants(conn, s)
            except Exception:
                market = None

        try:
            suffix = _resolve_yahoo_suffix(s, market)
        except Exception:
            try:
                suffix = _market_to_yahoo_suffix(market)
            except Exception:
                suffix = ".T"
        symbol_default = S + suffix

        if try_online:
            try:
                candidates = [symbol_default]
                if symbol_default != S + ".T":
                    candidates.append(S + ".T")
                candidates.append(S)
                for cand in candidates:
                    df = _yfinance_download_repaired(cand, period="5d", interval="1d", progress=False, threads=False)
                    if df is not None and not df.empty:
                        return cand
            except Exception:
                pass
        return symbol_default

    # 2-4) それ以外 → canonical form
    return S

def resolve_yahoo_symbols_bulk(codes, conn: Optional[sqlite3.Connection]) -> list[str]:
    """P2-25: 複数銘柄のYahoo symbolをDB一括読込で解決する。

    scalar resolve_yahoo_symbol() と同じ優先順位を保ちつつ、main override / 市場 /
    legacy suffix overrideを銘柄ごとにSELECTしない。try_online相当のprobeは行わない。
    """
    raws = ["" if c is None else str(c).strip() for c in (codes or [])]
    if not raws:
        return []
    if conn is None:
        return [resolve_yahoo_symbol(c, None, False) for c in raws]

    canonical = []
    for raw in raws:
        u = raw.upper()
        if u in {'^TOPIX', 'TOPIX', '998405.T', '^TOPX'}:
            canonical.append('^TOPX')
        elif u.startswith('^') or re.search(r"\.(?:T|N|S|F)$", u):
            canonical.append(u)
        else:
            canonical.append(canonical_code_for_db(raw))

    lookup_codes = list(dict.fromkeys(
        c for raw, c in zip(raws, canonical)
        if c and not str(c).startswith('^') and not re.search(r"\.(?:T|N|S|F)$", raw.upper())
    ))
    all_variants = expand_code_query_variants(lookup_codes)

    # main yahoo_symbol_override
    _ensure_override_table(conn)
    ov_by_raw = {}
    market_by_raw = {}
    for _i in range(0, len(all_variants), 500):
        _part = all_variants[_i:_i + 500]
        if not _part:
            continue
        _ph = ",".join("?" * len(_part))
        for _rc, _sym in conn.execute(
            f"SELECT CAST(コード AS TEXT), 問い合わせシンボル FROM yahoo_symbol_override "
            f"WHERE CAST(コード AS TEXT) IN ({_ph})", tuple(_part)
        ).fetchall():
            ov_by_raw[str(_rc)] = _sym
        for _rc, _mkt in conn.execute(
            f"SELECT CAST(コード AS TEXT), 市場 FROM screener "
            f"WHERE CAST(コード AS TEXT) IN ({_ph})", tuple(_part)
        ).fetchall():
            _key = str(_rc)
            if _key not in market_by_raw or (not market_by_raw[_key] and _mkt):
                market_by_raw[_key] = _mkt

    # legacy suffix tables: P2-24/P2-59 schema-aware + alias-aware探索。
    legacy_suffix = {}  # logical code -> normalized suffix
    table_candidates = [
        "symbol_overrides", "overrides_symbol", "overrides", "yahoo_overrides",
        "symbol_meta", "symbols_override",
    ]
    code_cols = ["code", "symbol", "ticker", "stock_code", "銘柄コード"]
    suffix_cols = ["yahoo_suffix", "yahoo_market_suffix", "yahoo_market", "yahoo_sfx"]
    try:
        existing_tables = {
            str(r[0]) for r in conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall() if r and r[0]
        }
    except Exception as _e:
        # P2-38: schema読込失敗を「legacy override table無し」と誤認しない。
        raise RuntimeError(f"Yahoo legacy-override schema lookup failed: {_e}") from _e
    legacy_targets = [c for c in lookup_codes if re.fullmatch(r"(?:\d{4}|\d{3}[A-Z])", c or "")]
    for t in table_candidates:
        if t not in existing_tables:
            continue
        try:
            cols = {str(r[1]) for r in conn.execute(f'PRAGMA table_info("{t}")').fetchall()}
        except Exception as _e:
            raise RuntimeError(f"Yahoo legacy-override schema read failed for {t}: {_e}") from _e
        actual_code_cols = [c for c in code_cols if c in cols]
        actual_suffix_cols = [c for c in suffix_cols if c in cols]
        for c_code in actual_code_cols:
            for c_sfx in actual_suffix_cols:
                unresolved = [c for c in legacy_targets if c not in legacy_suffix]
                if not unresolved:
                    break
                # P2-59: logical codeごとにcanonical→legacy alias順で選ぶ。
                _vars_by_logical = {c: code_query_variants(c) for c in unresolved}
                _all_legacy_vars = list(dict.fromkeys(
                    v for c in unresolved for v in _vars_by_logical[c] if v
                ))
                _rows_by_raw = {}
                for _i in range(0, len(_all_legacy_vars), 500):
                    _part = _all_legacy_vars[_i:_i + 500]
                    if not _part:
                        continue
                    _ph = ",".join("?" * len(_part))
                    try:
                        _rows = conn.execute(
                            f'SELECT CAST("{c_code}" AS TEXT), "{c_sfx}" FROM "{t}" '
                            f'WHERE CAST("{c_code}" AS TEXT) IN ({_ph})', tuple(_part)
                        ).fetchall()
                    except Exception as _e:
                        # P2-73: 実在schemaへのSELECT失敗は「override無し」ではない。
                        # fallback symbolで別市場を照会するより、このbatchを明示失敗させる。
                        raise RuntimeError(
                            f"Yahoo legacy-override read failed: table={t} code_col={c_code} suffix_col={c_sfx}: {_e}"
                        ) from _e
                    for _rc, _sfx in _rows:
                        _rows_by_raw[str(_rc)] = _sfx
                for _logical in unresolved:
                    for _v in _vars_by_logical[_logical]:
                        if str(_v) not in _rows_by_raw:
                            continue
                        _norm = _normalize_yahoo_suffix_token(_rows_by_raw[str(_v)])
                        if _norm:
                            legacy_suffix[_logical] = _norm
                            break

    out = []
    for raw, c in zip(raws, canonical):
        if not raw:
            out.append(raw)
            continue
        u = raw.upper()
        if u in _YAHOO_INDEX_SYMBOLS:
            out.append(_YAHOO_INDEX_SYMBOLS[u])
            continue
        if u.startswith('^') or re.search(r"\.(?:T|N|S|F)$", u):
            out.append(u)
            continue
        if not c:
            out.append(c)
            continue
        variants = code_query_variants(c)
        ov = None
        market = None
        for v in variants:
            if ov is None and str(v) in ov_by_raw:
                ov = ov_by_raw[str(v)]
            if market is None:
                m = market_by_raw.get(str(v))
                if m is not None and str(m).strip():
                    market = m
            if ov is not None and market is not None:
                break
        if ov and str(ov).strip().upper() not in {"NONE", "HISTORY_NONE"}:
            out.append(str(ov).strip().upper())
            continue
        C = str(c).upper()
        if (len(C) == 4 and C.isdigit()) or re.fullmatch(r"\d{3}[A-Z]", C) or (
            len(C) == 4 and re.fullmatch(r"[A-Z0-9]{4}", C) and not C.isdigit()
        ):
            suffix = legacy_suffix.get(C) or _market_to_yahoo_suffix(market)
            out.append(C + suffix)
        else:
            out.append(C)

    # P2-28: 異なるlogical codeが同じYahoo symbolへ解決されたら、bulk応答を別銘柄へ
    # 誤配布し得る。alias同一銘柄は許可し、別銘柄collisionだけfail-fastする。
    _owners = {}
    _symbol_by_code = {}
    for _raw, _resolved in zip(raws, out):
        _ck = canonical_code_for_db(_raw)
        _sym = str(_resolved or "").strip().upper()
        if not _ck or not _sym:
            continue
        _prev = _owners.get(_sym)
        if _prev is not None and _prev != _ck:
            raise RuntimeError(
                f"Yahoo symbol collision: {_sym} resolved for both {_prev} and {_ck}"
            )
        _prev_sym = _symbol_by_code.get(_ck)
        if _prev_sym is not None and _prev_sym != _sym:
            # P2-58: 逆方向も1対1。7203.T/7203.N等が同じlogical codeへ混在すると、
            # 後段で同じDB行へ別市場データを二重反映し得るためfail-fastする。
            raise RuntimeError(
                f"Yahoo code collision: {_ck} resolved to both {_prev_sym} and {_sym}"
            )
        _owners[_sym] = _ck
        _symbol_by_code[_ck] = _sym
    return out


def _ensure_latest_prices_code_col(conn):
    cur = conn.cursor()
    _sp = "p2_64_latest_prices_code_col"
    try:
        cur.execute(f"SAVEPOINT {_sp}")
        cols = [r[1] for r in cur.execute("PRAGMA table_info(latest_prices)")]
        if "コード" not in cols:
            cur.execute("ALTER TABLE latest_prices ADD COLUMN コード TEXT")
        cols = [r[1] for r in cur.execute("PRAGMA table_info(latest_prices)")]
        if "code" in cols:
            cur.execute("UPDATE latest_prices SET コード = CAST(code AS TEXT) WHERE コード IS NULL OR コード = ''")
        cur.execute(f"RELEASE SAVEPOINT {_sp}")
    except Exception as e:
        try:
            cur.execute(f"ROLLBACK TO SAVEPOINT {_sp}")
            cur.execute(f"RELEASE SAVEPOINT {_sp}")
        except Exception:
            pass
        print("[ERROR] _ensure_latest_prices_code_col failed:", e)
        raise RuntimeError("latest_prices code-column ensure failed") from e
    finally:
        cur.close()
            
def _ensure_latest_prices_index_rows(conn):
    """screenerの論理銘柄でlatest_prices未登録行を原子的に補完する。"""
    cur = conn.cursor()
    try:
        # P1-429/P1-580: placeholderもrun modeのsnapshot日。
        # PREOPENに当日の日付だけ先行させず、前営業日の確定snapshotへ合わせる。
        today_jst = _expected_snapshot_date_for_run(_auto_run_mode()).isoformat()
        _have = {
            canonical_code_for_db(r[0])
            for r in cur.execute("SELECT コード FROM latest_prices").fetchall()
            if canonical_code_for_db(r[0])
        }
        _to_insert = []
        for _raw_code, _upd in cur.execute("SELECT コード, 更新日 FROM screener").fetchall():
            _key = canonical_code_for_db(_raw_code)
            if not _key or _key in _have:
                continue
            _to_insert.append((_raw_code, _upd or today_jst))
            _have.add(_key)
        if not _to_insert:
            return

        # P1-425: autocommit接続で補完途中だけ入るのを防ぐ。
        _sp = f"sp_latest_index_rows_{time.time_ns()}"
        conn.execute(f"SAVEPOINT {_sp}")
        try:
            cur.executemany("INSERT INTO latest_prices(コード, 日付) VALUES(?,?)", _to_insert)
            conn.execute(f"RELEASE SAVEPOINT {_sp}")
        except Exception:
            try:
                conn.execute(f"ROLLBACK TO SAVEPOINT {_sp}")
                conn.execute(f"RELEASE SAVEPOINT {_sp}")
            except Exception:
                pass
            raise
    except Exception as e:
        print("[ERROR] _ensure_latest_prices_index_rows failed:", e)
        raise RuntimeError("latest_prices row ensure failed") from e
    finally:
        cur.close()

def setup_database_indexes(conn: sqlite3.Connection) -> None:
    """テーブル構築後、または初期化フェーズで明示的に呼び出すインデックス作成関数。

    PERF-OPT-V2: price_historyの主要な既存SQLは date(日付) と
    CAST(コード AS TEXT) を使うため、その式と完全一致するexpression indexを張る。
    初回だけindex buildコストが掛かるが、2回目以降はIF NOT EXISTSで即時。
    """
    _defs = [
        (
            "idx_signals_code_date",
            "CREATE INDEX IF NOT EXISTS idx_signals_code_date ON signals_log(コード, 日時);",
        ),
        (
            "idx_price_history_perf_date_expr",
            "CREATE INDEX IF NOT EXISTS idx_price_history_perf_date_expr ON price_history(date(日付));",
        ),
        (
            "idx_price_history_perf_code_text_date",
            "CREATE INDEX IF NOT EXISTS idx_price_history_perf_code_text_date "
            "ON price_history(CAST(コード AS TEXT), 日付);",
        ),
    ]
    for _name, _sql in _defs:
        _t0 = time.perf_counter()
        try:
            conn.execute(_sql)
            _dt = time.perf_counter() - _t0
            if _dt >= 0.05:
                print(f"[DB Setup][index] {_name}: {_dt:.2f}s", flush=True)
        except sqlite3.OperationalError as e:
            print(f"[DB Setup] インデックス作成をスキップしました: {_name}: {e}")
    # startup schema phaseなのでここで確定し、後続の長いread transactionへ持ち越さない。
    conn.commit()

def ensure_runlog_schema(conn):
    """日次実行ログテーブルの作成と、システム全体のインデックス最適化を担う"""
    conn.execute("""
    CREATE TABLE IF NOT EXISTS run_log (
      phase       TEXT NOT NULL,
      run_date    TEXT NOT NULL,   -- 'YYYY-MM-DD' JST
      status      TEXT,            -- 'ok' | 'error' | 'running'
      started_at  TEXT,
      finished_at TEXT,
      info_json   TEXT,
      build_token TEXT,
      PRIMARY KEY (phase, run_date)
    );
    """)
    # P1-489: 旧DBのrun_logにもbuild識別子列を後方互換で追加する。
    try:
        _runlog_cols = {str(r[1]) for r in conn.execute("PRAGMA table_info(run_log)").fetchall()}
        if "build_token" not in _runlog_cols:
            conn.execute("ALTER TABLE run_log ADD COLUMN build_token TEXT")
    except Exception as _e:
        raise RuntimeError(f"run_log build_token schema migration failed: {_e}") from _e
    conn.commit()
    # テーブル作成後に安全にインデックスを構築
    setup_database_indexes(conn)

try:
    __JST = ZoneInfo("Asia/Tokyo")
except Exception:
    __JST = None

def _now_jst():
    # P1-121: 時刻ゲートもJST固定。ZoneInfoが使えなくてもUTC+9へフォールバックする。
    return datetime.now(__JST) if __JST else datetime.now(timezone(timedelta(hours=9)))

def _today_jst():
    return _now_jst().strftime("%Y-%m-%d")

__DAILY_BUILD_TOKEN = None

def _daily_build_token() -> str:
    """P1-488: 同日中のスクリプト差替えを日次markerが隠さないためのbuild識別子。"""
    global __DAILY_BUILD_TOKEN
    if __DAILY_BUILD_TOKEN:
        return __DAILY_BUILD_TOKEN
    try:
        import hashlib
        with open(os.path.abspath(__file__), "rb") as _f:
            __DAILY_BUILD_TOKEN = hashlib.sha256(_f.read()).hexdigest()[:16]
    except Exception:
        try:
            _st = os.stat(os.path.abspath(__file__))
            __DAILY_BUILD_TOKEN = f"{int(_st.st_size):x}-{int(getattr(_st, 'st_mtime_ns', int(_st.st_mtime*1e9))):x}"
        except Exception:
            # buildを識別できない時に古いmarkerを信用するより、毎回再実行側へ倒す。
            __DAILY_BUILD_TOKEN = f"unknown-{os.getpid()}"
    return __DAILY_BUILD_TOKEN

# P1-499: build tokenは最初のdaily marker参照時ではなく、module読込時点で固定する。
# 実行中に.py自体が差し替えられても「旧コード実行中なのに新buildのmarker」を残さない。
__DAILY_BUILD_TOKEN = _daily_build_token()

def _daily_marker_payload() -> str:
    return f"{_today_jst()}|{_daily_build_token()}"




def _daily_marker_matches_today(name: str) -> bool:
    """日次markerがJST当日成功済みかを副作用なく確認する。"""
    marker_path = os.path.join(OUTPUT_DIR, f"last_{name}.txt")
    try:
        if not os.path.exists(marker_path):
            return False
        with open(marker_path, "r", encoding="utf-8") as f:
            # P1-488: 旧date-only markerや別buildのmarkerは成功済みとみなさない。
            return f.read().strip() == _daily_marker_payload()
    except Exception:
        return False




def _boot_token() -> str:
    """再起動を跨いだ残骸lockを即判定するためのboot識別子。"""
    try:
        if os.name == "nt":
            import ctypes
            uptime_ms = int(ctypes.windll.kernel32.GetTickCount64())
            boot_epoch_min = int((time.time() - uptime_ms / 1000.0) // 60)
            return f"win:{boot_epoch_min}"
        _bp = Path("/proc/sys/kernel/random/boot_id")
        if _bp.exists():
            return "linux:" + _bp.read_text(encoding="utf-8").strip()
    except Exception:
        pass
    return "unknown"


def _pid_is_alive(pid) -> bool:
    try:
        pid = int(pid)
    except Exception:
        return False
    if pid <= 0:
        return False
    if pid == os.getpid():
        return True
    try:
        if os.name == "nt":
            import ctypes
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            h = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
            if h:
                ctypes.windll.kernel32.CloseHandle(h)
                return True
            return False
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except Exception:
        return False


def _text_lock_owner_is_stale(lock_path: str) -> bool:
    try:
        txt = Path(lock_path).read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return False
    _pm = re.search(r"\bpid=(\d+)\b", txt)
    _bm = re.search(r"\bboot=([^\s]+)", txt)
    if _bm:
        old_boot = _bm.group(1)
        cur_boot = _boot_token()
        if old_boot != "unknown" and cur_boot != "unknown" and old_boot != cur_boot:
            return True
    return bool(_pm and not _pid_is_alive(_pm.group(1)))


def _json_lock_owner_is_stale(lock_path: Path) -> bool:
    try:
        data = json.loads(lock_path.read_text(encoding="utf-8"))
    except Exception:
        return False
    old_boot = str(data.get("boot") or "")
    cur_boot = _boot_token()
    if old_boot and old_boot != "unknown" and cur_boot != "unknown" and old_boot != cur_boot:
        return True
    pids = [data.get("pid"), data.get("child_pid")]
    known = [pid for pid in pids if pid is not None]
    return bool(known) and not any(_pid_is_alive(pid) for pid in known)


def _text_lock_owner_is_alive(lock_path: str) -> bool:
    try:
        txt = Path(lock_path).read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return False
    _pm = re.search(r"\bpid=(\d+)\b", txt)
    _bm = re.search(r"\bboot=([^\s]+)", txt)
    if _bm:
        old_boot = _bm.group(1)
        cur_boot = _boot_token()
        if old_boot != "unknown" and cur_boot != "unknown" and old_boot != cur_boot:
            return False
    return bool(_pm and _pid_is_alive(_pm.group(1)))


def _json_lock_owner_is_alive(lock_path: Path) -> bool:
    try:
        data = json.loads(lock_path.read_text(encoding="utf-8"))
    except Exception:
        return False
    old_boot = str(data.get("boot") or "")
    cur_boot = _boot_token()
    if old_boot and old_boot != "unknown" and cur_boot != "unknown" and old_boot != cur_boot:
        return False
    pids = [data.get("pid"), data.get("child_pid")]
    return any(pid is not None and _pid_is_alive(pid) for pid in pids)


def _claim_daily_phase_lock(name: str, stale_seconds: int = 12 * 3600):
    """P1-325: 複数プロセス同時起動でも日次フェーズを1本だけにする原子的lock claim。"""
    marker_path = os.path.join(OUTPUT_DIR, f"last_{name}.txt")
    lock_path = marker_path + ".lock"
    for _ in range(2):
        try:
            fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
            try:
                payload = f"pid={os.getpid()} boot={_boot_token()} started={_now_jst():%Y-%m-%d %H:%M:%S}\n".encode("utf-8")
                os.write(fd, payload)
            finally:
                os.close(fd)
            return lock_path
        except FileExistsError:
            # 完了markerが既に立ったなら競合相手が正常完了済み。
            if _daily_marker_matches_today(name):
                return None
            try:
                _lock_mtime = os.path.getmtime(lock_path)
                age = max(0.0, time.time() - _lock_mtime)
                _lock_day = datetime.fromtimestamp(_lock_mtime, tz=_now_jst().tzinfo).date()
                _today_day = date.fromisoformat(_today_jst())
            except Exception:
                age = 0.0
                _lock_day = _today_day = None
            # P1-330: 前日以前のcrash残骸が翌朝まで12hロックを維持しない。
            # ただし日跨ぎ直後に前日ジョブがまだ生きている可能性を考え、2時間の猶予は残す。
            _cross_day_stale = (
                _lock_day is not None and _today_day is not None
                and _lock_day != _today_day and age > 2 * 3600
            )
            _dead_owner = _text_lock_owner_is_stale(lock_path)
            _live_owner = _text_lock_owner_is_alive(lock_path)
            if _dead_owner or (not _live_owner and (age > float(stale_seconds) or _cross_day_stale)):
                try:
                    os.unlink(lock_path)
                    print(f"[daily-lock] stale lock removed: {name} age={age:.0f}s dead_owner={_dead_owner}")
                    continue
                except Exception:
                    pass
            return None
    return None


def _release_daily_phase_lock(lock_path):
    if not lock_path:
        return
    try:
        os.unlink(lock_path)
    except FileNotFoundError:
        pass
    except Exception as e:
        print(f"[daily-lock][WARN] release failed: {lock_path}: {e}")


def _timed_daily_once(name, func, *args, **kwargs):
    """1日1回だけ実行する関数（タイマー付き・複数プロセス安全）。"""
    marker_path = os.path.join(OUTPUT_DIR, f"last_{name}.txt")
    today_str = _today_jst()
    marker_payload = _daily_marker_payload()

    if _daily_marker_matches_today(name):
        print(f"[SKIP daily] {name} (already ok for {today_str}, build={_daily_build_token()})")
        return

    # P1-325: marker確認→実行の隙間を原子的lockで塞ぐ。
    lock_path = _claim_daily_phase_lock(name)
    if lock_path is None:
        if _daily_marker_matches_today(name):
            print(f"[SKIP daily] {name} (completed by another process for {today_str})")
            return
        # P1-389: 別プロセスが重要フェーズを更新中なのに、この実行だけ先へ進んで
        # 途中状態/旧状態のHTMLを公開しない。
        raise RuntimeError(f"daily phase is currently running in another process: {name}")

    try:
        # claim待ちの間に別プロセスが完了していた場合の二重チェック。
        if _daily_marker_matches_today(name):
            print(f"[SKIP daily] {name} (already ok after lock claim)")
            return

        res = _timed(name, func, *args, **kwargs)
        # P1-502: 日次関数が明示的にFalseを返した場合は成功markerを立てない。
        # 外部/任意phaseが「失敗だが例外は投げない」を返しても、旧実装は当日完了扱いしていた。
        if res is False:
            raise RuntimeError(f"daily phase returned False: {name}")

        # P1-326: 完了markerも直接truncateせずatomic replace。
        try:
            _atomic_write_text_file(marker_path, marker_payload)
        except Exception as e:
            # P1-350: phase本体だけ成功して完了markerの永続化に失敗した状態を
            # 「日次処理成功」として返さない。次回の重複実行リスクも上位へ明示する。
            print(f"[MARKER ERROR] {name} のマーカー保存失敗: {e}")
            raise RuntimeError(f"daily marker persistence failed: {name}") from e
        return res
    finally:
        _release_daily_phase_lock(lock_path)


def _interval_marker_path(name: str) -> Path:
    safe = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(name or "phase")).strip("._") or "phase"
    return SCREEN_RUNTIME_DIR / f"interval_{safe}.json"


def _interval_marker_is_fresh(name: str, interval_seconds: float) -> tuple[bool, float]:
    """P2-93: 同日・同buildで成功済みの中頻度phaseかを判定する。"""
    path = _interval_marker_path(name)
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(raw, dict):
            return False, float("inf")
        if str(raw.get("day") or "") != _today_jst():
            return False, float("inf")
        if str(raw.get("build") or "") != _daily_build_token():
            return False, float("inf")
        completed_at = float(raw.get("completed_at"))
        age = time.time() - completed_at
        if age < -300.0:
            return False, age
        return age < max(0.0, float(interval_seconds)), age
    except Exception:
        return False, float("inf")


def _timed_interval_once(name, interval_seconds, func, *args, **kwargs) -> bool:
    """P2-93: 中頻度phaseを指定間隔に1回だけ実行。失敗時はmarkerを進めない。"""
    fresh, age = _interval_marker_is_fresh(name, interval_seconds)
    if fresh:
        print(
            f"[SKIP interval] {name} "
            f"age={max(0.0, age):.0f}s < {float(interval_seconds):.0f}s"
        )
        return False
    result = _timed(name, func, *args, **kwargs)
    if result is False:
        raise RuntimeError(f"interval phase returned False: {name}")
    payload = {
        "day": _today_jst(),
        "build": _daily_build_token(),
        "completed_at": time.time(),
    }
    path = _interval_marker_path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    _atomic_write_text_file(path, json.dumps(payload, ensure_ascii=False, separators=(",", ":")))
    return True

# ===== /日次実行ログユーティリティ =====

# === V5_ResSup: 抵抗/支持 計算＋HTML出力（静的UI・自然統合） ===============


_V5_N_DAYS = 90
_V5_TOUCH_PCT = 0.03
_V5_TOUCH_MIN = 3
_V5_ROUND_STEPS = [1,5,10,50,100,500,1000,5000,10000]
_V5_SWING_LOOKBACK = 60
# P4-DASH8: 回帰線は表示研究用に保持するが、最寄り支持/抵抗へ採用するのは説明力がある時だけ。
_V5_LINE_MIN_R2 = max(0.0, min(1.0, float(os.environ.get("KABU_V5_LINE_MIN_R2", "0.30"))))
_V5_HISTORY_TABLE = "price_history"
_V5_LATEST_TABLE  = "latest_prices"
_V5_COLS = {
    "Res_HH":"REAL","Res_Zone":"REAL","Res_Zone_Touches":"INTEGER","Res_Zone_Last":"TEXT",
    "Res_Round":"REAL","Res_Round_Step":"INTEGER","Res_Round_Near":"INTEGER",
    "Res_Line_Today":"REAL","Res_Line_R2":"REAL","Res_Nearest":"REAL",
    "Sup_LL":"REAL","Sup_Zone":"REAL","Sup_Zone_Touches":"INTEGER","Sup_Zone_Last":"TEXT",
    "Sup_Round":"REAL","Sup_Round_Step":"INTEGER","Sup_Round_Near":"INTEGER",
    "Sup_Line_Today":"REAL","Sup_Line_R2":"REAL","Sup_Nearest":"REAL",
}

def _v5_q(conn, sql, params=()):
    return list(conn.execute(sql, params))

def _v5_ensure_cols(conn, latest):
    cur = conn.cursor()
    _sp = "p2_65_v5_ensure_cols"
    try:
        cur.execute(f"SAVEPOINT {_sp}")
        existing = {r[1] for r in cur.execute(f"PRAGMA table_info({latest})")}
        for k, decl in _V5_COLS.items():
            if k not in existing:
                cur.execute(f"ALTER TABLE {latest} ADD COLUMN {k} {decl}")
        cur.execute(f"RELEASE SAVEPOINT {_sp}")
    except Exception:
        try:
            cur.execute(f"ROLLBACK TO SAVEPOINT {_sp}")
            cur.execute(f"RELEASE SAVEPOINT {_sp}")
        except Exception:
            pass
        raise
    finally:
        cur.close()

def _v5_unify_code(conn, latest):
    cols = [r[1] for r in _v5_q(conn, f"PRAGMA table_info({latest})")]
    if "コード" in cols:
        return "コード"
    if "code" in cols:
        cur = conn.cursor()
        _sp = "p2_65_v5_unify_code"
        try:
            cur.execute(f"SAVEPOINT {_sp}")
            # P2-16/P2-65: 不存在確認済み。schema migrationは外側transactionをcommitしない。
            cur.execute(f"ALTER TABLE {latest} ADD COLUMN コード TEXT")
            cur.execute(f"UPDATE {latest} SET コード = CAST(code AS TEXT) WHERE コード IS NULL")
            cur.execute(f"RELEASE SAVEPOINT {_sp}")
        except Exception:
            try:
                cur.execute(f"ROLLBACK TO SAVEPOINT {_sp}")
                cur.execute(f"RELEASE SAVEPOINT {_sp}")
            except Exception:
                pass
            raise
        finally:
            cur.close()
        return "コード"
    return cols[0] if cols else "コード"

# --- 安全変換ユーティリティ（None/空/NaN→default） ---
def _v5_num(x, default=None):
    try:
        if x is None:
            return default
        v = float(x)
        if v != v:  # NaN
            return default
        return v
    except Exception:
        return default

def _v5_round_levels(p: float):
    pval = _v5_num(p, None)
    if pval is None:
        return [(0, None, None)]
    out = []
    for step in _V5_ROUND_STEPS:
        if step <= 0:
            continue
        nearest = round(pval / step) * step
        diff = abs(float(nearest) - pval)
        out.append((step, float(nearest), diff))
    out.sort(key=lambda x: (-x[0], x[2]))
    return out

def _v5_hist_zone(
    values,
    band_ratio,
    touch_min,
    ref_price=None
):
    vals = []

    for v in values:
        vv = _v5_num(v, None)
        if vv is not None:
            vals.append(vv)

    if not vals:
        return None

    vals.sort()

    best_center = None
    best_cnt = 0
    best_score = -1

    for i, v in enumerate(vals):

        # P4-DASH8: 旧最低30円幅は低位株で過大。株価比率bandだけで統一する。
        hi = v + abs(v) * band_ratio

        j = i

        while (
            j + 1 < len(vals)
            and vals[j + 1] <= hi
        ):
            j += 1

        cnt = j - i + 1

        if cnt < touch_min:
            continue

        center = sum(vals[i:j+1]) / cnt

        # ----------------------------
        # 距離補正
        # ----------------------------

        if ref_price is not None:

            distance = abs(center - ref_price) / ref_price
            # 現在値から遠い帯を強く減点
            score = cnt / (1 + distance * 20)

        else:

            score = cnt

        if score > best_score:

            best_score = score
            best_cnt = cnt
            best_center = center

    if best_center is None:
        return None

    return (best_center, best_cnt)

def _v5_linreg_today(xs, ys):
    xs2, ys2 = [], []
    for x, y in zip(xs, ys):
        yy = _v5_num(y, None)
        if yy is not None:
            xs2.append(float(x))
            ys2.append(yy)
    n = len(xs2)
    if n < 5:
        return (None, None)
    mx = sum(xs2) / n
    my = sum(ys2) / n
    sxx = sum((x - mx) ** 2 for x in xs2)
    if sxx == 0:
        return (None, None)
    sxy = sum((x - mx) * (y - my) for x, y in zip(xs2, ys2))
    a = sxy / sxx
    b = my - a * mx
    yhat = [a * x + b for x in xs2]
    sst = sum((y - my) ** 2 for y in ys2)
    ssr = sum((yh - my) ** 2 for yh in yhat)
    r2 = (ssr / sst) if sst else None
    y_today = a * (xs2[-1] + 1) + b
    return (float(y_today), (float(r2) if r2 is not None else None))

def _v5_fetch_ohlcv(conn, code, cutoff_date=None):
    # P1-279: legacy/canonicalを横断し、同一日alias重複を1本へ畳んで返す。
    # P1-532: P1-158以前のlegacy未来日（平日）をV5支持抵抗の「最新足」にしない。
    # P1-575: V5もrun mode基準のsnapshot日を使う。PREOPENは前営業日、MIDDAY/EODは当日。
    # _dedupe_price_history_df() は休日行を落とすが、未来の平日は別途as-of cutoffが必要。
    _vars = code_query_variants(code)
    if not _vars:
        return []
    _ph = ",".join("?" * len(_vars))
    if cutoff_date is None:
        cutoff_date = _expected_snapshot_date_for_run(_auto_run_mode())
    _cutoff = pd.to_datetime(cutoff_date).date().isoformat()
    df = pd.read_sql_query(f"""
        SELECT rowid AS _rowid, コード, 日付, 始値, 高値, 安値, 終値
        FROM {_V5_HISTORY_TABLE}
        WHERE CAST(コード AS TEXT) IN ({_ph})
          AND date(日付) <= date(?)
        ORDER BY 日付 ASC, rowid ASC
    """, conn, params=_vars + [_cutoff])
    df = _dedupe_price_history_df(df)
    # P1-676: 技術計算の観測日は「有効な正の終値」がある行だけ。
    # 日付placeholder(終値NULL/0/非有限)を1営業日として数えてV5支持抵抗を再生成しない。
    if not df.empty:
        df["終値"] = pd.to_numeric(df["終値"], errors="coerce")
        df = df[df["終値"].notna() & np.isfinite(df["終値"]) & (df["終値"] > 0)].copy()
    if df.empty:
        return []
    return list(df[["日付","始値","高値","安値","終値"]].itertuples(index=False, name=None))
    
def _v5_calc(rows, code=None):
    keys = list(_V5_COLS.keys())

    if not rows:
        return {k: None for k in keys}

    rows = rows[-_V5_N_DAYS:]

    dates = [r[0] for r in rows]
    highs = [_v5_num(r[2], None) for r in rows]
    lows  = [_v5_num(r[3], None) for r in rows]

    close_today = _v5_num(rows[-1][4], None)

    res_hh = max([v for v in highs if v is not None], default=None)
    sup_ll = min([v for v in lows if v is not None], default=None)

    # --------------------------------------------------
    # 支持帯・抵抗帯は現在値基準で探索
    # --------------------------------------------------

    if close_today is not None:

        highs_above = [
            h for h in highs
            if h is not None and h > close_today
        ]

        lows_below = [
            l for l in lows
            if l is not None and l < close_today
        ]

    else:
        highs_above = []
        lows_below = []

    zr = _v5_hist_zone(
        highs_above,
        _V5_TOUCH_PCT,
        _V5_TOUCH_MIN,
        close_today
    )

    zs = _v5_hist_zone(
        lows_below,
        _V5_TOUCH_PCT,
        _V5_TOUCH_MIN,
        close_today
    )

    res_zone, res_touch = (
        (zr[0], zr[1]) if zr else (None, None)
    )

    sup_zone, sup_touch = (
        (zs[0], zs[1]) if zs else (None, None)
    )

    # --------------------------------------------------
    # 最終接触日
    # --------------------------------------------------

    res_last = None

    if res_zone is not None:

        for i in range(len(rows) - 1, -1, -1):

            hi = highs[i]

            if hi is None:
                continue

            if abs(hi - res_zone) <= res_zone * _V5_TOUCH_PCT:
                res_last = dates[i]
                break

    sup_last = None

    if sup_zone is not None:

        for i in range(len(rows) - 1, -1, -1):

            lo = lows[i]

            if lo is None:
                continue

            if abs(lo - sup_zone) <= sup_zone * _V5_TOUCH_PCT:
                sup_last = dates[i]
                break

    # --------------------------------------------------
    # キリ番
    # --------------------------------------------------

    rl = _v5_round_levels(close_today)

    step, nearest, _ = (
        rl[0]
        if rl and rl[0][1] is not None
        else (None, None, None)
    )

    res_round_step = step
    sup_round_step = step

    res_round = nearest
    sup_round = nearest

    if close_today is None or nearest is None:
        near_flag = None
    else:
        near_flag = (
            1
            if abs(close_today - nearest)
            <= close_today * _V5_TOUCH_PCT
            else 0
        )

    # --------------------------------------------------
    # 回帰線
    # --------------------------------------------------

    sw = rows[-_V5_SWING_LOOKBACK:]

    xs = list(range(len(sw)))

    rh = [_v5_num(r[2], None) for r in sw]
    rl_ = [_v5_num(r[3], None) for r in sw]

    res_line_today, res_r2 = _v5_linreg_today(xs, rh)
    sup_line_today, sup_r2 = _v5_linreg_today(xs, rl_)

    # --------------------------------------------------
    # 20日・60日高安
    # --------------------------------------------------

    high20 = max(
        [v for v in highs[-20:] if v is not None],
        default=None
    )

    high60 = max(
        [v for v in highs[-60:] if v is not None],
        default=None
    )

    low20 = min(
        [v for v in lows[-20:] if v is not None],
        default=None
    )

    low60 = min(
        [v for v in lows[-60:] if v is not None],
        default=None
    )

    # --------------------------------------------------
    # 最寄り支持・抵抗
    # --------------------------------------------------
    # P4-DASH8: 回帰線raw値/R²は残すが、低R²線は売買用の「最寄り」候補に採用しない。
    trusted_res_line = res_line_today if (res_line_today is not None and res_r2 is not None and res_r2 >= _V5_LINE_MIN_R2) else None
    trusted_sup_line = sup_line_today if (sup_line_today is not None and sup_r2 is not None and sup_r2 >= _V5_LINE_MIN_R2) else None

    if close_today is None:

        res_near = None
        sup_near = None

    else:

        up_candidates = [

            res_zone,
            res_hh,
            high20,
            high60,
            trusted_res_line,

        ]

        up_candidates = [

            v
            for v in up_candidates
            if v is not None and v > close_today

        ]

        dn_candidates = [

            sup_zone,
            sup_ll,
            low20,
            low60,
            trusted_sup_line,

        ]

        dn_candidates = [

            v
            for v in dn_candidates
            if v is not None and v < close_today

        ]

        res_near = (
            min(
                up_candidates,
                key=lambda x: abs(x - close_today)
            )
            if up_candidates
            else None
        )

        sup_near = (
            min(
                dn_candidates,
                key=lambda x: abs(x - close_today)
            )
            if dn_candidates
            else None
        )

    if str(code) == "5074":

        print("=" * 80)
        print("DEBUG 5074")

        print("close_today =", close_today)

        print("highs_above =", highs_above[-20:])
        print("lows_below  =", lows_below[-20:])

        print("zr =", zr)
        print("zs =", zs)

        print("up_candidates =", up_candidates)
        print("dn_candidates =", dn_candidates)

        print("res_zone =", res_zone)
        print("sup_zone =", sup_zone)

        print("res_near =", res_near)
        print("sup_near =", sup_near)

        print("=" * 80)
        
    return {

        "Res_HH": res_hh,

        "Res_Zone": res_zone,
        "Res_Zone_Touches": res_touch,
        "Res_Zone_Last": res_last,

        "Res_Round": res_round,
        "Res_Round_Step": res_round_step,
        "Res_Round_Near": near_flag,

        "Res_Line_Today": res_line_today,
        "Res_Line_R2": res_r2,

        "Res_Nearest": res_near,

        "Sup_LL": sup_ll,

        "Sup_Zone": sup_zone,
        "Sup_Zone_Touches": sup_touch,
        "Sup_Zone_Last": sup_last,

        "Sup_Round": sup_round,
        "Sup_Round_Step": sup_round_step,
        "Sup_Round_Near": near_flag,

        "Sup_Line_Today": sup_line_today,
        "Sup_Line_R2": sup_r2,

        "Sup_Nearest": sup_near,
    }
def _v5_update_latest(conn, latest):
    _v5_ensure_cols(conn, latest)
    code_col = _v5_unify_code(conn, latest)
    codes = [r[0] for r in _v5_q(conn, f"SELECT {code_col} FROM {latest}")]
    if not codes:
        return 0

    # P1-533: 計算途中の例外でlatest_pricesを半分だけ新V5値へ更新しない。
    # まず全銘柄をメモリ上で計算し、全件成功後に1 SAVEPOINTで反映する。
    # P1-575: export直前のV5再計算が、phase_resistance_updateで消したstale支持抵抗を
    # 復活させないよう、個別の最終価格日がrun mode基準日と一致する銘柄だけ計算する。
    # 不一致/履歴なしは全V5列をNULLにし、成功した古い計算結果をcurrent-runへ混入させない。
    _v5_expected_date = _expected_snapshot_date_for_run(_auto_run_mode())
    _v5_expected = _v5_expected_date.isoformat()
    params_rows = []
    for code in codes:
        _rows = _v5_fetch_ohlcv(conn, code, cutoff_date=_v5_expected_date)
        _last_date = str(_rows[-1][0])[:10] if _rows else None
        if _rows and _last_date == _v5_expected:
            vals = _v5_calc(_rows, code)
        else:
            vals = {k: None for k in _V5_COLS.keys()}
        params_rows.append([vals[k] for k in _V5_COLS.keys()] + [code])

    set_clause = ",".join([f"{k}=?" for k in _V5_COLS.keys()])
    sql = f"UPDATE {latest} SET {set_clause} WHERE {code_col}=?"
    sp = "sp_v5_update_latest"
    try:
        conn.execute(f"SAVEPOINT {sp}")
        conn.executemany(sql, params_rows)
        conn.execute(f"RELEASE SAVEPOINT {sp}")
    except Exception:
        try:
            conn.execute(f"ROLLBACK TO SAVEPOINT {sp}")
            conn.execute(f"RELEASE SAVEPOINT {sp}")
        except Exception:
            pass
        raise
    return len(params_rows)

