# P1-390: スクリーナー本体全体をOSレベルで排他。
# 個別phase lockだけでは、fetch_all終了後のDB計算/HTML生成が別起動と重なり得る。
def _acquire_main_process_lock():
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    lock_path = os.path.join(OUTPUT_DIR, ".screening_main_process.lock")
    fh = open(lock_path, "a+b")
    try:
        fh.seek(0, os.SEEK_END)
        if fh.tell() == 0:
            fh.write(b"0")
            fh.flush()
        fh.seek(0)
        if os.name == "nt":
            import msvcrt
            try:
                msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
            except OSError as e:
                raise RuntimeError("another screening process is already running") from e
            return (fh, "nt")
        else:
            import fcntl
            try:
                fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            except OSError as e:
                raise RuntimeError("another screening process is already running") from e
            return (fh, "posix")
    except Exception:
        try: fh.close()
        except Exception: pass
        raise

def _release_main_process_lock(token):
    if not token:
        return
    fh, kind = token
    try:
        fh.seek(0)
        if kind == "nt":
            import msvcrt
            msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
        else:
            import fcntl
            fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
    finally:
        try: fh.close()
        except Exception: pass

